  const [generationHistory, setGenerationHistory] = useState<
    GenerationHistoryItem[]
  >(() => {
    try {
      const storedHistory = sessionStorage.getItem(SESSION_HISTORY_KEY);
      if (storedHistory) {
        const storedItems: StoredHistoryItem[] = JSON.parse(storedHistory);
        return storedItems.map((storedItem) => ({
          id: storedItem.id,
          thumbnailUrl: storedItem.thumbnailUrl,
          item: {
            videoUrl: null,
            blob: null,
            video: {uri: storedItem.videoUri} as Video,
            config: {
              ...storedItem.config,
            } as GenerateVideoParams,
          },
        }));
      }
