      setLastConfig(params);
      setInitialFormValues(null);

      try {
        const {objectUrl, blob, video} = await generateVideo(params);

        // Add to history, wrapping thumbnail creation to prevent it from failing the whole process.
        let thumbnailUrl: string | undefined;
        try {
          thumbnailUrl = await createThumbnail(objectUrl);
        } catch (error) {
          console.error(
