  // API Key State
  const [apiKey, setApiKey] = useState<string>('');
  const [isApiKeyModalOpen, setIsApiKeyModalOpen] = useState<boolean>(false);

  // Narration state
  const [narrationText, setNarrationText] = useState<string>('<speak>\n  Hello! This is a demo of SSML. \n  You can <emphasis level="strong">emphasize</emphasis> words, \n  or take a short pause <break time="1500ms"/> before continuing.\n  You can also change the <prosody rate="slow" pitch="-1st">pitch and rate to be extremely fast or slow or faster or slower</prosody> of the voice.\n</speak>');
  const [narrationVoiceKey, setNarrationVoiceKey] = useState<string>('Charon (Deep Male)');
  const [narrationVoiceStyle, setNarrationVoiceStyle] = useState<string>(narrationPrebuiltVoices['Charon (Deep Male)'].description);
  const [narrationBaseVoice, setNarrationBaseVoice] = useState<string>('Charon');
  const [narrationLanguage, setNarrationLanguage] = useState<string>('English (US)');
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [generationStatus, setGenerationStatus] = useState<string>('');
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const [audioBlob, setAudioBlob] = useState<globalThis.Blob | null>(null);

  // FIX: Updated 'LiveSession' type to 'any' as it's not an exported member of '@google/genai'.
  const sessionRef = useRef<any | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const nextStartTimeRef = useRef<number>(0);
  const currentInputTranscriptionRef = useRef<string>('');
  const currentOutputTranscriptionRef = useRef<string>('');

  useEffect(() => {
    const storedKey = localStorage.getItem('gemini_api_key');
    if (storedKey) {
      setApiKey(storedKey);
    } else if (process.env.API_KEY) {
        // Fallback to env var if available (local dev)
        setApiKey(process.env.API_KEY);
    } else {
      setIsApiKeyModalOpen(true);
    }
  }, []);

  const handleSaveApiKey = (key: string) => {
    localStorage.setItem('gemini_api_key', key);
    setApiKey(key);
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) {
      sessionRef.current.close();
      sessionRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => track.stop());
      streamRef.current = null;
    }
    if (scriptProcessorRef.current) {
      scriptProcessorRef.current.disconnect();
      scriptProcessorRef.current = null;
    }
    if (inputAudioContextRef.current && inputAudioContextRef.current.state !== 'closed') {
      inputAudioContextRef.current.close();
      inputAudioContextRef.current = null;
    }
    if (outputAudioContextRef.current && outputAudioContextRef.current.state !== 'closed') {
      sourcesRef.current.forEach(source => source.stop());
      sourcesRef.current.clear();
      outputAudioContextRef.current.close();
      outputAudioContextRef.current = null;
    }

    setIsSessionActive(false);
    setTranscript([]);
    console.log('Session stopped and resources cleaned up.');
  }, []);

  const startSession = async () => {
    setError(null);
    setTranscript([]);

    if (!apiKey) {
      setIsApiKeyModalOpen(true);
      return;
    }

    setIsSessionActive(true);

    try {
      const ai = new GoogleGenAI({ apiKey: apiKey });

      const systemInstruction = `You are a helpful AI assistant. You must speak aloud. Your tone should be ${emotion === 'Inquisitive' ? 'Pro-Actively Curious and Investigative Natured' : emotion}. Your speaking style should be ${style}. ${customVoice ? customVoice.instruction : ''}`;

      inputAudioContextRef.current = new ((window as any).AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new ((window as any).AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      nextStartTimeRef.current = 0;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: (customVoice && voice === customVoice.name) ? customVoice.baseVoice : voice } },
          },
          systemInstruction: systemInstruction,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
        },
        callbacks: {
          onopen: async () => {
            console.log('Session opened.');
            streamRef.current = await navigator.mediaDevices.getUserMedia({ audio: true });
            const source = inputAudioContextRef.current!.createMediaStreamSource(streamRef.current);
            scriptProcessorRef.current = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);

            scriptProcessorRef.current.onaudioprocess = (audioProcessingEvent) => {
              const inputData = audioProcessingEvent.inputBuffer.getChannelData(0);
              const pcmBlob: Blob = {
                data: encode(new Uint8Array(new Int16Array(inputData.map(f => f * 32768)).buffer)),
                mimeType: 'audio/pcm;rate=16000',
              };
              sessionPromise.then((session) => {
                session.sendRealtimeInput({ media: pcmBlob });
              });
            };
            source.connect(scriptProcessorRef.current);
            scriptProcessorRef.current.connect(inputAudioContextRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.serverContent?.inputTranscription) {
              const { text } = message.serverContent.inputTranscription;
              currentInputTranscriptionRef.current += text;

              setTranscript(prev => {
                const last = prev[prev.length - 1];
                if (last && last.speaker === 'user' && !last.isFinal) {
                  const updated = { ...last, text: currentInputTranscriptionRef.current };
                  return [...prev.slice(0, -1), updated];
                }
                return [...prev, { speaker: 'user', text: currentInputTranscriptionRef.current, isFinal: false }];
              });
            }

            if (message.serverContent?.outputTranscription) {
              const { text } = message.serverContent.outputTranscription;
              currentOutputTranscriptionRef.current += text;
              setTranscript(prev => {
                const last = prev[prev.length - 1];
                if (last && last.speaker === 'model' && !last.isFinal) {
                  const updated = { ...last, text: currentOutputTranscriptionRef.current };
                  return [...prev.slice(0, -1), updated];
                }
                // Add a new model message if the last one isn't an unfinished model message
                if (!last || last.speaker !== 'model' || last.isFinal) {
                  return [...prev, { speaker: 'model', text: currentOutputTranscriptionRef.current, isFinal: false }];
                }
                return prev;
              });
            }

            if (message.serverContent?.turnComplete) {
                setTranscript(prev => {
                    const newTranscript = [...prev];
                    // FIX: Property 'findLastIndex' does not exist on type 'any[]'. Replaced with a for loop for compatibility.
                    let lastUserIndex = -1;
                    for (let i = newTranscript.length - 1; i >= 0; i--) {
                        if (newTranscript[i].speaker === 'user') {
                            lastUserIndex = i;
                            break;
                        }
                    }
                    if (lastUserIndex > -1 && !newTranscript[lastUserIndex].isFinal) {
                      newTranscript[lastUserIndex] = {...newTranscript[lastUserIndex], isFinal: true };
                    }
                    // FIX: Property 'findLastIndex' does not exist on type 'any[]'. Replaced with a for loop for compatibility.
                    let lastModelIndex = -1;
                    for (let i = newTranscript.length - 1; i >= 0; i--) {
                        if (newTranscript[i].speaker === 'model') {
                            lastModelIndex = i;
                            break;
                        }
                    }
                    if (lastModelIndex > -1 && !newTranscript[lastModelIndex].isFinal) {
                      newTranscript[lastModelIndex] = {...newTranscript[lastModelIndex], isFinal: true };
                    }
                    return newTranscript;
                });
                currentInputTranscriptionRef.current = '';
                currentOutputTranscriptionRef.current = '';
            }

            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              const audioContext = outputAudioContextRef.current!;
              const decodedAudio = decode(base64Audio);
              const audioBuffer = await decodeAudioData(decodedAudio, audioContext, 24000, 1);
              const source = audioContext.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(audioContext.destination);

              const currentTime = audioContext.currentTime;
              const startTime = Math.max(currentTime, nextStartTimeRef.current);
              source.start(startTime);

              nextStartTimeRef.current = startTime + audioBuffer.duration;
              sourcesRef.current.add(source);
              source.onended = () => {
                sourcesRef.current.delete(source);
              };
            }
          },
          onerror: (err: ErrorEvent) => {
            console.error('Session error:', err);
            setError(`Session error: ${err.message}`);
            stopSession();
          },
          onclose: () => {
            console.log('Session closed.');
            stopSession();
          },
        },
      });

      sessionRef.current = await sessionPromise;

    } catch (err: any) {
      console.error('Failed to start session:', err);
      setError(`Failed to start session: ${err.message}`);
      setIsSessionActive(false);
    }
  };

  const handleSaveCustomVoice = (newCustomVoice: CustomVoice) => {
    setCustomVoice(newCustomVoice);
    setVoice(newCustomVoice.name); // Auto-select the new voice
    setIsCustomVoiceModalOpen(false);
  };

  // Helper to chunk text
  const splitTextIntoChunks = (text: string): string[] => {
    // 1. Remove outer <speak> tags if present to avoid nesting issues
    let cleanText = text.trim();
    if (cleanText.startsWith('<speak>')) cleanText = cleanText.slice(7);
    if (cleanText.endsWith('</speak>')) cleanText = cleanText.slice(0, -8);
    cleanText = cleanText.trim();

    // 2. Split by double newline (paragraphs)
    return cleanText.split(/\n\s*\n/).filter(chunk => chunk.trim().length > 0);
  };

  const generateNarration = async () => {
    setIsGenerating(true);
    setGenerationStatus('Preparing...');
    setError(null);
    setAudioUrl(null);
    setAudioBlob(null);

    if (!apiKey) {
      setIsApiKeyModalOpen(true);
      setIsGenerating(false);
      return;
    }

    try {
      const ai = new GoogleGenAI({ apiKey: apiKey });

      const chunks = splitTextIntoChunks(narrationText);
      const audioParts: Uint8Array[] = [];

      const languageFullName = narrationLanguage;
      const language = languageFullName.split(' ')[0];
      const isTranslation = !languageFullName.startsWith('English');

      for (let i = 0; i < chunks.length; i++) {
        setGenerationStatus(`Processing part ${i + 1} of ${chunks.length}...`);

        // Wrap current chunk in speak tags
        let textChunk = `<speak>${chunks[i]}</speak>`;
        let textToSpeak = textChunk;

        // STEP 1: Handle translation for this chunk
        if (isTranslation) {
           setGenerationStatus(`Translating part ${i + 1} of ${chunks.length}...`);
           const translationResponse = await ai.models.generateContent({
             model: 'gemini-2.5-flash',
             contents: `Translate the following script to ${language}. The script might contain SSML tags for speech synthesis. It is crucial that you preserve these SSML tags (like <speak>, <prosody>, <emphasis>, <break>) exactly as they are in the output. Only translate the text content within the tags. Script: ${textChunk}`,
           });
           textToSpeak = translationResponse.text.trim();
        }

        setGenerationStatus(`Generating audio for part ${i + 1} of ${chunks.length}...`);

        // STEP 2: Generate Audio
        // We now enforce the base voice (Charon/Kore/etc) via speechConfig for ALL requests.
        // This ensures gender consistency (e.g., Male) even when using custom descriptions or translations.
        const voiceName = narrationBaseVoice; 

        let ttsPromptText = '';
        const isAdHocCustom = narrationVoiceKey === 'custom'; // User has edited the text area

        if (isAdHocCustom) {
            // User modified the style. Send detailed instruction + Text
            let accentInstruction = '';
            if (languageFullName === 'English (UK)') {
                accentInstruction = 'Use a standard British English accent.';
            } else if (languageFullName === 'English (India)') {
                accentInstruction = 'Use a standard Indian English accent.';
            }
             ttsPromptText = `Use a voice with these characteristics: "${narrationVoiceStyle}". ${accentInstruction} Read the following script aloud. The script may contain SSML. Script: ${textToSpeak}`;
        } else {
             // Standard preset. Send Text (with accent instruction if needed)
             ttsPromptText = textToSpeak;
             if (languageFullName === 'English (UK)') {
                ttsPromptText = `Read the following script with a standard British English accent. Script: ${textToSpeak}`;
             } else if (languageFullName === 'English (India)') {
                ttsPromptText = `Read the following script with a standard Indian English accent. Script: ${textToSpeak}`;
             }
        }

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-preview-tts',
            contents: [{ parts: [{ text: ttsPromptText }] }],
            config: {
              responseModalities: [Modality.AUDIO],
              speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName } } },
            },
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (base64Audio) {
           audioParts.push(decode(base64Audio));
        } else {
           console.warn(`Part ${i + 1} returned no audio.`);
        }
      }

      if (audioParts.length === 0) {
        throw new Error("No audio generated.");
      }

      setGenerationStatus('Stitching audio...');
      const combinedPcm = concatenateBuffers(audioParts);
      const wavBlob = pcmToWavBlob(combinedPcm, 24000, 1);
      const url = URL.createObjectURL(wavBlob);
      setAudioUrl(url);
      setAudioBlob(wavBlob);

    } catch (err: any) {
      console.error("Error generating narration:", err);
      setError(`Narration generation failed: ${err.message}`);
    } finally {
      setIsGenerating(false);
      setGenerationStatus('');
    }
  };


  const allVoices = ['Zephyr', 'Puck', 'Kore', 'Charon', 'Fenrir'];
  if (customVoice && !allVoices.includes(customVoice.name)) {
    allVoices.unshift(customVoice.name);
  }

  const allNarrationVoices: {[key: string]: {description: string, voiceName?: string}} = { ...narrationPrebuiltVoices };
  if (customVoice) {
    allNarrationVoices[customVoice.name] = { description: customVoice.instruction };
  }
  const narrationLanguages = [
    'English (US)', 'English (UK)', 'English (India)', 
    'Spanish', 'French', 'German', 'Hindi', 'Japanese', 'Korean', 'Thai', 'Chinese', 'Italian', 'Russian',
    'Maltese', 'Lao', 'Khmer', 'Sanskrit', 'Tamil', 'Latin', 'Greek', 'Catalan', 'Portuguese', 'Georgian', 'Nepali', 'Sinhala'
  ];

  const handleNarrationVoiceChange = (selectedKey: string) => {
    setNarrationVoiceKey(selectedKey);
    const preset = narrationPrebuiltVoices[selectedKey];
    if (preset) {
        setNarrationVoiceStyle(preset.description);
        setNarrationBaseVoice(preset.voiceName);
    } else if (customVoice && selectedKey === customVoice.name) {
        setNarrationVoiceStyle(customVoice.instruction);
        setNarrationBaseVoice(customVoice.baseVoice);
    }
  };

  const renderConversationMode = () => (
    <>
      <div className="flex-grow w-full max-w-4xl mx-auto p-4 overflow-y-auto">
          <div className="space-y-6">
            {transcript.length === 0 && (
              <div className="text-center text-gray-400 pt-20">
                <h1 className="text-4xl font-bold text-teal-300">Conversational AI</h1>
                <p className="mt-2">Press the microphone to start talking.</p>
              </div>
            )}
            {transcript.map((msg, index) => (
              <div key={index} className={`flex items-start gap-4 ${msg.speaker === 'user' ? 'justify-end' : ''}`}>
                <div className={`p-2 rounded-full ${msg.speaker === 'model' ? 'bg-teal-500' : 'bg-gray-600'}`}>
                  {msg.speaker === 'model' ? <SparklesIcon className="w-6 h-6 text-white"/> : <UserIcon className="w-6 h-6 text-white"/>}
                </div>
                <div className={`max-w-prose p-4 rounded-xl ${msg.speaker === 'model' ? 'bg-gray-700' : 'bg-teal-800'}`}>
                  <p className={`text-white ${!msg.isFinal ? 'opacity-70' : ''}`}>{msg.text}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
        <footer className="w-full bg-gray-900/80 backdrop-blur-sm border-t border-gray-700 p-4">
          <div className="max-w-4xl mx-auto">
            <div className="flex justify-center mb-4">
              <button
                onClick={isSessionActive ? stopSession : startSession}
                className={`p-4 rounded-full transition-all duration-300 ${isSessionActive ? 'bg-red-600 hover:bg-red-700 scale-110' : 'bg-teal-500 hover:bg-teal-600'}`}
                aria-label={isSessionActive ? 'Stop Session' : 'Start Session'}
              >
                {isSessionActive ? <StopCircleIcon className="w-10 h-10 text-white" /> : <MicrophoneIcon className="w-10 h-10 text-white" />}
              </button>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4 text-white">
                <div>
                  <label htmlFor="emotion" className="block text-sm font-medium text-gray-400 mb-1">AI Tone</label>
                  <select id="emotion" value={emotion} onChange={(e) => setEmotion(e.target.value)} disabled={isSessionActive} className="w-full bg-gray-700 border border-gray-600 rounded-md p-2 text-sm focus:ring-teal-500 focus:border-teal-500 disabled:opacity-50">
                    <option>Neutral</option>
                    <option>Happy</option>
                    <option>Sad</option>
                    <option>Enthusiastic</option>
                    <option>Serious</option>
                    <option value="Pro-Actively Curious and Investigative Natured">Inquisitive</option>
                    <option value="Proactive Agentic Suggestive Teacher">Teacher</option>
                  </select>
                </div>
                <div>
                  <label htmlFor="style" className="block text-sm font-medium text-gray-400 mb-1">AI Style</label>
                  <select id="style" value={style} onChange={(e) => setStyle(e.target.value)} disabled={isSessionActive} className="w-full bg-gray-700 border border-gray-600 rounded-md p-2 text-sm focus:ring-teal-500 focus:border-teal-500 disabled:opacity-50">
                    <option>Conversational</option>
                    <option>Formal</option>
                    <option>Narrative</option>
                    <option value="Official Executive Professional Advisor Consultant Expert">Expert Advisor</option>
                  </select>
                </div>
                <div>
                  <label htmlFor="voice" className="block text-sm font-medium text-gray-400 mb-1">AI Voice</label>
                  <select id="voice" value={voice} onChange={(e) => setVoice(e.target.value)} disabled={isSessionActive} className="w-full bg-gray-700 border border-gray-600 rounded-md p-2 text-sm focus:ring-teal-500 focus:border-teal-500 disabled:opacity-50">
                     {allVoices.map(v => <option key={v} value={v}>{v}</option>)}
                  </select>
                </div>
                <div>
                   <label className="block text-sm font-medium text-gray-400 mb-1 opacity-0 pointer-events-none">Custom</label>
                   <button onClick={() => setIsCustomVoiceModalOpen(true)} disabled={isSessionActive} className="w-full flex items-center justify-center gap-2 bg-teal-600 hover:bg-teal-700 rounded-md p-2 text-sm disabled:opacity-50 disabled:bg-gray-600 transition-colors">
                     <PlusIcon className="w-4 h-4" /> Create Custom Voice
                   </button>
                </div>
            </div>
          </div>
        </footer>
    </>
  );

  const renderNarrationMode = () => {
    return (
    <div className="flex-grow w-full max-w-4xl mx-auto p-4 flex flex-col gap-4 overflow-y-auto">

        <div className="flex-grow flex flex-col gap-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 <div>
                    <label htmlFor="narrationLanguage" className="block text-sm font-medium text-gray-300 mb-1">Language & Accent</label>
                    <p className="text-xs text-gray-500 -mt-1 mb-1">Translates script or applies a regional accent.</p>
                    <select
                    id="narrationLanguage"
                    value={narrationLanguage}
                    onChange={(e) => setNarrationLanguage(e.target.value)}
                    className="w-full bg-gray-800 border border-gray-600 rounded-md p-2 text-white focus:ring-teal-500 focus:border-teal-500"
                    disabled={isGenerating}
                    >
                    {narrationLanguages.map(lang => <option key={lang} value={lang}>{lang}</option>)}
                    </select>
                </div>
                <div>
                    <label htmlFor="narrationVoice" className="block text-sm font-medium text-gray-300 mb-1">Voice Preset</label>
                     <p className="text-xs text-gray-500 -mt-1 mb-1">Choose a base voice style for the narration.</p>
                    <select
                        id="narrationVoice"
                        value={narrationVoiceKey}
                        onChange={(e) => handleNarrationVoiceChange(e.target.value)}
                        className="w-full bg-gray-800 border border-gray-600 rounded-md p-2 text-white focus:ring-teal-500 focus:border-teal-500"
                        disabled={isGenerating}
                        >
                        {Object.keys(allNarrationVoices).map((name) => <option key={name} value={name}>{name.replace('(Custom)', '').trim()}</option>)}
                        {narrationVoiceKey === 'custom' && <option value="custom" disabled>Custom</option>}
                    </select>
                </div>
            </div>

            <div>
                <label htmlFor="narrationVoiceStyle" className="block text-sm font-medium text-gray-300 mb-1">Voice Style Description (Editable)</label>
                <textarea
                    id="narrationVoiceStyle"
                    rows={3}
                    value={narrationVoiceStyle}
                    onChange={(e) => {
                      setNarrationVoiceStyle(e.target.value);
                      const isPrebuilt = !!narrationPrebuiltVoices[narrationVoiceKey];
                      const isCustom = customVoice && narrationVoiceKey === customVoice.name;
                      if (isPrebuilt || isCustom) {
                         // A change to a preset voice's description makes it a custom style
                         setNarrationVoiceKey('custom');
                         // We do NOT update the narrationBaseVoice here, so it retains the base of whatever we started editing from.
                      }
                    }}
                    className="w-full bg-gray-800 border border-gray-600 rounded-md p-2 text-white focus:ring-teal-500 focus:border-teal-500 font-sans text-sm"
                    placeholder="e.g., A deep male voice with a calm, narrative tone."
                    disabled={isGenerating}
                />
            </div>

            <div>
                 <label htmlFor="narrationText" className="block text-sm font-medium text-gray-300 mb-1">Script with SSML Control</label>
                 <textarea
                    id="narrationText"
                    value={narrationText}
                    onChange={(e) => setNarrationText(e.target.value)}
                    className="w-full h-56 bg-gray-800 border border-gray-600 rounded-md p-3 text-white font-mono text-sm focus:ring-teal-500 focus:border-teal-500"
                    placeholder="Enter your script here. You can use SSML for fine-tuned control."
                    disabled={isGenerating}
                />
                 <details className="text-xs text-gray-400 mt-2">
                    <summary className="cursor-pointer hover:text-white">SSML Quick Reference</summary>
                    <div className="p-2 bg-gray-800/50 rounded-md mt-1 font-mono">
                        <p className="mb-1"><strong className="text-teal-400">Pause:</strong> {'<break time="500ms"/>'}</p>
                        <p className="mb-1"><strong className="text-teal-400">Emphasis:</strong> {'<emphasis level="strong">word</emphasis>'}</p>
                        <p><strong className="text-teal-400">Prosody:</strong> {'<prosody rate="slow" pitch="-10%">text</prosody>'}</p>
                    </div>
                 </details>
            </div>

            <div className="flex justify-center">
                 <button 
                    onClick={generateNarration} 
                    disabled={isGenerating || !narrationText}
                    className="px-8 py-3 rounded-md bg-teal-600 hover:bg-teal-700 disabled:bg-gray-500 disabled:cursor-not-allowed transition-colors flex items-center font-bold text-lg"
                >
                    {isGenerating ? (
                        <>
                            <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w.org/2000/svg" fill="none" viewBox="0 0 24 24">
                                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                            </svg>
                            {generationStatus}
                        </>
                    ) : "Generate Audio"}
                </button>
            </div>
        </div>

        {audioUrl && (
            <div className="mt-4 p-4 bg-gray-700 rounded-lg">
                <h3 className="text-lg font-semibold mb-2 text-teal-300">Generated Audio</h3>
                <audio controls src={audioUrl} className="w-full"></audio>
                <a 
                    href={audioUrl} 
                    download={`narration-${Date.now()}.wav`}
                    className="mt-3 inline-block w-full text-center px-4 py-2 rounded-md bg-teal-500 hover:bg-teal-600 transition-colors"
                >
                    Download .wav File
                </a>
            </div>
        )}
    </div>
    );
  };

  return (
    <main className="bg-gray-900 text-white h-screen flex flex-col font-sans">
      <header className="w-full bg-gray-800/80 backdrop-blur-sm border-b border-gray-700 p-4 flex flex-col items-center relative z-10 gap-4">
        <h1 className="text-3xl font-bold text-cyan-300 font-orbitron" style={{ textShadow: '0 0 8px rgba(56, 249, 215, 0.5)' }}>
            Endless Text Narrator
        </h1>
        <div className="w-full flex justify-between items-center max-w-sm">
            <div className="flex-1"></div>
            <div className="inline-flex bg-gray-700 rounded-md p-1">
                <button 
                  onClick={() => setMode('conversation')}
                  className={`px-4 py-1 text-sm font-semibold rounded ${mode === 'conversation' ? 'bg-teal-600 text-white' : 'text-gray-300 hover:bg-gray-600'}`}
                >
                  Conversation
                </button>
                 <button 
                  onClick={() => setMode('narration')}
                  className={`px-4 py-1 text-sm font-semibold rounded ${mode === 'narration' ? 'bg-teal-600 text-white' : 'text-gray-300 hover:bg-gray-600'}`}
                >
                  Narration
                </button>
            </div>
             <div className="flex-1 flex justify-end">
                <button onClick={() => setIsApiKeyModalOpen(true)} className="text-gray-400 hover:text-white transition-colors" title="API Key Settings">
                    <KeyIcon className="w-6 h-6" />
                </button>
            </div>
        </div>
      </header>

      <div className="flex-grow flex flex-col overflow-hidden">
        {mode === 'conversation' ? renderConversationMode() : renderNarrationMode()}
      </div>

      <footer className="w-full bg-gray-800 border-t border-gray-700 p-3 text-center text-xs text-gray-400">
        <p>
          Ajarn Spencer Littlewood in Collaboration with Gemini CLI Unleashed | 
          <a 
            href="https://github.com/AjarnSpencer/" 
            target="_blank" 
            rel="noopener noreferrer" 
            className="ml-2 font-semibold hover:text-teal-300 transition-colors underline"
          >
            GitHub Profile
          </a>
        </p>
      </footer>

      {error && (
        <div className="fixed bottom-4 right-4 bg-red-600 text-white p-4 rounded-lg shadow-lg max-w-sm z-50">
          <p className="font-bold">An Error Occurred</p>
          <p className="text-sm">{error}</p>
          <button onClick={() => setError(null)} className="absolute top-1 right-1 text-xl">&times;</button>
        </div>
      )}
      <CustomVoiceModal 
        isOpen={isCustomVoiceModalOpen}
        onClose={() => setIsCustomVoiceModalOpen(false)}
        onSave={handleSaveCustomVoice}
        apiKey={apiKey}
      />
      <ApiKeyModal
        isOpen={isApiKeyModalOpen}
        onClose={() => setIsApiKeyModalOpen(false)}
        onSave={handleSaveApiKey}
        initialKey={apiKey}
      />
    </main>
  );
};

