                </div>
                <div className={`max-w-prose p-4 rounded-xl ${msg.speaker === 'model' ? 'bg-gray-700' : 'bg-teal-800'}`}>
                  <p className={`text-white ${!msg.isFinal ? 'opacity-70' : ''}`}>{msg.text}</p>
                </div>
              </div>
