              </button>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4 text-white">
                <div>
                  <label htmlFor="emotion" className="block text-sm font-medium text-gray-400 mb-1">AI Tone</label>
                  <select id="emotion" value={emotion} onChange={(e) => setEmotion(e.target.value)} disabled={isSessionActive} className="w-full bg-gray-700 border border-gray-600 rounded-md p-2 text-sm focus:ring-teal-500 focus:border-teal-500 disabled:opacity-50">
                    <option>Neutral</option>
                    <option>Happy</option>
                    <option>Sad</option>
                    <option>Enthusiastic</option>
                    <option>Serious</option>
                    <option value="Pro-Actively Curious and Investigative Natured">Inquisitive</option>
                    <option value="Proactive Agentic Suggestive Teacher">Teacher</option>
                  </select>
                </div>
                <div>
                  <label htmlFor="style" className="block text-sm font-medium text-gray-400 mb-1">AI Style</label>
