                    <option>Conversational</option>
                    <option>Formal</option>
                    <option>Narrative</option>
                    <option value="Official Executive Professional Advisor Consultant Expert">Expert Advisor</option>
                  </select>
                </div>
                <div>
                  <label htmlFor="voice" className="block text-sm font-medium text-gray-400 mb-1">AI Voice</label>
