        <div className="mt-8 flex flex-col gap-3">
            <button 
                onClick={handleSave}
                className="w-full py-4 bg-teal-600 hover:bg-teal-500 text-white font-black uppercase text-xs tracking-widest rounded-xl transition-all shadow-xl shadow-teal-500/20 active:scale-95"
            >
                Sync Credentials
            </button>
            <button onClick={onClose} className="w-full py-2 text-[10px] font-bold text-gray-500 hover:text-gray-300 uppercase tracking-widest transition-colors">
                Close Settings
            </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useRef, useCallback, useEffect } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality, Blob } from '@google/genai';
import { MicrophoneIcon, StopCircleIcon, UserIcon, SparklesIcon, PlusIcon, KeyIcon, BookOpenIcon, ArrowDownTrayIcon, ArrowUpTrayIcon, InformationCircleIcon } from './components/icons';
import { CustomVoiceModal } from './components/CustomVoiceModal';
import { ApiKeyModal } from './components/ApiKeyModal';
import { PronunciationModal, type PronunciationRule } from './components/PronunciationModal';
import { TutorialModal } from './components/TutorialModal';
import { type TranscriptMessage } from './types';
import { encode, decode, decodeAudioData, pcmToWavBlob, concatenateBuffers } from './utils/audio';

interface CustomVoice {
  name: string;
  instruction: string;
  baseVoice: string;
}

type AppMode = 'conversation' | 'narration';

const narrationPrebuiltVoices: { [key: string]: { description: string; voiceName: string } } = {
  'Charon (Deep Male)': {
    description: 'A very deep, resonant, and unambiguously MALE voice with a serious, authoritative tone.',
    voiceName: 'Charon',
  },
  'Hyperion (Authoritative Male Narrator)': {
    description: 'An authoritative, deep MALE voice for documentary-style narration, similar to Charon but with a focus on gravitas.',
    voiceName: 'Charon',
  },
  'Puck (Friendly Male)': {
    description: 'A friendly and engaging MALE voice with a clear and pleasant tone, with a slight warmth. (Inspired by Sadachbia)',
    voiceName: 'Puck',
  },
  'Sadachbia (Warm Male Storyteller)': {
    description: 'A warm, engaging, and friendly MALE voice, perfect for storytelling and audiobooks. Based on Puck.',
    voiceName: 'Puck',
  },
  'Fenrir (Serious Male)': {
    description: 'A serious, mature MALE voice suitable for formal narration.',
    voiceName: 'Fenrir',
  },
  'Kore (Clear Female)': {
    description: 'A clear, neutral female voice with a standard American accent.',
    voiceName: 'Kore',
  },
   'Aura (Calm Female Guide)': {
    description: 'A calm, clear, and reassuring FEMALE voice, suitable for guided meditations or instructional content. Based on Kore.',
    voiceName: 'Kore',
  },
  'Zephyr (Warm Female)': {
    description: 'A warm and friendly female voice, suitable for conversational content.',
    voiceName: 'Zephyr',
  }
};


const App: React.FC = () => {
  const [mode, setMode] = useState<AppMode>('narration');
  const [isSessionActive, setIsSessionActive] = useState<boolean>(false);
  const [transcript, setTranscript] = useState<TranscriptMessage[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [emotion, setEmotion] = useState<string>('Neutral');
  const [style, setStyle] = useState<string>('Narrative');
  const [voice, setVoice] = useState<string>('Zephyr');

  const [isCustomVoiceModalOpen, setIsCustomVoiceModalOpen] = useState(false);
  const [customVoice, setCustomVoice] = useState<CustomVoice | null>(null);

  // API Key State
  const [apiKey, setApiKey] = useState<string>('');
  const [resembleKey, setResembleKey] = useState<string>('');
  const [elevenLabsKey, setElevenLabsKey] = useState<string>('');
  const [isApiKeyModalOpen, setIsApiKeyModalOpen] = useState<boolean>(false);
  const [isTutorialModalOpen, setIsTutorialModalOpen] = useState<boolean>(false);

  // Narration state
  const defaultNarrationScript = `<speak>
  [Read with professional gravitas and occasional warmth]

  Welcome to the future of documentary narration. By combining LLM-driven context with SSML control, we achieve unparalleled realism.

  <break time="800ms"/>

  Observe how the AI handles complex mathematics: 
  The area of a circle is defined by the equation <prosody pitch="+2st" rate="95%">A equals pi times the radius squared</prosody>.

  <break time="500ms"/>

  [Switch to a more conversational, inquisitive tone]
  But why does it matter? 
  <emphasis level="strong">Because accuracy is everything.</emphasis> 

  Whether you are explaining quantum mechanics or telling the story of an ancient civilization, 
  this tool provides the <prosody rate="110%" pitch="-1st">nuance required for world-class production.</prosody>

  [Whisper]
  The secrets of the past are only ever a syllable away.
</speak>`;

  const [narrationText, setNarrationText] = useState<string>(defaultNarrationScript);
  const [narrationVoiceKey, setNarrationVoiceKey] = useState<string>('Charon (Deep Male)');
  const [narrationVoiceStyle, setNarrationVoiceStyle] = useState<string>(narrationPrebuiltVoices['Charon (Deep Male)'].description);
  const [narrationBaseVoice, setNarrationBaseVoice] = useState<string>('Charon');
  const [narrationLanguage, setNarrationLanguage] = useState<string>('English (US)');
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [generationStatus, setGenerationStatus] = useState<string>('');
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const [audioBlob, setAudioBlob] = useState<globalThis.Blob | null>(null);

  // Pronunciation state
  const [pronunciationRules, setPronunciationRules] = useState<PronunciationRule[]>([]);
  const [isPronunciationModalOpen, setIsPronunciationModalOpen] = useState(false);

  const sessionRef = useRef<any | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const nextStartTimeRef = useRef<number>(0);
  const currentInputTranscriptionRef = useRef<string>('');
  const currentOutputTranscriptionRef = useRef<string>('');

  useEffect(() => {
    const storedKey = localStorage.getItem('gemini_api_key');
    const storedResembleKey = localStorage.getItem('resemble_api_key');
    const storedElevenLabsKey = localStorage.getItem('elevenlabs_api_key');
    const storedRules = localStorage.getItem('pronunciation_rules');
    const storedVoice = localStorage.getItem('custom_voice_profile');

    if (storedKey) {
      setApiKey(storedKey);
    } else if (process.env.API_KEY) {
        setApiKey(process.env.API_KEY);
    } else {
      setIsApiKeyModalOpen(true);
    }

    if (storedResembleKey) setResembleKey(storedResembleKey);
    if (storedElevenLabsKey) setElevenLabsKey(storedElevenLabsKey);

    if (storedRules) {
      try {
        setPronunciationRules(JSON.parse(storedRules));
      } catch (e) { console.error("Rules restore failed", e); }
    }

    if (storedVoice) {
      try {
        setCustomVoice(JSON.parse(storedVoice));
      } catch (e) { console.error("Voice restore failed", e); }
    }
  }, []);

  const handleSaveApiKey = (gemini: string, resemble: string, eleven: string) => {
    localStorage.setItem('gemini_api_key', gemini);
    localStorage.setItem('resemble_api_key', resemble);
    localStorage.setItem('elevenlabs_api_key', eleven);
    setApiKey(gemini);
    setResembleKey(resemble);
    setElevenLabsKey(eleven);
  };

  const handleSavePronunciationRules = (rules: PronunciationRule[]) => {
    setPronunciationRules(rules);
    localStorage.setItem('pronunciation_rules', JSON.stringify(rules));
  };

  const handleExportVoice = () => {
    let profileToExport = null;
    if (customVoice && narrationVoiceKey === customVoice.name) {
      profileToExport = customVoice;
    } else {
      profileToExport = {
        name: narrationVoiceKey,
        instruction: narrationVoiceStyle,
        baseVoice: narrationBaseVoice
      };
    }

    if (!profileToExport) return;
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(profileToExport, null, 2));
    const downloadAnchorNode = document.createElement('a');
    downloadAnchorNode.setAttribute("href", dataStr);
    downloadAnchorNode.setAttribute("download", `voice-profile-${profileToExport.name.replace(/\s+/g, '-').toLowerCase()}.json`);
    document.body.appendChild(downloadAnchorNode);
    downloadAnchorNode.click();
    downloadAnchorNode.remove();
  };

  const handleImportVoice = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const profile = JSON.parse(e.target?.result as string) as CustomVoice;
        if (profile.name && profile.instruction && profile.baseVoice) {
          setCustomVoice(profile);
          localStorage.setItem('custom_voice_profile', JSON.stringify(profile));
          setVoice(profile.name);
          handleNarrationVoiceChange(profile.name);
        } else {
          setError("Invalid voice profile format.");
        }
      } catch (err) {
        setError("Failed to parse voice profile JSON.");
      }
    };
    reader.readAsText(file);
  };

  const applyPronunciationRules = (text: string): string => {
    if (pronunciationRules.length === 0) return text;
    let processedText = text;
    pronunciationRules.forEach(rule => {
      const escapedWord = rule.word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const regex = new RegExp(`\\b${escapedWord}\\b`, 'gi');
      processedText = processedText.replace(regex, rule.alias);
    });
    return processedText;
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) {
      sessionRef.current.close();
      sessionRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => track.stop());
      streamRef.current = null;
    }
    if (scriptProcessorRef.current) {
      scriptProcessorRef.current.disconnect();
      scriptProcessorRef.current = null;
    }
    if (inputAudioContextRef.current && inputAudioContextRef.current.state !== 'closed') {
      inputAudioContextRef.current.close();
      inputAudioContextRef.current = null;
    }
    if (outputAudioContextRef.current && outputAudioContextRef.current.state !== 'closed') {
      sourcesRef.current.forEach(source => source.stop());
      sourcesRef.current.clear();
      outputAudioContextRef.current.close();
      outputAudioContextRef.current = null;
    }
    setIsSessionActive(false);
    setTranscript([]);
  }, []);

  const startSession = async () => {
    setError(null);
    setTranscript([]);
    if (!apiKey) {
      setIsApiKeyModalOpen(true);
      return;
    }
    setIsSessionActive(true);
    try {
      const ai = new GoogleGenAI({ apiKey: apiKey });
      const systemInstruction = `You are a helpful AI assistant. You must speak aloud. Your tone should be ${emotion === 'Inquisitive' ? 'Pro-Actively Curious and Investigative Natured' : emotion}. Your speaking style should be ${style}. ${customVoice ? customVoice.instruction : ''}`;
      inputAudioContextRef.current = new ((window as any).AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new ((window as any).AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      nextStartTimeRef.current = 0;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        config: {
          responseModalalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: (customVoice && voice === customVoice.name) ? customVoice.baseVoice : voice } },
          },
          systemInstruction: systemInstruction,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
        },
        callbacks: {
          onopen: async () => {
            streamRef.current = await navigator.mediaDevices.getUserMedia({ audio: true });
            const source = inputAudioContextRef.current!.createMediaStreamSource(streamRef.current);
            scriptProcessorRef.current = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current.onaudioprocess = (audioProcessingEvent) => {
              const inputData = audioProcessingEvent.inputBuffer.getChannelData(0);
              const pcmBlob: Blob = {
                data: encode(new Uint8Array(new Int16Array(inputData.map(f => f * 32768)).buffer)),
                mimeType: 'audio/pcm;rate=16000',
              };
              sessionPromise.then((session) => { session.sendRealtimeInput({ media: pcmBlob }); });
            };
            source.connect(scriptProcessorRef.current);
            scriptProcessorRef.current.connect(inputAudioContextRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.serverContent?.inputTranscription) {
              const { text } = message.serverContent.inputTranscription;
              currentInputTranscriptionRef.current += text;
              setTranscript(prev => {
                const last = prev[prev.length - 1];
                if (last && last.speaker === 'user' && !last.isFinal) return [...prev.slice(0, -1), { ...last, text: currentInputTranscriptionRef.current }];
                return [...prev, { speaker: 'user', text: currentInputTranscriptionRef.current, isFinal: false }];
              });
            }
            if (message.serverContent?.outputTranscription) {
              const { text } = message.serverContent.outputTranscription;
              currentOutputTranscriptionRef.current += text;
              setTranscript(prev => {
                const last = prev[prev.length - 1];
                if (last && last.speaker === 'model' && !last.isFinal) return [...prev.slice(0, -1), { ...last, text: currentOutputTranscriptionRef.current }];
                if (!last || last.speaker !== 'model' || last.isFinal) return [...prev, { speaker: 'model', text: currentOutputTranscriptionRef.current, isFinal: false }];
                return prev;
              });
            }
            if (message.serverContent?.turnComplete) {
                setTranscript(prev => {
                    const newTranscript = [...prev];
                    for (let i = newTranscript.length - 1; i >= 0; i--) { if (newTranscript[i].speaker === 'user') { newTranscript[i] = {...newTranscript[i], isFinal: true }; break; } }
                    for (let i = newTranscript.length - 1; i >= 0; i--) { if (newTranscript[i].speaker === 'model') { newTranscript[i] = {...newTranscript[i], isFinal: true }; break; } }
                    return newTranscript;
                });
                currentInputTranscriptionRef.current = '';
                currentOutputTranscriptionRef.current = '';
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              const audioContext = outputAudioContextRef.current!;
              const audioBuffer = await decodeAudioData(decode(base64Audio), audioContext, 24000, 1);
              const source = audioContext.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(audioContext.destination);
              const startTime = Math.max(audioContext.currentTime, nextStartTimeRef.current);
              source.start(startTime);
              nextStartTimeRef.current = startTime + audioBuffer.duration;
              sourcesRef.current.add(source);
              source.onended = () => sourcesRef.current.delete(source);
            }
          },
          onerror: (err: ErrorEvent) => { setError(`Session error: ${err.message}`); stopSession(); },
          onclose: () => stopSession(),
        },
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setError(`Failed to start session: ${err.message}`); setIsSessionActive(false); }
  };

  const handleSaveCustomVoice = (newCustomVoice: CustomVoice) => {
    setCustomVoice(newCustomVoice);
    localStorage.setItem('custom_voice_profile', JSON.stringify(newCustomVoice));
    setVoice(newCustomVoice.name);
    setIsCustomVoiceModalOpen(false);
  };

  const splitTextIntoChunks = (text: string): string[] => {
    let cleanText = text.trim();
    if (cleanText.startsWith('<speak>')) cleanText = cleanText.slice(7);
    if (cleanText.endsWith('</speak>')) cleanText = cleanText.slice(0, -8);
    return cleanText.trim().split(/\n\s*\n/).filter(chunk => chunk.trim().length > 0);
  };

  const generateNarration = async () => {
    setIsGenerating(true); setGenerationStatus('Preparing...'); setError(null); setAudioUrl(null); setAudioBlob(null);
    if (!apiKey) { setIsApiKeyModalOpen(true); setIsGenerating(false); return; }
    try {
      const ai = new GoogleGenAI({ apiKey: apiKey });
      const ruleAppliedText = applyPronunciationRules(narrationText);
      const chunks = splitTextIntoChunks(ruleAppliedText);
      const audioParts: Uint8Array[] = [];
      const languageFullName = narrationLanguage;
      const isTranslation = !languageFullName.startsWith('English');

      for (let i = 0; i < chunks.length; i++) {
        setGenerationStatus(`Processing part ${i + 1} of ${chunks.length}...`);
        let textChunk = `<speak>${chunks[i]}</speak>`;
        let textToSpeak = textChunk;

        if (isTranslation) {
           setGenerationStatus(`Translating part ${i + 1}...`);
           const translationResponse = await ai.models.generateContent({
             model: 'gemini-2.5-flash',
             contents: `Translate to ${languageFullName.split(' ')[0]}. Keep SSML tags exactly: ${textChunk}`,
           });
           textToSpeak = translationResponse.text.trim();
        }

        setGenerationStatus(`Synthesizing part ${i + 1}...`);
        let ttsPromptText = narrationVoiceKey === 'custom' 
            ? `Voice Style: "${narrationVoiceStyle}". Accent: ${languageFullName}. Script: ${textToSpeak}`
            : textToSpeak;

        const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-preview-tts',
            contents: [{ parts: [{ text: ttsPromptText }] }],
            config: {
              responseModalities: [Modality.AUDIO],
              speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: narrationBaseVoice } } },
            },
        });
        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (base64Audio) audioParts.push(decode(base64Audio));
      }

      setGenerationStatus('Finalizing...');
      const wavBlob = pcmToWavBlob(concatenateBuffers(audioParts), 24000, 1);
      setAudioUrl(URL.createObjectURL(wavBlob));
      setAudioBlob(wavBlob);
    } catch (err: any) { setError(`Generation failed: ${err.message}`); } finally { setIsGenerating(false); setGenerationStatus(''); }
  };

  const handleNarrationVoiceChange = (selectedKey: string) => {
    setNarrationVoiceKey(selectedKey);
    const preset = narrationPrebuiltVoices[selectedKey];
    if (preset) {
        setNarrationVoiceStyle(preset.description);
        setNarrationBaseVoice(preset.voiceName);
    } else if (customVoice && selectedKey === customVoice.name) {
        setNarrationVoiceStyle(customVoice.instruction);
        setNarrationBaseVoice(customVoice.baseVoice);
    }
  };

  const allVoices = ['Zephyr', 'Puck', 'Kore', 'Charon', 'Fenrir'];
  if (customVoice && !allVoices.includes(customVoice.name)) allVoices.unshift(customVoice.name);

  const allNarrationVoices: {[key: string]: {description: string, voiceName?: string}} = { ...narrationPrebuiltVoices };
  if (customVoice) allNarrationVoices[customVoice.name] = { description: customVoice.instruction };

  const renderConversationMode = () => (
    <>
      <div className="flex-grow w-full max-w-4xl mx-auto p-4 overflow-y-auto">
          <div className="space-y-6">
            {transcript.length === 0 && (
              <div className="text-center text-gray-400 pt-20">
                <h1 className="text-4xl font-bold text-teal-300 font-orbitron">Conversational AI</h1>
                <p className="mt-2">Enable your microphone to begin.</p>
              </div>
            )}
            {transcript.map((msg, index) => (
              <div key={index} className={`flex items-start gap-4 ${msg.speaker === 'user' ? 'justify-end' : ''}`}>
                <div className={`p-2 rounded-full ${msg.speaker === 'model' ? 'bg-teal-500' : 'bg-gray-600'}`}>
                  {msg.speaker === 'model' ? <SparklesIcon className="w-6 h-6 text-white"/> : <UserIcon className="w-6 h-6 text-white"/>}
                </div>
                <div className={`max-w-prose p-4 rounded-xl ${msg.speaker === 'model' ? 'bg-gray-700 shadow-lg border border-gray-600' : 'bg-teal-800 shadow-lg'}`}>
                  <p className={`text-white leading-relaxed ${!msg.isFinal ? 'opacity-70' : ''}`}>{msg.text}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
        <footer className="w-full bg-gray-900/80 backdrop-blur-sm border-t border-gray-700 p-4">
          <div className="max-w-4xl mx-auto">
            <div className="flex justify-center mb-4">
              <button onClick={isSessionActive ? stopSession : startSession} className={`p-4 rounded-full transition-all duration-300 shadow-lg ${isSessionActive ? 'bg-red-600 hover:bg-red-700 scale-110' : 'bg-teal-500 hover:bg-teal-600'}`}>
                {isSessionActive ? <StopCircleIcon className="w-10 h-10 text-white" /> : <MicrophoneIcon className="w-10 h-10 text-white" />}
              </button>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-4 gap-4 text-white">
                <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">AI Tone</label>
                  <select value={emotion} onChange={(e) => setEmotion(e.target.value)} disabled={isSessionActive} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-sm disabled:opacity-50">
                    <option>Neutral</option><option>Happy</option><option>Sad</option><option>Enthusiastic</option><option>Serious</option><option value="Pro-Actively Curious">Inquisitive</option><option value="Proactive Agentic Suggestive Teacher">Teacher</option>
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">AI Style</label>
                  <select value={style} onChange={(e) => setStyle(e.target.value)} disabled={isSessionActive} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-sm disabled:opacity-50">
                    <option>Conversational</option><option>Formal</option><option>Narrative</option><option value="Official Expert Advisor">Expert Advisor</option>
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">AI Voice</label>
                  <select value={voice} onChange={(e) => setVoice(e.target.value)} disabled={isSessionActive} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-sm disabled:opacity-50">
                     {allVoices.map(v => <option key={v} value={v}>{v}</option>)}
                  </select>
                </div>
                <div>
                   <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Voice Control</label>
                   <div className="flex gap-1">
                    <button onClick={() => setIsCustomVoiceModalOpen(true)} disabled={isSessionActive} className="flex-grow flex items-center justify-center gap-2 bg-teal-600 hover:bg-teal-700 rounded-md p-2 text-xs transition-colors disabled:bg-gray-700">
                      <PlusIcon className="w-3 h-3" /> New
                    </button>
                    <button onClick={handleExportVoice} className="bg-gray-700 hover:bg-gray-600 p-2 rounded-md transition-colors" title="Export Voice JSON">
                        <ArrowDownTrayIcon className="w-4 h-4 text-teal-400" />
                    </button>
                    <label className="bg-gray-700 hover:bg-gray-600 p-2 rounded-md cursor-pointer transition-colors" title="Import Voice JSON">
                        <ArrowUpTrayIcon className="w-4 h-4 text-teal-400" />
                        <input type="file" accept=".json" onChange={handleImportVoice} className="hidden" />
                    </label>
                   </div>
                </div>
            </div>
          </div>
        </footer>
    </>
  );

  const renderNarrationMode = () => (
    <div className="flex-grow w-full max-w-4xl mx-auto p-4 flex flex-col gap-4 overflow-y-auto">
        <div className="flex-grow flex flex-col gap-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 <div>
                    <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Language & Accent</label>
                    <select value={narrationLanguage} onChange={(e) => setNarrationLanguage(e.target.value)} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-white focus:ring-teal-500 outline-none" disabled={isGenerating}>
                    {['English (US)', 'English (UK)', 'English (India)', 'Spanish', 'French', 'German', 'Hindi', 'Japanese', 'Korean', 'Thai', 'Chinese', 'Italian', 'Russian', 'Maltese', 'Lao', 'Khmer', 'Latin', 'Greek', 'Portuguese', 'Nepali', 'Sinhala'].map(lang => <option key={lang} value={lang}>{lang}</option>)}
                    </select>
                </div>
                <div>
                    <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Base Voice Model</label>
                    <select value={narrationVoiceKey} onChange={(e) => handleNarrationVoiceChange(e.target.value)} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-white focus:ring-teal-500 outline-none" disabled={isGenerating}>
                        {Object.keys(allNarrationVoices).map((name) => <option key={name} value={name}>{name.replace('(Custom)', '').trim()}</option>)}
                        {narrationVoiceKey === 'custom' && <option value="custom" disabled>Custom</option>}
                    </select>
                </div>
            </div>

            <div>
                <div className="flex justify-between items-center mb-1">
                  <label className="block text-xs font-bold text-gray-500 uppercase">Voice Style Personalization</label>
                  <div className="flex bg-gray-800 border border-gray-700 rounded-md overflow-hidden shadow-sm">
                    <button onClick={() => setIsPronunciationModalOpen(true)} className="flex items-center gap-2 px-3 py-1.5 text-[10px] font-black uppercase text-teal-400 hover:bg-gray-700 border-r border-gray-700 transition-colors">
                      <BookOpenIcon className="w-3 h-3" /> Dict ({pronunciationRules.length})
                    </button>
                    <button onClick={handleExportVoice} className="flex items-center gap-2 px-3 py-1.5 text-[10px] font-black uppercase text-teal-400 hover:bg-gray-700 border-r border-gray-700 transition-colors" title="Export Current Profile">
                      <ArrowDownTrayIcon className="w-3 h-3" /> Export
                    </button>
                    <label className="flex items-center gap-2 px-3 py-1.5 text-[10px] font-black uppercase text-teal-400 hover:bg-gray-700 cursor-pointer transition-colors" title="Import Profile JSON">
                      <ArrowUpTrayIcon className="w-3 h-3" /> Import
                      <input type="file" accept=".json" onChange={handleImportVoice} className="hidden" />
                    </label>
                  </div>
                </div>
                <textarea rows={3} value={narrationVoiceStyle} onChange={(e) => { setNarrationVoiceStyle(e.target.value); setNarrationVoiceKey('custom'); }} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-sm focus:border-teal-500 outline-none" placeholder="Describe the voice's emotional nuances..." disabled={isGenerating} />
            </div>

            <div className="flex flex-col flex-grow">
                 <label className="block text-xs font-bold text-gray-500 mb-1 uppercase">Script & Synthesis Control</label>
                 <textarea value={narrationText} onChange={(e) => setNarrationText(e.target.value)} className="w-full flex-grow min-h-[400px] bg-gray-800 border border-gray-700 rounded-md p-3 text-white font-mono text-xs focus:border-teal-500 outline-none leading-relaxed shadow-inner" placeholder="Enter script with SSML or LLM-style emotional cues..." disabled={isGenerating} />
            </div>

            <div className="flex justify-center mt-2">
                 <button onClick={generateNarration} disabled={isGenerating || !narrationText} className="px-10 py-4 rounded-xl bg-teal-600 hover:bg-teal-500 disabled:bg-gray-700 disabled:cursor-not-allowed transition-all font-black uppercase text-sm tracking-widest shadow-xl shadow-teal-500/20 flex items-center group">
                    {isGenerating ? (
                        <><svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>{generationStatus}</>
                    ) : (
                      <>Synthesize Narrative <SparklesIcon className="w-4 h-4 ml-2 group-hover:animate-pulse" /></>
                    )}
                </button>
            </div>
        </div>

        {audioUrl && (
            <div className="mt-4 p-4 bg-gray-800 rounded-lg border border-teal-900/50 shadow-inner">
                <div className="flex justify-between items-center mb-3">
                  <h3 className="text-sm font-bold text-teal-300 uppercase tracking-widest">Master Audio Output</h3>
                  <span className="text-[10px] text-gray-500">24kHz PCM WAV</span>
                </div>
                <audio controls src={audioUrl} className="w-full mb-3"></audio>
                <a href={audioUrl} download={`narration-${Date.now()}.wav`} className="block w-full text-center px-4 py-3 rounded-md bg-teal-500 hover:bg-teal-600 transition-colors font-bold shadow-lg uppercase text-sm tracking-tighter">Download High-Fidelity Waveform</a>
            </div>
        )}
    </div>
  );

  return (
    <main className="bg-gray-900 text-white h-screen flex flex-col font-sans selection:bg-teal-500/30">
      <header className="w-full bg-gray-800/80 backdrop-blur-md border-b border-gray-700 p-4 flex flex-col items-center relative z-10 gap-4 shadow-xl">
        <h1 className="text-3xl font-bold text-cyan-300 font-orbitron tracking-tighter" style={{ textShadow: '0 0 15px rgba(56, 249, 215, 0.4)' }}>Endless Text Narrator</h1>
        <div className="w-full flex justify-between items-center max-w-sm">
             <div className="flex-1">
                <button onClick={() => setIsTutorialModalOpen(true)} className="text-gray-400 hover:text-teal-300 transition-all flex items-center gap-2 group" title="Academy & Pro Tutorials">
                    <InformationCircleIcon className="w-8 h-8 group-hover:scale-110" />
                    <div className="flex flex-col items-start leading-none">
                      <span className="text-[10px] font-black uppercase text-teal-500">Voice</span>
                      <span className="text-[8px] font-bold uppercase opacity-50">Academy</span>
                    </div>
                </button>
            </div>
            <div className="inline-flex bg-gray-900 border border-gray-700 rounded-lg p-1 mx-2">
                <button onClick={() => setMode('conversation')} className={`px-4 py-1.5 text-xs font-bold uppercase rounded-md transition-all ${mode === 'conversation' ? 'bg-teal-600 text-white shadow-lg' : 'text-gray-400 hover:text-gray-200'}`}>Chat</button>
                 <button onClick={() => setMode('narration')} className={`px-4 py-1.5 text-xs font-bold uppercase rounded-md transition-all ${mode === 'narration' ? 'bg-teal-600 text-white shadow-lg' : 'text-gray-400 hover:text-gray-200'}`}>Narrate</button>
            </div>
             <div className="flex-1 flex justify-end">
                <button onClick={() => setIsApiKeyModalOpen(true)} className="text-gray-400 hover:text-teal-300 transition-colors" title="API Key Configuration">
                    <KeyIcon className="w-6 h-6" />
                </button>
            </div>
        </div>
      </header>

      <div className="flex-grow flex flex-col overflow-hidden">
        {mode === 'conversation' ? renderConversationMode() : renderNarrationMode()}
      </div>

      <footer className="w-full bg-gray-800 border-t border-gray-700 p-3 text-center text-[10px] text-gray-500 uppercase font-bold tracking-widest">
        <p>Collaboration: Ajarn Spencer Littlewood × Gemini CLI Unleashed | <a href="https://github.com/AjarnSpencer/" target="_blank" rel="noopener noreferrer" className="text-teal-400 hover:underline">Source</a></p>
      </footer>

      {error && (
        <div className="fixed bottom-6 right-6 bg-red-950/80 backdrop-blur-md border border-red-500 text-red-200 p-4 rounded-xl shadow-2xl max-w-sm z-50 animate-in fade-in slide-in-from-bottom-4">
          <p className="font-black text-xs uppercase mb-1">System Error</p>
          <p className="text-sm leading-tight">{error}</p>
          <button onClick={() => setError(null)} className="absolute top-2 right-2 text-red-500 hover:text-white">&times;</button>
        </div>
      )}
      <CustomVoiceModal isOpen={isCustomVoiceModalOpen} onClose={() => setIsCustomVoiceModalOpen(false)} onSave={handleSaveCustomVoice} apiKey={apiKey} />
      <ApiKeyModal 
        isOpen={isApiKeyModalOpen} 
        onClose={() => setIsApiKeyModalOpen(false)} 
        onSave={handleSaveApiKey} 
        initialGeminiKey={apiKey}
        initialResembleKey={resembleKey}
        initialElevenLabsKey={elevenLabsKey}
      />
      <PronunciationModal isOpen={isPronunciationModalOpen} onClose={() => setIsPronunciationModalOpen(false)} rules={pronunciationRules} onSave={handleSavePronunciationRules} />
      <TutorialModal isOpen={isTutorialModalOpen} onClose={() => setIsTutorialModalOpen(false)} />
    </main>
  );
};

export default App;

{
