import React, { useState, useEffect } from 'react';

interface ApiKeyModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (geminiKey: string, resembleKey: string, elevenLabsKey: string) => void;
  initialGeminiKey?: string;
  initialResembleKey?: string;
  initialElevenLabsKey?: string;
}

export const ApiKeyModal: React.FC<ApiKeyModalProps> = ({ 
  isOpen, 
  onClose, 
  onSave, 
  initialGeminiKey = '',
  initialResembleKey = '',
  initialElevenLabsKey = ''
}) => {
  const [geminiKey, setGeminiKey] = useState(initialGeminiKey);
  const [resembleKey, setResembleKey] = useState(initialResembleKey);
  const [elevenLabsKey, setElevenLabsKey] = useState(initialElevenLabsKey);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setGeminiKey(initialGeminiKey);
    setResembleKey(initialResembleKey);
    setElevenLabsKey(initialElevenLabsKey);
  }, [initialGeminiKey, initialResembleKey, initialElevenLabsKey]);

  if (!isOpen) return null;

  const handleSave = () => {
    if (!geminiKey.trim()) {
      setError("Google Gemini API Key is required.");
      return;
    }
    onSave(geminiKey.trim(), resembleKey.trim(), elevenLabsKey.trim());
    onClose();
  };

  return (
    <div className="fixed inset-0 bg-black/90 flex items-center justify-center z-[200] p-4" onClick={onClose}>
      <div className="bg-gray-800 rounded-2xl shadow-2xl w-full max-w-md p-8 text-white border border-gray-700 animate-in zoom-in-95 duration-200 max-h-[90vh] overflow-y-auto scrollbar-thin scrollbar-thumb-teal-900" onClick={(e) => e.stopPropagation()}>
