        </div>

        <p className="text-gray-400 mb-6 text-[11px] leading-relaxed">
          Keys are stored locally in your browser cache. They are never transmitted to our servers—only used for direct client-side requests to providers.
        </p>

        <div className="space-y-6">
          {/* Gemini Key */}
          <div className="bg-black/20 p-4 rounded-xl border border-gray-700/50">
            <label htmlFor="geminiKey" className="block text-[10px] font-black text-teal-500 mb-2 uppercase tracking-wider">Google Gemini API Key (Required)</label>
            <input
              id="geminiKey"
              type="password"
              value={geminiKey}
              onChange={(e) => {
                  setGeminiKey(e.target.value);
                  setError(null);
              }}
              placeholder="AIzaSy..."
              className="w-full bg-black/40 border border-gray-700 rounded-lg p-3 text-sm text-teal-100 focus:ring-2 focus:ring-teal-500/50 focus:border-teal-500 outline-none transition-all"
            />
            <div className="mt-2">
               <a href="https://aistudio.google.com/app/apikey" target="_blank" rel="noopener noreferrer" className="text-[10px] text-gray-500 hover:text-teal-400 underline transition-colors">Get a Gemini Key</a>
            </div>
          </div>

          {/* ElevenLabs Key */}
          <div className="bg-black/20 p-4 rounded-xl border border-gray-700/50">
            <label htmlFor="elevenLabsKey" className="block text-[10px] font-black text-teal-500 mb-1 uppercase tracking-wider">ElevenLabs API Key</label>
            <p className="text-[9px] text-gray-500 mb-2 italic">Required for professional voice cloning and high-fidelity output.</p>
            <input
              id="elevenLabsKey"
              type="password"
              value={elevenLabsKey}
              onChange={(e) => setElevenLabsKey(e.target.value)}
              placeholder="Your ElevenLabs API key..."
              className="w-full bg-black/40 border border-gray-700 rounded-lg p-3 text-sm text-teal-100 focus:ring-2 focus:ring-teal-500/50 focus:border-teal-500 outline-none transition-all"
            />
            <div className="mt-2">
               <a href="https://elevenlabs.io/app/settings/api-keys" target="_blank" rel="noopener noreferrer" className="text-[10px] text-gray-500 hover:text-teal-400 underline transition-colors">Get an ElevenLabs Key</a>
            </div>
          </div>

          {/* Resemble Key */}
          <div className="bg-black/20 p-4 rounded-xl border border-gray-700/50">
            <label htmlFor="resembleKey" className="block text-[10px] font-black text-teal-500 mb-1 uppercase tracking-wider">Resemble AI API Key</label>
            <p className="text-[9px] text-gray-500 mb-2 italic">Alternative high-fidelity engine for specific vocal profiles.</p>
            <input
              id="resembleKey"
              type="password"
              value={resembleKey}
              onChange={(e) => setResembleKey(e.target.value)}
              placeholder="Your Resemble AI token..."
              className="w-full bg-black/40 border border-gray-700 rounded-lg p-3 text-sm text-teal-100 focus:ring-2 focus:ring-teal-500/50 focus:border-teal-500 outline-none transition-all"
            />
            <div className="mt-2">
