import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI, Type } from '@google/genai';
import { MicrophoneIcon, UploadIcon } from './icons';

interface CustomVoice {
    name: string;
    instruction: string;
    baseVoice: string;
}

interface CustomVoiceModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (voice: CustomVoice) => void;
}

type ModalView = 'initial' | 'analyzing' | 'refining';

export const CustomVoiceModal: React.FC<CustomVoiceModalProps> = ({ isOpen, onClose, onSave }) => {
  const [activeTab, setActiveTab] = useState<'record' | 'upload'>('record');
  const [isRecording, setIsRecording] = useState(false);
  const [audioBlob, setAudioBlob] = useState<Blob | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [view, setView] = useState<ModalView>('initial');
  const [analysisResult, setAnalysisResult] = useState<{ instruction: string; baseVoice: string } | null>(null);
  const [editedInstruction, setEditedInstruction] = useState('');

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  useEffect(() => {
    // Reset state when modal opens or closes
    if (isOpen) {
      setView('initial');
      setAudioBlob(null);
      setError(null);
      setIsRecording(false);
      setAnalysisResult(null);
      setEditedInstruction('');
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const handleStartRecording = async () => {
    try {
      setError(null);
      setAudioBlob(null);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      mediaRecorderRef.current = new MediaRecorder(stream);
      audioChunksRef.current = [];

      mediaRecorderRef.current.ondataavailable = (event) => {
        audioChunksRef.current.push(event.data);
      };

      mediaRecorderRef.current.onstop = () => {
        const blob = new Blob(audioChunksRef.current, { type: 'audio/webm' });
        setAudioBlob(blob);
        stream.getTracks().forEach(track => track.stop()); // Release microphone
      };

      mediaRecorderRef.current.start();
      setIsRecording(true);
    } catch (err) {
      console.error("Error starting recording:", err);
      setError("Could not access microphone. Please check permissions.");
    }
  };

  const handleStopRecording = () => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state === 'recording') {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
    }
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setError(null);
    setAudioBlob(null);
    const file = event.target.files?.[0];
    if (file && file.type.startsWith('audio/')) {
        setAudioBlob(file);
    } else {
        setError("Please select a valid audio file.");
    }
  };

  const handleAnalyze = async () => {
    if (!audioBlob) {
      setError("Please record or upload audio first.");
      return;
    }

    setView('analyzing');
    setError(null);
    try {
      // Create instance right before API call using process.env.API_KEY
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const reader = new FileReader();
      reader.readAsDataURL(audioBlob);
      await new Promise<void>(resolve => reader.onload = () => resolve());
      const base64Audio = (reader.result as string).split(',')[1];

      // Updated model to gemini-3-flash-preview for text analysis task
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: { parts: [
          { inlineData: { mimeType: audioBlob.type, data: base64Audio } },
          { text: "Analyze the attached audio of a person speaking. Provide a detailed description of the voice's characteristics for an AI to mimic. Specifically include analysis of: pitch (e.g., high, low, medium), tone (e.g., warm, sharp, calm), pace (e.g., fast, slow, measured), and more nuanced qualities like vocal fry (presence and amount), breathiness, and articulation clarity (e.g., crisp, soft). Then, determine if the voice sounds more masculine or feminine. Based on your analysis, provide a JSON object with two keys: 'instruction' (a detailed instruction for an AI to mimic this speaking style, incorporating the nuanced qualities) and 'baseVoice' (select 'Charon' if the voice is masculine, and 'Kore' if it is feminine)." }
        ]},
        config: {
          responseMimeType: 'application/json',
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              instruction: { type: Type.STRING },
              baseVoice: { type: Type.STRING }
            }
          }
        }
      });

      const jsonStr = response.text;
      if (!jsonStr) throw new Error("No response text from model");
      const parsed = JSON.parse(jsonStr);
      setAnalysisResult(parsed);
      setEditedInstruction(parsed.instruction);
      setView('refining');

    } catch (err: any) {
      console.error("Error creating custom voice:", err);
      setError("Could not analyze the voice. Please try again.");
      setView('initial');
    }
  };

  const handleSave = () => {
    if (!analysisResult) return;
    const voiceName = `Custom: ${editedInstruction.substring(0, 25)}...`;
    const newCustomVoice: CustomVoice = {
      name: voiceName,
      instruction: editedInstruction,
      baseVoice: analysisResult.baseVoice,
    };
    onSave(newCustomVoice);
  };

  const renderInitialView = () => (
    <>
      <p className="text-gray-400 mb-6">Record or upload a short audio clip (up to 30 seconds). The AI will analyze your voice's characteristics to create a unique speaking style. This is not a direct voice clone.</p>
      <div className="border-b border-gray-600 mb-4">
        <nav className="-mb-px flex space-x-6" aria-label="Tabs">
          <button onClick={() => setActiveTab('record')} className={`${activeTab === 'record' ? 'border-teal-400 text-teal-400' : 'border-transparent text-gray-400 hover:text-gray-200 hover:border-gray-400'} whitespace-nowrap py-3 px-1 border-b-2 font-medium text-sm`}>
            Record Audio
          </button>
          <button onClick={() => setActiveTab('upload')} className={`${activeTab === 'upload' ? 'border-teal-400 text-teal-400' : 'border-transparent text-gray-400 hover:text-gray-200 hover:border-gray-400'} whitespace-nowrap py-3 px-1 border-b-2 font-medium text-sm`}>
            Upload File
          </button>
        </nav>
      </div>
      <div className="min-h-[150px] flex flex-col items-center justify-center">
        {activeTab === 'record' && (
          <div className="text-center">
            <button onClick={isRecording ? handleStopRecording : handleStartRecording} className={`p-4 rounded-full transition-colors ${isRecording ? 'bg-red-600 hover:bg-red-700' : 'bg-teal-500 hover:bg-teal-600'}`}>
              <MicrophoneIcon className="w-8 h-8"/>
            </button>
            <p className="mt-4 text-lg">{isRecording ? "Recording..." : "Tap to record"}</p>
          </div>
        )}
        {activeTab === 'upload' && (
          <div className="text-center w-full">
            <label htmlFor="audio-upload" className="cursor-pointer w-full border-2 border-dashed border-gray-600 rounded-lg p-8 flex flex-col items-center justify-center hover:bg-gray-700/50 transition-colors">
              <UploadIcon className="w-10 h-10 text-gray-400 mb-2"/>
              <span className="text-teal-400 font-semibold">Click to upload</span>
              <span className="text-gray-500 text-sm">MP3, WAV, WEBM, OGG</span>
            </label>
            <input id="audio-upload" type="file" accept="audio/*" className="hidden" onChange={handleFileChange} />
          </div>
        )}
      </div>
      {audioBlob && (
        <div className="my-4 p-3 bg-gray-700 rounded-lg text-center">
          <p className="text-sm">Audio ready for analysis.</p>
          <p className="text-xs text-gray-400">Size: {(audioBlob.size / 1024).toFixed(2)} KB</p>
        </div>
      )}
    </>
  );

  const renderAnalyzingView = () => (
    <div className="min-h-[250px] flex flex-col items-center justify-center text-center">
        <svg className="animate-spin h-10 w-10 text-teal-400 mb-4" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
        </svg>
        <h3 className="text-xl font-semibold">Analyzing Voice...</h3>
        <p className="text-gray-400 mt-2">The AI is learning the unique characteristics of the provided audio.</p>
    </div>
  );

  const renderRefiningView = () => (
    <div>
        <h3 className="text-xl font-bold text-teal-300 mb-2">Refine Voice Style</h3>
        <p className="text-gray-400 mb-4">The AI has generated a voice style based on your audio. You can edit the instruction below to fine-tune it before saving.</p>

        <div>
            <label htmlFor="voiceInstruction" className="block text-sm font-medium text-gray-300 mb-1">AI Voice Instruction</label>
            <textarea 
                id="voiceInstruction"
                value={editedInstruction}
                onChange={(e) => setEditedInstruction(e.target.value)}
                rows={5}
                className="w-full bg-gray-700 border border-gray-600 rounded-md p-2 text-sm text-white focus:ring-teal-500 focus:border-teal-500"
            />
        </div>
        <div className="mt-3 text-sm">
            <span className="font-semibold text-gray-300">Base Voice: </span>
            <span className="text-teal-400 bg-gray-700 px-2 py-1 rounded">{analysisResult?.baseVoice}</span>
        </div>
    </div>
  );

  return (
    <div className="fixed inset-0 bg-black/70 flex items-center justify-center z-50 transition-opacity" onClick={onClose}>
      <div className="bg-gray-800 rounded-lg shadow-xl w-full max-w-md p-6 text-white" onClick={(e) => e.stopPropagation()}>
        <h2 className="text-2xl font-bold mb-2 text-teal-300">Create a Custom Voice Style</h2>

        {view === 'initial' && renderInitialView()}
        {view === 'analyzing' && renderAnalyzingView()}
        {view === 'refining' && renderRefiningView()}

        {error && <p className="text-red-400 text-center my-2">{error}</p>}

        <div className="mt-6 flex justify-end gap-4">
          <button onClick={onClose} className="px-4 py-2 rounded-md bg-gray-600 hover:bg-gray-500 transition-colors">Cancel</button>

          {view === 'initial' && (
            <button 
              onClick={handleAnalyze} 
              disabled={!audioBlob}
              className="px-6 py-2 rounded-md bg-teal-600 hover:bg-teal-700 disabled:bg-gray-500 disabled:cursor-not-allowed transition-colors flex items-center"
            >
              Analyze Audio
            </button>
          )}

          {view === 'refining' && (
            <button 
              onClick={handleSave} 
              className="px-6 py-2 rounded-md bg-teal-600 hover:bg-teal-700 transition-colors flex items-center"
            >
              Save Voice Style
            </button>
          )}

        </div>
      </div>
    </div>
  );
};

