      <footer className="w-full bg-gray-800 border-t border-gray-700 p-2 flex justify-between items-center px-6 shrink-0">
        <span className="text-[7px] text-gray-600 uppercase tracking-[0.2em] font-black">Native Desktop Engine v1.1.1 • Store-Verified Metadata Build</span>
        <div className="flex items-center gap-4">
          <button onClick={handleExportVoice} className="text-[7px] text-teal-500/50 hover:text-teal-500 font-black uppercase tracking-widest transition-colors">Export .aivoice Identity</button>
          <span className="text-[7px] text-teal-500/50 uppercase tracking-[0.1em] font-black">© 2025 Spencer Littlewood</span>
        </div>
      </footer>

      {error && (
        <div className="fixed bottom-6 right-6 bg-red-950/90 border border-red-500 text-red-200 p-4 rounded-xl shadow-2xl max-w-sm z-[300]">
          <p className="text-xs">{error}</p>
        </div>
      )}
      <CustomVoiceModal isOpen={isCustomVoiceModalOpen} onClose={() => setIsCustomVoiceModalOpen(false)} onSave={handleSaveCustomVoice} />
      <ApiKeyModal isOpen={isApiKeyModalOpen} onClose={() => setIsApiKeyModalOpen(false)} onSave={handleSaveApiKey} initialResembleKey={resembleKey} initialElevenLabsKey={elevenLabsKey} />
      <PronunciationModal isOpen={isPronunciationModalOpen} onClose={() => setIsPronunciationModalOpen(false)} rules={pronunciationRules} onSave={handleSavePronunciationRules} />
      <TutorialModal isOpen={isTutorialModalOpen} onClose={() => setIsTutorialModalOpen(false)} />
    </main>
  );
};

