const LANGUAGES = [
  'English (US)', 'English (UK)', 'Spanish (ES)', 'French (FR)', 'German (DE)', 
  'Hindi (IN)', 'Japanese (JP)', 'Chinese (ZH)', 'Korean (KR)', 'Portuguese (BR)',
  'Italian (IT)', 'Russian (RU)', 'Arabic (AR)', 'Turkish (TR)', 'Dutch (NL)',
