];

const App: React.FC = () => {
  const [mode, setMode] = useState<AppMode>('narration');
  const [isSessionActive, setIsSessionActive] = useState<boolean>(false);
  const [transcript, setTranscript] = useState<TranscriptMessage[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [emotion, setEmotion] = useState<string>('Neutral');
  const [style, setStyle] = useState<string>('Narrative');
  const [voice, setVoice] = useState<string>('Zephyr');

  const [isCustomVoiceModalOpen, setIsCustomVoiceModalOpen] = useState(false);
  const [customVoice, setCustomVoice] = useState<CustomVoice | null>(null);

  const [narrationProvider, setNarrationProvider] = useState<SvgProvider>('gemini-tts');
  const [elevenLabsVoiceId, setElevenLabsVoiceId] = useState<string>('');
  const [resembleProjectId, setResembleProjectId] = useState<string>('');
  const [resembleVoiceId, setResembleVoiceId] = useState<string>('');

  const [resembleKey, setResembleKey] = useState<string>('');
  const [elevenLabsKey, setElevenLabsKey] = useState<string>('');
  const [isApiKeyModalOpen, setIsApiKeyModalOpen] = useState<boolean>(false);
  const [isTutorialModalOpen, setIsTutorialModalOpen] = useState<boolean>(false);

  const defaultNarrationScript = `<speak>
  [Authoritative][Professional Gravitas]
  In the silence of the cosmic void, a single particle began its journey toward the dawn of time.

  <break time="800ms"/>

  [Whisper][Intimate]
  Can you feel it? The subtle shift in the neural landscape where machine and human identity finally converge?

  <break time="500ms"/>

  [Excitedly][Hyper-Energetic]
  Welcome to AI Voice Studio! We are now processing at speeds previously thought impossible, utilizing the full logic stack of Gemini 3 Pro for real-time semantic restructuring.

  [Instruction: Use a slightly questioning upward lilt on the following technical term]
  The singularity is no longer a theory; it is an audible reality.

  <break time="1200ms"/>

  [Solemnly][Narrative-Deep]
  Precision is the language of the universe. In the Semantic Math Prosody Library, we express the fundamental laws of nature with absolute clarity.

  <p>
    Consider Einstein's mass-energy equivalence:
    <prosody rate="85%" pitch="+2st">
      Energy, E, equals mass, m, times the square of the speed of light, c-squared.
    </prosody>
  </p>

  <break time="800ms"/>

  [Skeptical][Drawl]
  They said a machine could never master the irony of human speech. 
  [Whisper]
  But then again... they've been wrong before.

  <break time="1s"/>

  [Aged][Gentle]
  The light is fading now. We must prepare for the next production cycle.

  [Instruction: End with a profound, resonant tone that lingers in the lower frequencies]
  <break time="2000ms"/>

  Final master recording verified. Studio out.
</speak>`;

  const [narrationText, setNarrationText] = useState<string>(defaultNarrationScript);
  const [narrationVoiceKey, setNarrationVoiceKey] = useState<string>('Charon (Deep Male)');
  const [narrationVoiceStyle, setNarrationVoiceStyle] = useState<string>(narrationPrebuiltVoices['Charon (Deep Male)'].description);
  const [narrationBaseVoice, setNarrationBaseVoice] = useState<string>('Charon');
  const [narrationLanguage, setNarrationLanguage] = useState<string>('English (US)');
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [generationStatus, setGenerationStatus] = useState<string>('');
  const [audioUrl, setAudioUrl] = useState<string | null>(null);

  const [pronunciationRules, setPronunciationRules] = useState<PronunciationRule[]>([]);
  const [isPronunciationModalOpen, setIsPronunciationModalOpen] = useState(false);

  const sessionRef = useRef<any | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const nextStartTimeRef = useRef<number>(0);
  const currentInputTranscriptionRef = useRef<string>('');
  const currentOutputTranscriptionRef = useRef<string>('');

  useEffect(() => {
    const storedResembleKey = localStorage.getItem('resemble_api_key');
    const storedElevenLabsKey = localStorage.getItem('elevenlabs_api_key');
    const storedElevenLabsVoiceId = localStorage.getItem('elevenlabs_voice_id');
    const storedResembleProj = localStorage.getItem('resemble_project_id');
    const storedResembleVoice = localStorage.getItem('resemble_voice_id');
    const storedRules = localStorage.getItem('pronunciation_rules');
    const storedVoice = localStorage.getItem('custom_voice_profile');

    if (storedResembleKey) setResembleKey(storedResembleKey);
    if (storedElevenLabsKey) setElevenLabsKey(storedElevenLabsKey);
    if (storedElevenLabsVoiceId) setElevenLabsVoiceId(storedElevenLabsVoiceId);
    if (storedResembleProj) setResembleProjectId(storedResembleProj);
    if (storedResembleVoice) setResembleVoiceId(storedResembleVoice);

    if (storedRules) {
      try { setPronunciationRules(JSON.parse(storedRules)); } catch (e) {}
    }
    if (storedVoice) {
      try { setCustomVoice(JSON.parse(storedVoice)); } catch (e) {}
    }
  }, []);

  const handleSaveApiKey = (resemble: string, eleven: string) => {
    localStorage.setItem('resemble_api_key', resemble);
    localStorage.setItem('elevenlabs_api_key', eleven);
    setResembleKey(resemble);
    setElevenLabsKey(eleven);
  };

  const handleSavePronunciationRules = (rules: PronunciationRule[]) => {
    setPronunciationRules(rules);
    localStorage.setItem('pronunciation_rules', JSON.stringify(rules));
  };

  const handleSaveCustomVoice = (voiceData: CustomVoice) => {
    setCustomVoice(voiceData);
    localStorage.setItem('custom_voice_profile', JSON.stringify(voiceData));
    setVoice(voiceData.name);
    handleNarrationVoiceChange(voiceData.name);
    setIsCustomVoiceModalOpen(false);
  };

  const handleExportVoice = () => {
    let profileToExport = (customVoice && narrationVoiceKey === customVoice.name) ? customVoice : {
      name: narrationVoiceKey, instruction: narrationVoiceStyle, baseVoice: narrationBaseVoice
    };
    const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(profileToExport, null, 2));
    const dl = document.createElement('a');
    dl.setAttribute("href", dataStr);
    dl.setAttribute("download", `aivoice-${profileToExport.name.replace(/\s+/g, '-').toLowerCase()}.aivoice`);
    document.body.appendChild(dl);
    dl.click();
    dl.remove();
  };

  const applyPronunciationRules = (text: string): string => {
    if (pronunciationRules.length === 0) return text;
    let processedText = text;
    pronunciationRules.forEach(rule => {
      const regex = new RegExp(`\\b${rule.word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'gi');
      processedText = processedText.replace(regex, rule.alias);
    });
    return processedText;
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close(); sessionRef.current = null; }
    if (streamRef.current) { streamRef.current.getTracks().forEach((track) => track.stop()); streamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (inputAudioContextRef.current) { inputAudioContextRef.current.close(); inputAudioContextRef.current = null; }
    if (outputAudioContextRef.current) { sourcesRef.current.forEach(s => s.stop()); sourcesRef.current.clear(); outputAudioContextRef.current.close(); outputAudioContextRef.current = null; }
    setIsSessionActive(false);
    setTranscript([]);
  }, []);

  const startSession = async () => {
    setError(null); setTranscript([]); setIsSessionActive(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const systemInstruction = `You are a helpful AI assistant. You must speak aloud. Tone: ${emotion}. Style: ${style}. ${customVoice ? customVoice.instruction : ''}`;
      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      nextStartTimeRef.current = 0;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        config: {
          responseModalalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: (customVoice && voice === customVoice.name) ? customVoice.baseVoice : voice } } },
          systemInstruction,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
        },
        callbacks: {
          onopen: async () => {
            streamRef.current = await navigator.mediaDevices.getUserMedia({ audio: true });
            const source = inputAudioContextRef.current!.createMediaStreamSource(streamRef.current);
            scriptProcessorRef.current = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current.onaudioprocess = (e) => {
              const input = e.inputBuffer.getChannelData(0);
              const pcmBlob: Blob = { data: encode(new Uint8Array(new Int16Array(input.map(f => f * 32768)).buffer)), mimeType: 'audio/pcm;rate=16000' };
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessorRef.current);
            scriptProcessorRef.current.connect(inputAudioContextRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.serverContent?.inputTranscription) {
              currentInputTranscriptionRef.current += message.serverContent.inputTranscription.text;
              setTranscript(prev => [{ speaker: 'user', text: currentInputTranscriptionRef.current, isFinal: false }]);
            }
            if (message.serverContent?.outputTranscription) {
              currentOutputTranscriptionRef.current += message.serverContent.outputTranscription.text;
              setTranscript(prev => [...prev.filter(m => m.speaker === 'user'), { speaker: 'model', text: currentOutputTranscriptionRef.current, isFinal: false }]);
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              const audioBuffer = await decodeAudioData(decode(base64Audio), outputAudioContextRef.current!, 24000, 1);
              const s = outputAudioContextRef.current!.createBufferSource();
              s.buffer = audioBuffer;
              s.connect(outputAudioContextRef.current!.destination);
              const startTime = Math.max(outputAudioContextRef.current!.currentTime, nextStartTimeRef.current);
              s.start(startTime);
              nextStartTimeRef.current = startTime + audioBuffer.duration;
              sourcesRef.current.add(s);
              s.onended = () => sourcesRef.current.delete(s);
            }
          },
          onerror: (err: any) => { setError(`Error: ${err.message}`); stopSession(); },
          onclose: () => stopSession(),
        },
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setError(err.message); setIsSessionActive(false); }
  };

  const generateNarration = async () => {
    setIsGenerating(true); setGenerationStatus('Preparing Engine...'); setError(null); setAudioUrl(null);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      let ruleAppliedText = applyPronunciationRules(narrationText);

      // Advanced Universal Translation Layer
      if (narrationLanguage !== 'English (US)') {
        setGenerationStatus(`Translating to ${narrationLanguage}...`);
        const transResponse = await ai.models.generateContent({
          model: 'gemini-3-pro-preview',
          contents: `Translate the following script for high-end documentary narration into ${narrationLanguage}. 
          IMPORTANT: 
          1. Keep all SSML tags like <speak> or <break> intact.
          2. Keep all emotional cues in brackets like [Whisper] or [Excitedly] intact.
          3. Use the formal/literary register of the target language.

          Script:\n${ruleAppliedText}`
        });
        ruleAppliedText = transResponse.text || ruleAppliedText;
      }

      const chunks = splitTextIntoChunks(ruleAppliedText);
      const audioParts: Uint8Array[] = [];

      for (let i = 0; i < chunks.length; i++) {
        setGenerationStatus(`Synthesizing Part ${i + 1}/${chunks.length}...`);

        if (narrationProvider === 'elevenlabs') {
          const res = await fetch(`https://api.elevenlabs.io/v1/text-to-speech/${elevenLabsVoiceId}`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'xi-api-key': elevenLabsKey },
            body: JSON.stringify({ 
              text: chunks[i], 
              model_id: 'eleven_multilingual_v2'
            })
          });
          if (!res.ok) throw new Error(`ElevenLabs failure: ${res.statusText}`);
          audioParts.push(new Uint8Array(await res.arrayBuffer()));
        } else if (narrationProvider === 'resemble') {
          const res = await fetch(`https://app.resemble.ai/api/v2/projects/${resembleProjectId}/clips`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': `Token token=${resembleKey}` },
            body: JSON.stringify({ body: chunks[i], voice_uuid: resembleVoiceId })
          });
          if (!res.ok) throw new Error("Resemble AI failure");
          const data = await res.json();
          const audioFetch = await fetch(data.item.link);
          audioParts.push(new Uint8Array(await audioFetch.arrayBuffer()));
        } else {
          let modelName = 'gemini-2.5-flash-preview-tts';
          if (narrationProvider === 'gemini-3-flash') modelName = 'gemini-3-flash-preview';
          if (narrationProvider === 'gemini-3-pro') modelName = 'gemini-3-pro-preview';

          const res = await ai.models.generateContent({
              model: modelName,
              contents: [{ parts: [{ text: chunks[i] }] }],
              config: { 
                responseModalities: [Modality.AUDIO], 
                speechConfig: { 
                  voiceConfig: { 
                    prebuiltVoiceConfig: { voiceName: narrationBaseVoice } 
                  } 
                } 
              },
          });
          const base64 = res.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
          if (base64) audioParts.push(decode(base64));
        }
      }

      if (audioParts.length === 0) throw new Error("Synthesis produced no data.");

      const concatenated = concatenateBuffers(audioParts);
      const isEncoded = narrationProvider === 'elevenlabs' || narrationProvider === 'resemble';
      const finalBlob = isEncoded ? new globalThis.Blob([concatenated], { type: 'audio/mpeg' }) : pcmToWavBlob(concatenated, 24000, 1);
      setAudioUrl(URL.createObjectURL(finalBlob));
    } catch (err: any) { 
      console.error(err);
      setError(err.message); 
    } finally { 
      setIsGenerating(false); 
    }
  };

  const handleNarrationVoiceChange = (k: string) => {
    setNarrationVoiceKey(k);
    const p = narrationPrebuiltVoices[k] || (customVoice && k === customVoice.name ? { description: customVoice.instruction, voiceName: customVoice.baseVoice } : null);
    if (p) { setNarrationVoiceStyle(p.description); setNarrationBaseVoice(p.voiceName || 'Charon'); }
  };

  const allNarrationVoices: {[key: string]: any} = { ...narrationPrebuiltVoices };
  if (customVoice) allNarrationVoices[customVoice.name] = { description: customVoice.instruction };

  const renderNarrationMode = () => (
    <div className="flex-grow w-full max-w-4xl mx-auto p-4 flex flex-col gap-4 overflow-y-auto no-scrollbar scroll-container">
        <div className="flex-grow flex flex-col gap-4">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                <div>
                    <label className="block text-[9px] font-black text-gray-500 mb-1 uppercase tracking-widest">Synthesis Engine</label>
                    <select value={narrationProvider} onChange={(e) => setNarrationProvider(e.target.value as SvgProvider)} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-xs">
                      <option value="gemini-tts">Gemini 2.5 TTS</option>
                      <option value="gemini-3-flash">Gemini 3 Flash</option>
                      <option value="gemini-3-pro">Gemini 3 Pro</option>
                      <option value="elevenlabs">ElevenLabs Multilingual</option>
                      <option value="resemble">Resemble AI</option>
                    </select>
                </div>

                <div>
                    <label className="block text-[9px] font-black text-gray-500 mb-1 uppercase tracking-widest">Global Language</label>
                    <select value={narrationLanguage} onChange={(e) => setNarrationLanguage(e.target.value)} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-xs">
                        {LANGUAGES.map(lang => <option key={lang} value={lang}>{lang}</option>)}
                    </select>
                </div>

                 <div className="md:col-span-2 grid grid-cols-1 md:grid-cols-2 gap-4">
                    {narrationProvider === 'elevenlabs' ? (
                        <>
                            <div>
                                <label className="block text-[9px] font-black text-gray-500 mb-1 uppercase tracking-widest">Voice UUID</label>
                                <input type="text" value={elevenLabsVoiceId} onChange={(e) => {setElevenLabsVoiceId(e.target.value); localStorage.setItem('elevenlabs_voice_id', e.target.value)}} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-[10px]" placeholder="ElevenLabs Voice ID" />
                            </div>
                            <div className="flex items-end">
                                <span className="text-[8px] text-teal-500/50 uppercase italic leading-tight">Hybrid Multilingual v2 Enabled</span>
                            </div>
                        </>
                    ) : narrationProvider === 'resemble' ? (
                        <>
                            <div>
                                <label className="block text-[9px] font-black text-gray-500 mb-1 uppercase tracking-widest">Project ID</label>
                                <input type="text" value={resembleProjectId} onChange={(e) => {setResembleProjectId(e.target.value); localStorage.setItem('resemble_project_id', e.target.value)}} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-[10px]" placeholder="Resemble Project ID" />
                            </div>
                            <div>
                                <label className="block text-[9px] font-black text-gray-500 mb-1 uppercase tracking-widest">Voice UUID</label>
                                <input type="text" value={resembleVoiceId} onChange={(e) => {setResembleVoiceId(e.target.value); localStorage.setItem('resemble_voice_id', e.target.value)}} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-[10px]" placeholder="Voice UUID" />
                            </div>
                        </>
                    ) : (
                        <div className="md:col-span-2">
                            <label className="block text-[9px] font-black text-gray-500 mb-1 uppercase tracking-widest">Vocal Identity Profile</label>
                            <select value={narrationVoiceKey} onChange={(e) => handleNarrationVoiceChange(e.target.value)} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-xs" disabled={isGenerating}>
                                {Object.keys(allNarrationVoices).map((name) => <option key={name} value={name}>{name}</option>)}
                            </select>
                        </div>
                    )}
                </div>
            </div>

            <div className="flex flex-col flex-grow">
                 <label className="block text-[9px] font-black text-gray-500 mb-1 uppercase tracking-widest">Documentary Narrative Script (Universal Translation Active)</label>
                 <textarea value={narrationText} onChange={(e) => setNarrationText(e.target.value)} className="w-full flex-grow min-h-[350px] bg-gray-800 border border-gray-700 rounded-md p-3 text-white font-mono text-[11px] leading-relaxed no-scrollbar" disabled={isGenerating} />
            </div>

            <div className="flex justify-center mt-2">
                 <button onClick={generateNarration} disabled={isGenerating || !narrationText} className="px-10 py-4 rounded-xl bg-teal-600 hover:bg-teal-500 transition-all font-black uppercase text-xs tracking-[0.2em] shadow-xl shadow-teal-500/20 flex items-center">
                    {isGenerating ? <><svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>{generationStatus}</> : "Launch Production Pipeline"}
                </button>
            </div>
        </div>

        {audioUrl && (
            <div className="mt-4 p-4 bg-gray-800 rounded-lg border border-teal-900/50 shadow-2xl animate-in fade-in zoom-in duration-300">
                <audio controls src={audioUrl} className="w-full mb-4"></audio>
                <div className="flex gap-2">
                  <a href={audioUrl} download={`master-studio-${Date.now()}.wav`} className="flex-1 text-center px-4 py-3 rounded-md bg-teal-500 hover:bg-teal-600 font-bold uppercase text-[10px] tracking-widest">Download Studio Master</a>
                  {window.electronAPI && (
                    <button onClick={() => window.electronAPI?.showInFolder("")} className="px-4 py-3 rounded-md bg-gray-700 hover:bg-gray-600 font-bold uppercase text-[10px]">Open Production Folder</button>
                  )}
                </div>
            </div>
        )}
    </div>
  );

  return (
    <main className="bg-gray-900 text-white h-screen flex flex-col font-sans selection:bg-teal-500/30 overflow-hidden">
      <header className="w-full bg-gray-800/80 backdrop-blur-md border-b border-gray-700 p-4 flex flex-col items-center relative z-10 gap-4 shadow-xl shrink-0">
        <div className="flex items-center gap-3">
          <AppLogo />
          <div className="flex flex-col">
            <h1 className="text-3xl font-bold text-cyan-300 font-orbitron tracking-tighter" style={{ textShadow: '0 0 15px rgba(56, 249, 215, 0.4)' }}>AI Voice Studio</h1>
            <div className="flex items-center gap-2 -mt-1">
              <span className="text-[7px] bg-teal-500/10 text-teal-400 px-1.5 py-0.5 rounded border border-teal-500/20 font-black uppercase">Official Distribution</span>
              <p className="text-[8px] text-gray-500 uppercase tracking-[0.3em] font-bold">By Ajarn Spencer Littlewood</p>
            </div>
          </div>
        </div>
        <div className="w-full flex justify-between items-center max-w-sm">
             <div className="flex-1">
                <button onClick={() => setIsTutorialModalOpen(true)} className="text-gray-400 hover:text-teal-300 transition-all flex items-center gap-2 group">
                    <InformationCircleIcon className="w-8 h-8" />
                    <div className="flex flex-col items-start leading-none"><span className="text-[10px] font-black uppercase text-teal-500">Academy</span></div>
                </button>
            </div>
            <div className="inline-flex bg-gray-900 border border-gray-700 rounded-lg p-1">
                <button onClick={() => setMode('conversation')} className={`px-4 py-1.5 text-[10px] font-bold uppercase rounded-md transition-all ${mode === 'conversation' ? 'bg-teal-600' : 'text-gray-400'}`}>Chat</button>
                <button onClick={() => setMode('narration')} className={`px-4 py-1.5 text-[10px] font-bold uppercase rounded-md transition-all ${mode === 'narration' ? 'bg-teal-600' : 'text-gray-400'}`}>Studio</button>
            </div>
             <div className="flex-1 flex justify-end">
                <button onClick={() => setIsApiKeyModalOpen(true)} className="text-gray-400 hover:text-teal-300"><KeyIcon className="w-6 h-6" /></button>
            </div>
        </div>
      </header>

      <div className="flex-grow flex flex-col overflow-hidden">
        {mode === 'conversation' ? (
          <div className="flex-grow w-full max-w-4xl mx-auto p-4 overflow-y-auto no-scrollbar scroll-container">
             {transcript.map((msg, i) => (
                <div key={i} className={`flex items-start gap-4 mb-6 ${msg.speaker === 'user' ? 'justify-end' : ''}`}>
