            <div className="flex items-center gap-2 -mt-1">
              <span className="text-[7px] bg-teal-500/10 text-teal-400 px-1.5 py-0.5 rounded border border-teal-500/20 font-black uppercase tracking-widest">Studio Master Build</span>
            </div>
          </div>
        </div>
        <div className="w-full flex justify-between items-center max-w-sm">
             <button onClick={() => setIsTutorialModalOpen(true)} className="text-gray-400 hover:text-teal-300 transition-all flex items-center gap-2">
                <InformationCircleIcon className="w-6 h-6" />
             </button>
            <div className="inline-flex bg-gray-900 border border-gray-700 rounded-lg p-1">
