    const updated = customVoices.filter(v => v.id !== id);
    setCustomVoices(updated);
    localStorage.setItem('custom_voice_profiles', JSON.stringify(updated));
    if (selectedVoiceKey === id) setSelectedVoiceKey('Zephyr (Warm Female)');
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close(); sessionRef.current = null; }
    if (streamRef.current) { streamRef.current.getTracks().forEach((track) => track.stop()); streamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (inputAudioContextRef.current) { inputAudioContextRef.current.close(); inputAudioContextRef.current = null; }
    if (outputAudioContextRef.current) { sourcesRef.current.forEach(s => s.stop()); sourcesRef.current.clear(); outputAudioContextRef.current.close(); outputAudioContextRef.current = null; }
    setIsSessionActive(false);
  }, []);

  const startSession = async () => {
    setError(null); setIsSessionActive(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const customProfile = customVoices.find(v => v.id === selectedVoiceKey);
      const voiceInstruction = customProfile ? customProfile.instruction : '';
      const baseVoiceName = customProfile ? customProfile.baseVoice : (narrationPrebuiltVoices[selectedVoiceKey]?.voiceName || 'Zephyr');

      const systemInstruction = `You are a helpful AI assistant. TONALITY: ${voiceInstruction}. You must always respond with audio. Focus on clarity and professional narration style.`;

      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      nextStartTimeRef.current = 0;
      currentInputTranscriptionRef.current = '';
      currentOutputTranscriptionRef.current = '';

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: baseVoiceName } } },
          systemInstruction,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
        },
        callbacks: {
          onopen: async () => {
            streamRef.current = await navigator.mediaDevices.getUserMedia({ audio: true });
            const source = inputAudioContextRef.current!.createMediaStreamSource(streamRef.current);
            scriptProcessorRef.current = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current.onaudioprocess = (e) => {
              const input = e.inputBuffer.getChannelData(0);
              const pcmBlob: Blob = { data: encode(new Uint8Array(new Int16Array(input.map(f => f * 32768)).buffer)), mimeType: 'audio/pcm;rate=16000' };
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessorRef.current);
            scriptProcessorRef.current.connect(inputAudioContextRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.serverContent?.inputTranscription) {
              currentInputTranscriptionRef.current += message.serverContent.inputTranscription.text;
              setTranscript(prev => {
                const last = prev[prev.length - 1];
                if (last?.speaker === 'user' && !last.isFinal) {
                  return [...prev.slice(0, -1), { speaker: 'user', text: currentInputTranscriptionRef.current, isFinal: false }];
                }
                return [...prev, { speaker: 'user', text: currentInputTranscriptionRef.current, isFinal: false }];
              });
            }
            if (message.serverContent?.outputTranscription) {
              currentOutputTranscriptionRef.current += message.serverContent.outputTranscription.text;
              setTranscript(prev => {
                const last = prev[prev.length - 1];
                if (last?.speaker === 'model' && !last.isFinal) {
                  return [...prev.slice(0, -1), { speaker: 'model', text: currentOutputTranscriptionRef.current, isFinal: false }];
                }
                return [...prev, { speaker: 'model', text: currentOutputTranscriptionRef.current, isFinal: false }];
              });
            }
            if (message.serverContent?.turnComplete) {
              setTranscript(prev => prev.map(m => ({ ...m, isFinal: true })));
              currentInputTranscriptionRef.current = '';
              currentOutputTranscriptionRef.current = '';
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              const audioBuffer = await decodeAudioData(decode(base64Audio), outputAudioContextRef.current!, 24000, 1);
              const s = outputAudioContextRef.current!.createBufferSource();
              s.buffer = audioBuffer;
              s.connect(outputAudioContextRef.current!.destination);
              const startTime = Math.max(outputAudioContextRef.current!.currentTime, nextStartTimeRef.current);
              s.start(startTime);
              nextStartTimeRef.current = startTime + audioBuffer.duration;
              sourcesRef.current.add(s);
              s.onended = () => sourcesRef.current.delete(s);
            }
          },
          onerror: (err: any) => { setError(`Engine Error: ${err.message}`); stopSession(); },
          onclose: () => stopSession(),
        },
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setError(err.message); setIsSessionActive(false); }
  };

  const generateNarration = async () => {
    setIsGenerating(true); setGenerationStatus('Calibrating Neural Synthesis...'); setError(null); setAudioUrl(null);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      let ruleAppliedText = applyPronunciationRules(narrationText);

      // Translation Layer
      if (narrationLanguage !== 'English (US)') {
        setGenerationStatus(`Translating to ${narrationLanguage}...`);
        const transResponse = await ai.models.generateContent({
          model: 'gemini-3-pro-preview',
          contents: `Translate to ${narrationLanguage}. Keep SSML tags <speak>, <break>, and cues like [Whisper] intact. Script:\n${ruleAppliedText}`
        });
        ruleAppliedText = transResponse.text || ruleAppliedText;
      }

      const customProfile = customVoices.find(v => v.id === selectedVoiceKey);
      const voiceNameForApi = customProfile ? customProfile.baseVoice : (narrationPrebuiltVoices[selectedVoiceKey]?.voiceName || 'Zephyr');

      const chunks = splitTextIntoChunks(ruleAppliedText);
      const audioParts: Uint8Array[] = [];

      for (let i = 0; i < chunks.length; i++) {
        setGenerationStatus(`Processing Segment ${i + 1}/${chunks.length}...`);

        if (narrationProvider === 'elevenlabs') {
          const res = await fetch(`https://api.elevenlabs.io/v1/text-to-speech/${elevenLabsVoiceId}`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'xi-api-key': elevenLabsKey },
            body: JSON.stringify({ text: chunks[i], model_id: 'eleven_multilingual_v2' })
          });
          if (!res.ok) throw new Error("ElevenLabs authentication or capacity error.");
          audioParts.push(new Uint8Array(await res.arrayBuffer()));
        } else if (narrationProvider === 'resemble') {
          const res = await fetch(`https://app.resemble.ai/api/v2/projects/${resembleProjectId}/clips`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': `Token token=${resembleKey}` },
            body: JSON.stringify({ body: chunks[i], voice_uuid: resembleVoiceId })
          });
          const data = await res.json();
          const audioFetch = await fetch(data.item.link);
          audioParts.push(new Uint8Array(await audioFetch.arrayBuffer()));
        } else {
          // Force gemini-2.5-flash-preview-tts for high-quality audio synthesis
          const res = await ai.models.generateContent({
              model: 'gemini-2.5-flash-preview-tts',
              contents: [{ parts: [{ text: customProfile ? `[Instruction: ${customProfile.instruction}] ${chunks[i]}` : chunks[i] }] }],
              config: { 
                responseModalities: [Modality.AUDIO], 
                speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: voiceNameForApi } } } 
              },
          });
          const base64 = res.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
          if (base64) audioParts.push(decode(base64));
        }
      }

      const concatenated = concatenateBuffers(audioParts);
      const isEncoded = narrationProvider === 'elevenlabs' || narrationProvider === 'resemble';
      setAudioUrl(URL.createObjectURL(isEncoded ? new globalThis.Blob([concatenated], { type: 'audio/mpeg' }) : pcmToWavBlob(concatenated, 24000, 1)));
    } catch (err: any) { setError(err.message); } finally { setIsGenerating(false); }
  };

  const applyPronunciationRules = (text: string) => {
    let processed = text;
    pronunciationRules.forEach(r => processed = processed.replace(new RegExp(`\\b${r.word}\\b`, 'gi'), r.alias));
    return processed;
  };

  const renderVoiceSelector = () => (
    <div className="flex items-center gap-2">
      <div className="flex-grow">
        <label className="block text-[9px] font-black text-gray-500 mb-1 uppercase tracking-widest">Neural Vocal Identity</label>
        <div className="relative">
          <select 
            value={selectedVoiceKey} 
            onChange={(e) => setSelectedVoiceKey(e.target.value)} 
            className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-xs appearance-none pr-8 focus:ring-1 focus:ring-teal-500/50"
          >
            <optgroup label="Prebuilt Studio Profiles" className="bg-gray-900">
              {Object.keys(narrationPrebuiltVoices).map(v => <option key={v} value={v}>{v}</option>)}
            </optgroup>
            {customVoices.length > 0 && (
              <optgroup label="Saved Neural Identities" className="bg-gray-900">
                {customVoices.map(v => <option key={v.id} value={v.id}>{v.name}</option>)}
              </optgroup>
            )}
          </select>
          <div className="absolute inset-y-0 right-0 flex items-center pr-2 pointer-events-none opacity-50">
            <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 9l-7 7-7-7"></path></svg>
          </div>
        </div>
      </div>
      <div className="flex items-end h-full pt-4 gap-1">
        <button 
          onClick={() => setIsCustomVoiceModalOpen(true)} 
          className="p-2.5 bg-gray-800 border border-teal-500/30 rounded-md hover:bg-gray-700 text-teal-400 transition-all shadow-lg"
          title="Clone Identity"
        >
          <PlusIcon className="w-4 h-4" />
        </button>
        {selectedVoiceKey.startsWith('custom-') && (
           <button 
            onClick={(e) => handleDeleteVoice(selectedVoiceKey, e)} 
            className="p-2.5 bg-gray-800 border border-red-500/30 rounded-md hover:bg-red-950/30 text-red-400 transition-all"
            title="Delete Identity"
          >
            <TrashIcon className="w-4 h-4" />
          </button>
        )}
      </div>
    </div>
  );

  return (
    <main className="bg-gray-900 text-white h-screen flex flex-col font-sans selection:bg-teal-500/30 overflow-hidden">
      <header className="w-full bg-gray-800/80 backdrop-blur-md border-b border-gray-700 p-4 flex flex-col items-center relative z-10 gap-4 shadow-xl shrink-0">
        <div className="flex items-center gap-3">
          <AppLogo />
          <div className="flex flex-col">
            <h1 className="text-3xl font-bold text-cyan-300 font-orbitron tracking-tighter">AI Voice Studio</h1>
            <div className="flex items-center gap-2 -mt-1">
              <span className="text-[7px] bg-teal-500/10 text-teal-400 px-1.5 py-0.5 rounded border border-teal-500/20 font-black uppercase tracking-widest">Documentary Narrative Suite</span>
            </div>
          </div>
        </div>
        <div className="w-full flex justify-between items-center max-w-sm">
             <button onClick={() => setIsTutorialModalOpen(true)} className="text-gray-400 hover:text-teal-300 transition-all">
                <InformationCircleIcon className="w-6 h-6" />
             </button>
            <div className="inline-flex bg-gray-900 border border-gray-700 rounded-lg p-1">
                <button onClick={() => { stopSession(); setMode('conversation'); }} className={`px-4 py-1.5 text-[10px] font-bold uppercase rounded-md transition-all ${mode === 'conversation' ? 'bg-teal-600 shadow-lg' : 'text-gray-400 hover:text-gray-200'}`}>Chat</button>
                <button onClick={() => { stopSession(); setMode('narration'); }} className={`px-4 py-1.5 text-[10px] font-bold uppercase rounded-md transition-all ${mode === 'narration' ? 'bg-teal-600 shadow-lg' : 'text-gray-400 hover:text-gray-200'}`}>Studio</button>
            </div>
             <button onClick={() => setIsApiKeyModalOpen(true)} className="text-gray-400 hover:text-teal-300"><KeyIcon className="w-6 h-6" /></button>
        </div>
      </header>

      <div className="flex-grow flex flex-col overflow-hidden relative">
        {mode === 'conversation' ? (
          <div className="flex-grow w-full max-w-4xl mx-auto flex flex-col p-4 overflow-hidden relative">
            <div className="flex gap-4 mb-4 items-center bg-gray-800/50 p-4 rounded-2xl border border-gray-700/50">
               <div className="flex-1">{renderVoiceSelector()}</div>
               <div className="text-[10px] text-teal-500/50 uppercase font-black tracking-widest px-4 border-l border-gray-700 animate-pulse">
                  Neural Sync Active
               </div>
            </div>

            <div className="flex-grow overflow-y-auto no-scrollbar scroll-container pb-28 space-y-4">
              {transcript.length === 0 && !isSessionActive && (
                <div className="h-full flex flex-col items-center justify-center text-center opacity-30">
                  <div className="p-10 rounded-full bg-gray-800 border border-gray-700 mb-4"><SparklesIcon className="w-20 h-20 text-teal-400" /></div>
                  <h3 className="text-xl font-black uppercase tracking-[0.3em] text-teal-500">Secure Link Required</h3>
                </div>
              )}
              {transcript.map((msg, i) => (
                <div key={i} className={`flex items-start gap-4 ${msg.speaker === 'user' ? 'justify-end' : ''} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
                  <div className={`p-4 rounded-2xl max-w-[85%] shadow-lg border ${msg.speaker === 'model' ? 'bg-gray-800 border-gray-700 text-teal-50' : 'bg-teal-900/40 border-teal-500/30 text-teal-100'}`}>
                    <div className="flex items-center gap-2 mb-1">
                      <span className={`text-[8px] font-black uppercase tracking-widest ${msg.speaker === 'model' ? 'text-teal-400' : 'text-teal-200'}`}>{msg.speaker === 'model' ? 'Cloned Engine' : 'User Input'}</span>
                      {!msg.isFinal && <span className="w-1.5 h-1.5 bg-teal-500 rounded-full animate-ping"></span>}
                    </div>
                    <p className="text-sm leading-relaxed font-medium">{msg.text || (msg.isFinal ? '...' : 'Processing identity cues...')}</p>
                  </div>
                </div>
              ))}
            </div>

            <div className="absolute bottom-6 left-1/2 -translate-x-1/2 w-full max-w-md px-4 flex items-center justify-between gap-4">
                <button onClick={() => setTranscript([])} disabled={transcript.length === 0} className="p-3 bg-gray-800 border border-gray-700 rounded-full hover:bg-gray-700 text-gray-400 disabled:opacity-20"><TrashIcon className="w-5 h-5" /></button>
                <div className="flex-grow flex justify-center">
                  <button onClick={isSessionActive ? stopSession : startSession} className={`flex items-center gap-3 px-10 py-4 rounded-full font-black uppercase text-xs tracking-[0.2em] transition-all shadow-2xl border ${isSessionActive ? 'bg-red-600 border-red-400/50 hover:bg-red-500' : 'bg-teal-600 border-teal-400/50 hover:bg-teal-500 shadow-teal-500/30'}`}>
                    {isSessionActive ? <><StopCircleIcon className="w-5 h-5" /> Terminate Link</> : <><MicrophoneIcon className="w-5 h-5" /> Establishing Sync</>}
                  </button>
                </div>
                <div className="w-11"></div>
            </div>
          </div>
        ) : (
          <div className="flex-grow w-full max-w-4xl mx-auto p-4 flex flex-col gap-4 overflow-y-auto no-scrollbar scroll-container">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 bg-gray-800/40 p-5 rounded-3xl border border-gray-700/50">
                <div>
                    <label className="block text-[9px] font-black text-gray-500 mb-1 uppercase tracking-widest">Synthesis Engine</label>
                    <select value={narrationProvider} onChange={(e) => setNarrationProvider(e.target.value as SvgProvider)} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-xs">
                      <option value="gemini-tts">Gemini Neural TTS</option>
                      <option value="gemini-3-pro">Gemini 3 Pro Audio</option>
                      <option value="elevenlabs">ElevenLabs v2</option>
                      <option value="resemble">Resemble AI</option>
                    </select>
                </div>
                <div>
                    <label className="block text-[9px] font-black text-gray-500 mb-1 uppercase tracking-widest">Global Localization</label>
                    <select value={narrationLanguage} onChange={(e) => setNarrationLanguage(e.target.value)} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-xs">
                        {LANGUAGES.map(lang => <option key={lang} value={lang}>{lang}</option>)}
                    </select>
                </div>
                <div className="md:col-span-2">
                  {narrationProvider === 'elevenlabs' ? (
                     <div className="grid grid-cols-2 gap-2">
                        <div>
                          <label className="block text-[9px] font-black text-gray-500 mb-1 uppercase tracking-widest">Voice ID</label>
                          <input type="text" value={elevenLabsVoiceId} onChange={(e) => setElevenLabsVoiceId(e.target.value)} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-[10px]" placeholder="ElevenLabs ID" />
                        </div>
                        <div className="flex items-end text-[8px] text-teal-400 font-black uppercase pb-3">Multilingual v2 Enabled</div>
                     </div>
                  ) : narrationProvider === 'resemble' ? (
                    <div className="grid grid-cols-2 gap-2">
                        <div>
                          <label className="block text-[9px] font-black text-gray-500 mb-1 uppercase tracking-widest">Voice UUID</label>
                          <input type="text" value={resembleVoiceId} onChange={(e) => setResembleVoiceId(e.target.value)} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-[10px]" placeholder="Resemble UUID" />
                        </div>
                        <div className="flex items-end text-[8px] text-teal-400 font-black uppercase pb-3">Rapid Clone Active</div>
                     </div>
                  ) : renderVoiceSelector()}
                </div>
            </div>

            <div className="flex flex-col flex-grow">
                 <label className="block text-[9px] font-black text-gray-500 mb-2 uppercase tracking-[0.2em]">Narrative Manuscript Editor</label>
                 <textarea value={narrationText} onChange={(e) => setNarrationText(e.target.value)} className="w-full flex-grow min-h-[450px] bg-gray-800 border border-gray-700 rounded-3xl p-6 text-white font-mono text-xs leading-relaxed no-scrollbar shadow-2xl" disabled={isGenerating} />
            </div>

            <div className="flex justify-center mb-4">
                 <button onClick={generateNarration} disabled={isGenerating || !narrationText} className="px-16 py-5 rounded-full bg-teal-600 hover:bg-teal-500 transition-all font-black uppercase text-[11px] tracking-[0.25em] shadow-2xl border border-teal-400/40 active:scale-95 flex items-center">
                    {isGenerating ? <><svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg>{generationStatus}</> : "Launch Production Phase"}
                </button>
            </div>

            {audioUrl && (
                <div className="mb-6 p-6 bg-gray-800/90 rounded-3xl border border-teal-500/20 shadow-2xl animate-in zoom-in duration-500">
                    <div className="flex justify-between items-center mb-4">
                        <span className="text-[10px] font-black uppercase tracking-widest text-teal-400">Master Audio Sequence Ready</span>
                    </div>
                    <audio controls src={audioUrl} className="w-full mb-4 rounded-full bg-gray-900"></audio>
                    <a href={audioUrl} download={`production-master-${Date.now()}.wav`} className="block text-center px-4 py-4 rounded-2xl bg-teal-500 hover:bg-teal-600 font-black uppercase text-xs tracking-widest transition-all shadow-xl">Export Studio Master</a>
                </div>
            )}
          </div>
        )}
      </div>

      <footer className="w-full bg-gray-800 border-t border-gray-700 p-2 flex justify-between items-center px-6 shrink-0">
        <span className="text-[7px] text-gray-600 uppercase tracking-[0.2em] font-black">Architecture v1.3.1 • Neural Identity Engine Active</span>
        <div className="text-[7px] font-black text-teal-500/50 uppercase tracking-widest">
          © 2025 Spencer Littlewood • Pro Distribution Build
        </div>
      </footer>

      {error && (
        <div className="fixed bottom-8 right-8 bg-red-950/95 border border-red-500 text-red-100 p-5 rounded-3xl shadow-2xl max-w-sm z-[300] animate-in slide-in-from-right-8 duration-500 backdrop-blur-md">
          <p className="text-[10px] font-black uppercase mb-2 tracking-widest text-red-400">Production Exception</p>
          <p className="text-xs leading-relaxed">{error}</p>
          <button onClick={() => setError(null)} className="absolute top-4 right-4 text-red-400 hover:text-white text-xl font-bold">&times;</button>
        </div>
      )}
      <CustomVoiceModal isOpen={isCustomVoiceModalOpen} onClose={() => setIsCustomVoiceModalOpen(false)} onSave={handleSaveCustomVoice} />
      <ApiKeyModal isOpen={isApiKeyModalOpen} onClose={() => setIsApiKeyModalOpen(false)} onSave={handleSaveApiKey} initialResembleKey={resembleKey} initialElevenLabsKey={elevenLabsKey} />
      <PronunciationModal isOpen={isPronunciationModalOpen} onClose={() => setIsPronunciationModalOpen(false)} rules={pronunciationRules} onSave={handleSavePronunciationRules} />
      <TutorialModal isOpen={isTutorialModalOpen} onClose={() => setIsTutorialModalOpen(false)} />
    </main>
  );
};

export default App;

