      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      nextStartTimeRef.current = 0;
      currentInputTranscriptionRef.current = '';
      currentOutputTranscriptionRef.current = '';

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-09-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: baseVoiceName } } },
          systemInstruction,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
        },
        callbacks: {
          onopen: async () => {
            streamRef.current = await navigator.mediaDevices.getUserMedia({ audio: true });
            const source = inputAudioContextRef.current!.createMediaStreamSource(streamRef.current);
            scriptProcessorRef.current = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current.onaudioprocess = (e) => {
              const input = e.inputBuffer.getChannelData(0);
              const pcmBlob: Blob = { data: encode(new Uint8Array(new Int16Array(input.map(f => f * 32768)).buffer)), mimeType: 'audio/pcm;rate=16000' };
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessorRef.current);
            scriptProcessorRef.current.connect(inputAudioContextRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.serverContent?.inputTranscription) {
              const text = message.serverContent.inputTranscription.text;
              currentInputTranscriptionRef.current += text;
              setTranscript(prev => {
                const last = prev[prev.length - 1];
                if (last?.speaker === 'user' && !last.isFinal) {
                  const updated = [...prev];
                  updated[updated.length - 1] = { ...last, text: currentInputTranscriptionRef.current };
                  return updated;
                }
                return [...prev, { speaker: 'user', text: currentInputTranscriptionRef.current, isFinal: false }];
              });
            }
            if (message.serverContent?.outputTranscription) {
              const text = message.serverContent.outputTranscription.text;
              currentOutputTranscriptionRef.current += text;
              setTranscript(prev => {
                const last = prev[prev.length - 1];
                if (last?.speaker === 'model' && !last.isFinal) {
                  const updated = [...prev];
                  updated[updated.length - 1] = { ...last, text: currentOutputTranscriptionRef.current };
                  return updated;
                }
                return [...prev, { speaker: 'model', text: currentOutputTranscriptionRef.current, isFinal: false }];
              });
            }
            if (message.serverContent?.turnComplete) {
              setTranscript(prev => prev.map(m => ({ ...m, isFinal: true })));
              currentInputTranscriptionRef.current = '';
              currentOutputTranscriptionRef.current = '';
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              const audioBuffer = await decodeAudioData(decode(base64Audio), outputAudioContextRef.current!, 24000, 1);
              const s = outputAudioContextRef.current!.createBufferSource();
              s.buffer = audioBuffer;
              s.connect(outputAudioContextRef.current!.destination);
              const startTime = Math.max(outputAudioContextRef.current!.currentTime, nextStartTimeRef.current);
              s.start(startTime);
              nextStartTimeRef.current = startTime + audioBuffer.duration;
              sourcesRef.current.add(s);
              s.onended = () => sourcesRef.current.delete(s);
            }
          },
          onerror: (err: any) => { setError(`Engine Exception: ${err.message}`); stopSession(); },
          onclose: () => stopSession(),
        },
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setError(err.message); setIsSessionActive(false); }
  };

  const generateNarration = async () => {
    setIsGenerating(true); setGenerationStatus('Calibrating Neural Synthesis...'); setError(null); setAudioUrl(null);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      let ruleAppliedText = narrationText;
      pronunciationRules.forEach(r => ruleAppliedText = ruleAppliedText.replace(new RegExp(`\\b${r.word}\\b`, 'gi'), r.alias));

      if (narrationLanguage !== 'English (US)') {
        setGenerationStatus(`Translating to ${narrationLanguage}...`);
        const transResponse = await ai.models.generateContent({
          model: 'gemini-3-pro-preview',
          contents: `Translate to ${narrationLanguage}. Keep SSML tags <speak>, <break>, <prosody> and emotional tokens [Whisper], [Authoritative] intact. Script:\n${ruleAppliedText}`
        });
        ruleAppliedText = transResponse.text || ruleAppliedText;
      }

      const customProfile = customVoices.find(v => v.id === selectedVoiceKey);
      const baseVoiceName = customProfile ? customProfile.baseVoice : (narrationPrebuiltVoices[selectedVoiceKey]?.voiceName || 'Charon');

      const chunks = splitTextIntoChunks(ruleAppliedText);
      const audioParts: Uint8Array[] = [];

      for (let i = 0; i < chunks.length; i++) {
        setGenerationStatus(`Synthesizing Sequence ${i + 1}/${chunks.length}...`);

        if (narrationProvider === 'elevenlabs') {
          const res = await fetch(`https://api.elevenlabs.io/v1/text-to-speech/${elevenLabsVoiceId}`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'xi-api-key': elevenLabsKey },
            body: JSON.stringify({ text: chunks[i], model_id: 'eleven_multilingual_v2' })
          });
          if (!res.ok) throw new Error("ElevenLabs engine failure.");
          audioParts.push(new Uint8Array(await res.arrayBuffer()));
        } else if (narrationProvider === 'resemble') {
           if (!resembleKey || !resembleProjectId || !resembleVoiceId) throw new Error("Missing Resemble AI Credentials.");
           const res = await fetch(`https://app.resemble.ai/api/v2/projects/${resembleProjectId}/clips`, {
             method: 'POST',
             headers: { 'Content-Type': 'application/json', 'Authorization': `Token token=${resembleKey}` },
             body: JSON.stringify({ body: chunks[i], voice_uuid: resembleVoiceId })
           });
           if (!res.ok) throw new Error("Resemble AI API error.");
           const data = await res.json();
           const audioFetch = await fetch(data.item.link);
           audioParts.push(new Uint8Array(await audioFetch.arrayBuffer()));
        } else {
          let targetModel = 'gemini-2.5-flash-preview-tts';
          if (narrationProvider === 'gemini-3-pro') targetModel = 'gemini-3-pro-preview';
          else if (narrationProvider === 'gemini-3-flash') targetModel = 'gemini-3-flash-preview';
          else if (narrationProvider === 'gemini-2.5-flash') targetModel = 'gemini-2.5-flash-native-audio-preview-09-2025';

          const res = await ai.models.generateContent({
              model: targetModel,
              contents: [{ parts: [{ text: customProfile ? `[Instruction: ${customProfile.instruction}] ${chunks[i]}` : chunks[i] }] }],
              config: { 
                responseModalities: [Modality.AUDIO], 
                speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: baseVoiceName } } } 
              },
          });
          const base64 = res.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
          if (base64) audioParts.push(decode(base64));
        }
      }
      const concatenated = concatenateBuffers(audioParts);
      const isMpeg = narrationProvider === 'elevenlabs' || narrationProvider === 'resemble';
      setAudioUrl(URL.createObjectURL(isMpeg ? new globalThis.Blob([concatenated], { type: 'audio/mpeg' }) : pcmToWavBlob(concatenated, 24000, 1)));
    } catch (err: any) { setError(err.message); } finally { setIsGenerating(false); }
  };

  const renderVoiceSelector = () => (
    <div className="flex items-center gap-2">
      <div className="flex-grow">
        <label className="block text-[9px] font-black text-gray-500 mb-1 uppercase tracking-widest">Neural Identity</label>
        <div className="relative">
          <select 
            value={selectedVoiceKey} 
            onChange={(e) => setSelectedVoiceKey(e.target.value)} 
            className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-xs appearance-none pr-8 focus:ring-1 focus:ring-teal-500/50"
          >
            <optgroup label="Studio Presets" className="bg-gray-900">
              {Object.keys(narrationPrebuiltVoices).map(v => <option key={v} value={v}>{v}</option>)}
            </optgroup>
            {customVoices.length > 0 && (
              <optgroup label="Custom Identities" className="bg-gray-900">
                {customVoices.map(v => <option key={v.id} value={v.id}>{v.name}</option>)}
              </optgroup>
            )}
          </select>
          <div className="absolute inset-y-0 right-0 flex items-center pr-2 pointer-events-none opacity-50">
            <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M19 9l-7 7-7-7" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/></svg>
          </div>
        </div>
      </div>
      <div className="flex items-end h-full pt-4 gap-1">
        <button onClick={() => setIsCustomVoiceModalOpen(true)} className="p-2.5 bg-gray-800 border border-teal-500/30 rounded-md hover:bg-gray-700 text-teal-400" title="Clone Voice"><PlusIcon className="w-4 h-4" /></button>
        {selectedVoiceKey.startsWith('custom-') && (
           <button onClick={(e) => handleDeleteVoice(selectedVoiceKey, e)} className="p-2.5 bg-gray-800 border border-red-500/30 rounded-md hover:bg-red-950/30 text-red-400" title="Delete Identity"><TrashIcon className="w-4 h-4" /></button>
        )}
      </div>
    </div>
  );

  return (
    <main className="bg-gray-900 text-white h-screen flex flex-col font-sans overflow-hidden">
      <header className="bg-gray-800 border-b border-gray-700 p-4 flex flex-col items-center gap-4 shrink-0 shadow-2xl">
        <div className="flex items-center gap-3">
          <AppLogo />
          <div className="flex flex-col">
            <h1 className="text-3xl font-bold text-cyan-300 font-orbitron tracking-tighter text-center">AI Voice Studio</h1>
            <div className="mt-2.5 text-center">
              <span className="text-[7px] bg-teal-500/10 text-teal-400 px-1.5 py-0.5 rounded border border-teal-500/20 font-black uppercase tracking-widest">Pro Documentary Suite</span>
            </div>
          </div>
        </div>
        <div className="w-full flex justify-between items-center max-w-md">
            <div className="flex items-center gap-4">
              <button onClick={() => setIsTutorialModalOpen(true)} className="text-gray-400 hover:text-teal-300" title="Academy Documentation"><InformationCircleIcon className="w-6 h-6" /></button>
              <button onClick={() => setIsPronunciationModalOpen(true)} className="text-gray-400 hover:text-teal-300" title="Pronunciation Guide"><BookOpenIcon className="w-6 h-6" /></button>
            </div>
            <div className="inline-flex bg-gray-900 border border-gray-700 rounded-lg p-1">
                <button onClick={() => { stopSession(); setMode('conversation'); }} className={`px-4 py-1.5 text-[10px] font-bold uppercase rounded-md transition-all ${mode === 'conversation' ? 'bg-teal-600 shadow-lg' : 'text-gray-400'}`}>Chat</button>
                <button onClick={() => { stopSession(); setMode('narration'); }} className={`px-4 py-1.5 text-[10px] font-bold uppercase rounded-md transition-all ${mode === 'narration' ? 'bg-teal-600 shadow-lg' : 'text-gray-400'}`}>Studio</button>
            </div>
             <button onClick={() => setIsApiKeyModalOpen(true)} className="text-gray-400 hover:text-teal-300" title="API Configuration"><KeyIcon className="w-6 h-6" /></button>
        </div>
      </header>

      <div className="flex-grow flex flex-col overflow-hidden relative">
        {mode === 'conversation' ? (
          <div className="flex-grow w-full max-w-4xl mx-auto flex flex-col p-4 relative">
            <div className="bg-gray-800/50 p-4 rounded-2xl border border-gray-700/50 mb-4 flex justify-between items-center">
               <div className="flex-grow max-w-xs">{renderVoiceSelector()}</div>
               <div className="flex items-center gap-3 ml-4">
                  <div className={`flex items-center gap-2 px-3 py-1 rounded-full border ${isSessionActive ? 'border-teal-500/40 bg-teal-500/10 text-teal-400' : 'border-gray-700 bg-gray-900 text-gray-500'}`}>
                    <span className={`w-2 h-2 rounded-full ${isSessionActive ? 'bg-teal-500 animate-pulse' : 'bg-gray-700'}`}></span>
                    <span className="text-[9px] font-black uppercase tracking-widest">{isSessionActive ? 'Link Active' : 'Standby'}</span>
                  </div>
               </div>
            </div>

            <div className="flex-grow overflow-y-auto no-scrollbar space-y-4 pb-32 scroll-container">
              {transcript.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center opacity-20 py-20">
                  <SparklesIcon className="w-16 h-16 text-teal-500 mb-4" />
                  <p className="text-xs font-black uppercase tracking-[0.3em]">Establishing Neural Sync...</p>
                </div>
              )}
              {transcript.map((msg, i) => (
                <div key={i} className={`flex items-start gap-4 ${msg.speaker === 'user' ? 'justify-end' : ''} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
                  <div className={`p-4 rounded-2xl max-w-[85%] border shadow-xl ${msg.speaker === 'model' ? 'bg-gray-800 border-gray-700 text-teal-50' : 'bg-teal-900/40 border-teal-500/30 text-teal-100'}`}>
                    <div className="flex items-center gap-2 mb-2">
                       <span className={`text-[8px] font-black uppercase tracking-widest px-1.5 py-0.5 rounded border ${msg.speaker === 'model' ? 'border-teal-500/30 text-teal-400' : 'border-teal-300/30 text-teal-200'}`}>
                        {msg.speaker === 'model' ? 'Neural Engine Output' : 'User Input Vector'}
                       </span>
                       {!msg.isFinal && <span className="w-1.5 h-1.5 bg-teal-500 rounded-full animate-ping"></span>}
                    </div>
                    <p className="text-sm leading-relaxed font-medium whitespace-pre-wrap">{msg.text || (msg.isFinal ? '...' : 'Processing identity cues...')}</p>
                  </div>
                </div>
              ))}
              <div ref={transcriptEndRef} />
            </div>

            <div className="absolute bottom-6 left-1/2 -translate-x-1/2 w-full max-w-lg flex items-center gap-4 px-4">
                <button 
                  onClick={() => setTranscript([])} 
                  disabled={transcript.length === 0} 
                  className="p-4 bg-gray-800 border border-gray-700 rounded-2xl hover:bg-gray-700 text-gray-500 hover:text-red-400 transition-all shadow-xl disabled:opacity-20"
                  title="Wipe Transcript Memory"
                >
                  <TrashIcon className="w-5 h-5" />
                </button>

                <div className="flex-grow">
                  {isSessionActive ? (
                    <button 
                      onClick={stopSession} 
                      className="w-full flex items-center justify-center gap-3 py-5 rounded-3xl bg-red-600 hover:bg-red-500 font-black uppercase text-xs tracking-[0.2em] border border-red-400/50 shadow-2xl transition-all active:scale-95"
                    >
                      <StopCircleIcon className="w-5 h-5" /> Terminate Link & Close
                    </button>
                  ) : (
                    <button 
                      onClick={startSession} 
                      className="w-full flex items-center justify-center gap-3 py-5 rounded-3xl bg-teal-600 hover:bg-teal-500 font-black uppercase text-xs tracking-[0.2em] border border-teal-400/50 shadow-2xl shadow-teal-500/30 transition-all active:scale-95"
                    >
                      <MicrophoneIcon className="w-5 h-5" /> Initialize Live Sync
                    </button>
                  )}
                </div>

                <button 
                  onClick={stopSession} 
                  disabled={!isSessionActive}
                  className="p-4 bg-gray-800 border border-gray-700 rounded-2xl hover:bg-gray-700 text-gray-400 transition-all shadow-xl disabled:opacity-20"
                  title="Close Live Connection"
                >
                  <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg>
                </button>
            </div>
          </div>
        ) : (
          <div className="flex-grow w-full max-w-5xl mx-auto p-4 flex flex-col gap-4 overflow-y-auto no-scrollbar scroll-container">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 bg-gray-800/40 p-5 rounded-3xl border border-gray-700/50">
                <div>
                    <label className="block text-[9px] font-black text-gray-500 mb-1 uppercase tracking-widest">Engine Architecture</label>
                    <select value={narrationProvider} onChange={(e) => setNarrationProvider(e.target.value as SvgProvider)} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-xs">
                      <option value="gemini-2.5-tts">Gemini 2.5 Flash TTS (Native)</option>
                      <option value="gemini-3-pro">Gemini 3 Pro (High Precision)</option>
                      <option value="gemini-3-flash">Gemini 3 Flash (Fast)</option>
                      <option value="gemini-2.5-flash">Gemini 2.5 Native Audio</option>
                      <option value="elevenlabs">ElevenLabs Multilingual v2</option>
                      <option value="resemble">Resemble AI (Rapid Clone)</option>
                    </select>
                </div>
                <div>
                    <label className="block text-[9px] font-black text-gray-500 mb-1 uppercase tracking-widest">Localization</label>
                    <select value={narrationLanguage} onChange={(e) => setNarrationLanguage(e.target.value)} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-xs">
                        {LANGUAGES.map(lang => <option key={lang} value={lang}>{lang}</option>)}
                    </select>
                </div>
                <div className="md:col-span-2">
                  {narrationProvider === 'elevenlabs' ? (
                     <div className="grid grid-cols-2 gap-2">
                        <div>
                           <label className="block text-[9px] font-black text-gray-500 mb-1 uppercase tracking-widest">Voice ID</label>
                           <input type="text" value={elevenLabsVoiceId} onChange={(e) => { setElevenLabsVoiceId(e.target.value); localStorage.setItem('elevenlabs_voice_id', e.target.value); }} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-[10px]" placeholder="ElevenLabs ID" />
                        </div>
                        <div className="flex items-end pb-3 text-[8px] text-teal-400 font-black uppercase">Engine Ready</div>
                     </div>
                  ) : narrationProvider === 'resemble' ? (
                     <div className="grid grid-cols-2 gap-2">
                        <div>
                           <label className="block text-[9px] font-black text-gray-500 mb-1 uppercase tracking-widest">Project / Voice UUID</label>
                           <div className="flex gap-1">
                             <input type="text" value={resembleProjectId} onChange={(e) => { setResembleProjectId(e.target.value); localStorage.setItem('resemble_project_id', e.target.value); }} className="flex-1 bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-[10px]" placeholder="Project ID" />
                             <input type="text" value={resembleVoiceId} onChange={(e) => { setResembleVoiceId(e.target.value); localStorage.setItem('resemble_voice_id', e.target.value); }} className="flex-1 bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-[10px]" placeholder="Voice ID" />
                           </div>
                        </div>
                        <div className="flex items-end pb-3 text-[8px] text-teal-400 font-black uppercase">Rapid-Clone Active</div>
                     </div>
                  ) : renderVoiceSelector()}
                </div>
            </div>
            <div className="flex flex-col flex-grow">
                 <label className="block text-[9px] font-black text-gray-500 mb-2 uppercase tracking-widest">Narrative Manuscript (Prosody & Emotion Stack Active)</label>
                 <textarea value={narrationText} onChange={(e) => setNarrationText(e.target.value)} className="w-full flex-grow min-h-[450px] bg-gray-800 border border-gray-700 rounded-3xl p-6 text-white font-mono text-xs leading-relaxed no-scrollbar shadow-2xl transition-all focus:ring-1 focus:ring-teal-500/30 outline-none" disabled={isGenerating} />
            </div>
            <div className="flex justify-center mb-6">
                 <button onClick={generateNarration} disabled={isGenerating || !narrationText} className="px-16 py-5 rounded-full bg-teal-600 hover:bg-teal-500 font-black uppercase text-[11px] tracking-widest border border-teal-400/40 shadow-2xl transition-all active:scale-95">
                    {isGenerating ? <div className="flex items-center gap-2"><svg className="animate-spin h-4 w-4 text-white" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg> {generationStatus}</div> : "Launch Production Pipeline"}
                </button>
            </div>
            {audioUrl && (
                <div className="mb-6 p-6 bg-gray-800 rounded-3xl border border-teal-500/20 shadow-2xl animate-in zoom-in duration-500">
                    <audio controls src={audioUrl} className="w-full mb-4 rounded-full bg-gray-900 border border-gray-700"></audio>
                    <a href={audioUrl} download={`studio-master-${Date.now()}.wav`} className="block text-center px-4 py-4 rounded-2xl bg-teal-500 hover:bg-teal-600 font-black uppercase text-xs tracking-widest transition-all">Download Production Master</a>
                </div>
            )}
          </div>
        )}
      </div>

      <footer className="bg-gray-800 border-t border-gray-700 p-2 flex justify-between px-6 shrink-0 text-[7px] font-black text-gray-600 uppercase tracking-widest">
        <span>v1.3.9 • Neural Identity Architecture Active • Spencer Littlewood</span>
        <span>© 2025 AI Voice Studio Master Production Suite</span>
      </footer>

      {error && (
        <div className="fixed bottom-8 right-8 bg-red-950/95 border border-red-500 text-red-100 p-5 rounded-3xl shadow-2xl max-w-sm z-[300] animate-in slide-in-from-right-8 duration-500">
          <p className="text-[10px] font-black uppercase mb-2 tracking-widest text-red-400 font-orbitron">Production Exception</p>
          <p className="text-xs leading-relaxed">{error}</p>
          <button onClick={() => setError(null)} className="absolute top-4 right-4 text-red-400 text-xl hover:text-white transition-all">&times;</button>
        </div>
      )}
      <CustomVoiceModal isOpen={isCustomVoiceModalOpen} onClose={() => setIsCustomVoiceModalOpen(false)} onSave={handleSaveCustomVoice} />
      <ApiKeyModal isOpen={isApiKeyModalOpen} onClose={() => setIsApiKeyModalOpen(false)} onSave={handleSaveApiKey} initialResembleKey={resembleKey} initialElevenLabsKey={elevenLabsKey} />
      <PronunciationModal isOpen={isPronunciationModalOpen} onClose={() => setIsPronunciationModalOpen(false)} rules={pronunciationRules} onSave={handleSavePronunciationRules} />
      <TutorialModal isOpen={isTutorialModalOpen} onClose={() => setIsTutorialModalOpen(false)} />
    </main>
  );
};

