        >
          <optgroup label="Core Studio Presets" className="bg-gray-900">
            {Object.keys(narrationPrebuiltVoices).map(v => <option key={v} value={v}>{v}</option>)}
          </optgroup>
          {customVoices.length > 0 && (
            <optgroup label="Induced Identities" className="bg-gray-900">
              {customVoices.map(v => <option key={v.id} value={v.id}>{v.name}</option>)}
            </optgroup>
          )}
        </select>
        <button 
          onClick={() => setIsCustomVoiceModalOpen(true)} 
          className="px-4 bg-teal-600/20 border border-teal-500/40 rounded-lg text-teal-400 hover:bg-teal-600/30 flex items-center gap-2 transition-all group"
        >
          <PlusIcon className="w-4 h-4" />
          <span className="text-[8px] font-black uppercase tracking-tighter">Induct New Identity</span>
        </button>
      </div>
    </div>
  );

  return (
    <main className="bg-gray-900 text-white h-screen flex flex-col font-sans overflow-hidden">
      <header className="bg-gray-800 border-b border-gray-700 p-4 flex flex-col items-center gap-4 shrink-0 shadow-2xl relative z-10">
        <div className="flex items-center gap-3">
          <AppLogo />
          <div className="flex flex-col">
            <h1 className="text-3xl font-bold text-cyan-300 font-orbitron tracking-tighter text-center">AI Voice Studio</h1>
            <div className="mt-2 text-center">
              <span className="text-[7px] bg-teal-500/10 text-teal-400 px-2 py-1 rounded border border-teal-500/20 font-black uppercase tracking-[0.2em]">Neural Synthesis Production Suite</span>
            </div>
          </div>
        </div>
        <div className="w-full flex justify-between items-center max-w-md">
            <div className="flex items-center gap-4">
              <button onClick={() => setIsTutorialModalOpen(true)} className="text-gray-400 hover:text-teal-300 transition-colors"><InformationCircleIcon className="w-6 h-6" /></button>
              <button onClick={() => setIsPronunciationModalOpen(true)} className="text-gray-400 hover:text-teal-300 transition-colors"><BookOpenIcon className="w-6 h-6" /></button>
            </div>
            <div className="inline-flex bg-gray-900 border border-gray-700 rounded-lg p-1">
                <button onClick={() => { stopSession(); setMode('conversation'); }} className={`px-4 py-1.5 text-[10px] font-bold uppercase rounded-md transition-all ${mode === 'conversation' ? 'bg-teal-600 shadow-lg' : 'text-gray-400'}`}>Chat</button>
                <button onClick={() => { stopSession(); setMode('narration'); }} className={`px-4 py-1.5 text-[10px] font-bold uppercase rounded-md transition-all ${mode === 'narration' ? 'bg-teal-600 shadow-lg' : 'text-gray-400'}`}>Studio</button>
            </div>
             <button onClick={() => setIsApiKeyModalOpen(true)} className="text-gray-400 hover:text-teal-300 transition-colors"><KeyIcon className="w-6 h-6" /></button>
        </div>
      </header>

      <div className="flex-grow flex flex-col overflow-hidden relative">
        {mode === 'conversation' ? (
          <div className="flex-grow w-full max-w-4xl mx-auto flex flex-col p-4 relative min-h-0">
            <div className="bg-gray-800/50 p-4 rounded-2xl border border-gray-700/50 mb-4 shrink-0">
               {renderGeminiVoiceSelector()}
            </div>
            <div className="flex-grow overflow-y-auto custom-scrollbar space-y-4 pb-32 scroll-container min-h-0 px-2">
              {transcript.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center opacity-20 py-20">
                  <SparklesIcon className="w-16 h-16 text-teal-500 mb-4" />
                  <p className="text-xs font-black uppercase tracking-[0.3em]">Neural Core Ready...</p>
                </div>
              )}
              {transcript.map((msg, i) => (
                <div key={i} className={`flex items-start gap-4 ${msg.speaker === 'user' ? 'justify-end' : ''} animate-in fade-in slide-in-from-bottom-2 duration-300`}>
                  <div className={`p-4 rounded-2xl max-w-[85%] border shadow-xl ${msg.speaker === 'model' ? 'bg-gray-800 border-gray-700 text-teal-50' : 'bg-teal-900/40 border-teal-500/30 text-teal-100'}`}>
                    <div className="flex items-center gap-2 mb-2">
                       <span className={`text-[8px] font-black uppercase tracking-widest px-1.5 py-0.5 rounded border ${msg.speaker === 'model' ? 'border-teal-500/30 text-teal-400' : 'border-teal-300/30 text-teal-200'}`}>
                        {msg.speaker === 'model' ? 'Neural Link' : 'Vocal Vector'}
                       </span>
                    </div>
                    <p className="text-sm leading-relaxed font-medium whitespace-pre-wrap">{msg.text || 'Processing signal...'}</p>
                  </div>
                </div>
              ))}
              <div ref={transcriptEndRef} />
            </div>
            <div className="absolute bottom-6 left-1/2 -translate-x-1/2 w-full max-w-lg flex items-center gap-4 px-4 z-20">
                <button onClick={() => setTranscript([])} className="p-4 bg-gray-900 border border-gray-700 rounded-2xl hover:bg-gray-800 text-gray-500 transition-all shadow-xl"><TrashIcon className="w-5 h-5" /></button>
                <div className="flex-grow">
                  <button onClick={isSessionActive ? stopSession : startSession} className={`w-full flex items-center justify-center gap-3 py-5 rounded-3xl font-black uppercase text-xs tracking-[0.2em] border shadow-2xl transition-all ${isSessionActive ? 'bg-red-600 border-red-400' : 'bg-teal-600 border-teal-400 shadow-teal-500/30'}`}>
                    {isSessionActive ? <><StopCircleIcon className="w-5 h-5" /> Terminate Link</> : <><MicrophoneIcon className="w-5 h-5" /> Initialize Sync</>}
                  </button>
                </div>
                <button onClick={stopSession} disabled={!isSessionActive} className="p-4 bg-gray-900 border border-gray-700 rounded-2xl hover:bg-gray-800 text-gray-400 transition-all shadow-xl disabled:opacity-20"><svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path></svg></button>
            </div>
          </div>
        ) : (
          <div className="flex-grow w-full max-w-5xl mx-auto p-4 flex flex-col gap-4 overflow-y-auto custom-scrollbar scroll-container">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 bg-gray-800/40 p-5 rounded-3xl border border-gray-700/50">
                <div>
                    <label className="block text-[9px] font-black text-gray-500 mb-1 uppercase tracking-widest">Synthesis Engine</label>
                    <select value={narrationProvider} onChange={(e) => setNarrationProvider(e.target.value as SvgProvider)} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-xs outline-none">
                      <option value="gemini-2.5-tts">Gemini 2.5 TTS (Induction)</option>
                      <option value="gemini-3-pro">Gemini 3 Pro (Precision)</option>
                      <option value="gemini-3-flash">Gemini 3 Flash (High-Speed)</option>
                      <option value="gemini-2.5-flash">Gemini 2.5 Native Audio</option>
                      <option value="elevenlabs">ElevenLabs (Account Clones)</option>
                      <option value="resemble">Resemble AI (Studio Clones)</option>
                    </select>
                </div>
                <div>
                    <label className="block text-[9px] font-black text-gray-500 mb-1 uppercase tracking-widest">Target Language</label>
                    <select value={narrationLanguage} onChange={(e) => setNarrationLanguage(e.target.value)} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-xs outline-none">
                        {LANGUAGES.map(lang => <option key={lang} value={lang}>{lang}</option>)}
                    </select>
                </div>
                <div className="md:col-span-2">
                  {narrationProvider === 'elevenlabs' ? (
                     <div className="flex flex-col gap-1">
                        <label className="text-[9px] font-black text-gray-500 uppercase tracking-widest">ElevenLabs Account Library</label>
                        <div className="flex gap-2">
                          <select 
                            value={elevenLabsVoiceId} 
                            onChange={(e) => setElevenLabsVoiceId(e.target.value)} 
                            className="flex-grow bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-xs outline-none"
                          >
                            <option value="">Select Account Voice...</option>
                            {elevenLabsVoices.map(v => <option key={v.id} value={v.id}>{v.name}</option>)}
                          </select>
                          <button onClick={syncExternalVoices} className="px-3 bg-gray-700 border border-gray-600 rounded-md text-teal-400 hover:text-white transition-all text-[10px] font-black uppercase">
                            {isSyncingVoices ? '...' : 'Sync'}
                          </button>
                        </div>
                     </div>
                  ) : narrationProvider === 'resemble' ? (
                     <div className="flex flex-col gap-1">
                        <label className="text-[9px] font-black text-gray-500 uppercase tracking-widest">Resemble Studio Voices</label>
                        <div className="grid grid-cols-2 gap-2">
                          <div className="flex gap-1">
                            <select 
                              value={resembleVoiceId} 
                              onChange={(e) => setResembleVoiceId(e.target.value)} 
                              className="flex-grow bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-xs outline-none"
                            >
                              <option value="">Select Voice...</option>
                              {resembleVoices.map(v => <option key={v.id} value={v.id}>{v.name}</option>)}
                            </select>
                            <button onClick={syncExternalVoices} className="px-3 bg-gray-700 border border-gray-600 rounded-md text-teal-400 hover:text-white transition-all text-[10px] font-black uppercase">Sync</button>
                          </div>
                          <input type="text" value={resembleProjectId} onChange={(e) => setResembleProjectId(e.target.value)} className="bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-[10px]" placeholder="Project UUID" title="Required for Resemble clips" />
                        </div>
                     </div>
                  ) : renderGeminiVoiceSelector()}
                </div>
            </div>
            <div className="flex flex-col flex-grow min-h-[300px]">
                 <label className="block text-[9px] font-black text-gray-500 mb-2 uppercase tracking-widest">Narrative Production Script</label>
                 <textarea value={narrationText} onChange={(e) => setNarrationText(e.target.value)} className="w-full flex-grow bg-gray-800 border border-gray-700 rounded-3xl p-6 text-white font-mono text-xs leading-relaxed custom-scrollbar shadow-2xl focus:ring-1 focus:ring-teal-500/30 outline-none" disabled={isGenerating} />
            </div>
            <div className="flex justify-center my-4">
                 <button onClick={generateNarration} disabled={isGenerating || !narrationText} className="px-20 py-5 rounded-full bg-teal-600 hover:bg-teal-500 font-black uppercase text-[11px] tracking-[0.2em] border border-teal-400/40 shadow-2xl transition-all active:scale-95">
                    {isGenerating ? <div className="flex items-center gap-3"><svg className="animate-spin h-5 w-5 text-white" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path></svg> {generationStatus}</div> : "Deploy Production Pipeline"}
                </button>
            </div>
            {audioUrl && (
                <div className="mb-6 p-6 bg-gray-800 rounded-3xl border border-teal-500/20 shadow-2xl animate-in zoom-in duration-500 flex flex-col gap-4">
                    <div className="flex justify-between items-center text-[9px] font-black uppercase text-teal-500 tracking-widest">
                        <span>Production Master Ready</span>
                        <span className="opacity-50">PCM 24bit / 48kHz Equivalent</span>
                    </div>
                    <audio controls src={audioUrl} className="w-full rounded-full bg-gray-900 border border-gray-700"></audio>
                    <a href={audioUrl} download={`studio-master-${Date.now()}.wav`} className="block text-center px-4 py-4 rounded-2xl bg-teal-500 hover:bg-teal-600 font-black uppercase text-xs tracking-widest transition-all shadow-lg shadow-teal-500/20">Download Documentary Master</a>
                </div>
            )}
          </div>
        )}
      </div>

      <footer className="bg-gray-800 border-t border-gray-700 p-2 flex justify-between px-6 shrink-0 text-[7px] font-black text-gray-600 uppercase tracking-widest relative z-10">
        <span>System v1.4.5 • Hybrid Identity Layer • Spencer Littlewood</span>
        <span>© 2025 Neural Synthesis Studio</span>
      </footer>

      {error && (
        <div className="fixed bottom-8 right-8 bg-red-950/95 border border-red-500 text-red-100 p-5 rounded-3xl shadow-2xl max-w-sm z-[300] animate-in slide-in-from-right-8 duration-500">
          <p className="text-[10px] font-black uppercase mb-2 tracking-widest text-red-400 font-orbitron">Engine Exception</p>
          <div className="max-h-40 overflow-y-auto custom-scrollbar pr-2">
            <p className="text-xs leading-relaxed">{error}</p>
          </div>
          <button onClick={() => setError(null)} className="absolute top-4 right-4 text-red-400 text-xl hover:text-white transition-all">&times;</button>
        </div>
      )}
      <CustomVoiceModal isOpen={isCustomVoiceModalOpen} onClose={() => setIsCustomVoiceModalOpen(false)} onSave={handleSaveCustomVoice} />
      <ApiKeyModal isOpen={isApiKeyModalOpen} onClose={() => setIsApiKeyModalOpen(false)} onSave={handleSaveApiKey} initialResembleKey={resembleKey} initialElevenLabsKey={elevenLabsKey} />
      <PronunciationModal isOpen={isPronunciationModalOpen} onClose={() => setIsPronunciationModalOpen(false)} rules={pronunciationRules} onSave={handleSavePronunciationRules} />
      <TutorialModal isOpen={isTutorialModalOpen} onClose={() => setIsTutorialModalOpen(false)} />
    </main>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { GoogleGenAI, Type } from '@google/genai';
import { MicrophoneIcon, UploadIcon, SparklesIcon } from './icons';

interface CustomVoiceModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (voice: { name: string; instruction: string; baseVoice: string }) => void;
}

type ModalView = 'initial' | 'analyzing' | 'refining';

export const CustomVoiceModal: React.FC<CustomVoiceModalProps> = ({ isOpen, onClose, onSave }) => {
  const [activeTab, setActiveTab] = useState<'record' | 'upload'>('record');
  const [isRecording, setIsRecording] = useState(false);
  const [audioBlob, setAudioBlob] = useState<Blob | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [view, setView] = useState<ModalView>('initial');
  const [analysisResult, setAnalysisResult] = useState<{ instruction: string; baseVoice: string } | null>(null);
  const [editedInstruction, setEditedInstruction] = useState('');
  const [voiceName, setVoiceName] = useState('');

  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);

  useEffect(() => {
    if (isOpen) {
      setView('initial');
      setAudioBlob(null);
      setError(null);
      setIsRecording(false);
      setAnalysisResult(null);
      setEditedInstruction('');
      setVoiceName('');
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const handleStartRecording = async () => {
    try {
      setError(null);
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      mediaRecorderRef.current = new MediaRecorder(stream);
      audioChunksRef.current = [];
      mediaRecorderRef.current.ondataavailable = (e) => audioChunksRef.current.push(e.data);
      mediaRecorderRef.current.onstop = () => setAudioBlob(new Blob(audioChunksRef.current, { type: 'audio/webm' }));
      mediaRecorderRef.current.start();
      setIsRecording(true);
    } catch (err) {
      setError("Microphone access denied.");
    }
  };

  const handleStopRecording = () => {
    if (mediaRecorderRef.current?.state === 'recording') {
      mediaRecorderRef.current.stop();
      setIsRecording(false);
      mediaRecorderRef.current.stream.getTracks().forEach(t => t.stop());
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file?.type.startsWith('audio/')) setAudioBlob(file);
    else setError("Invalid audio file.");
  };

  const handleAnalyze = async () => {
    if (!audioBlob) return;
    setView('analyzing');
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const reader = new FileReader();
      reader.readAsDataURL(audioBlob);
      await new Promise(r => reader.onload = r);
      const base64Audio = (reader.result as string).split(',')[1];

      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: { parts: [
          { inlineData: { mimeType: audioBlob.type, data: base64Audio } },
          { text: "Analyze the tone, pitch, and prosody of this voice. Provide a JSON object with 'instruction' (detailed description for AI mimicking) and 'baseVoice' (either 'Charon' or 'Kore' as the structural foundation)." }
        ]},
        config: {
          responseMimeType: 'application/json',
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              instruction: { type: Type.STRING },
              baseVoice: { type: Type.STRING }
            }
          }
        }
      });

      const parsed = JSON.parse(response.text);
      setAnalysisResult(parsed);
      setEditedInstruction(parsed.instruction);
      setVoiceName(`Inducted Identity ${Date.now().toString().slice(-4)}`);
      setView('refining');
    } catch (err) {
      setError("Neural analysis failed.");
      setView('initial');
    }
  };

  const handleSave = () => {
    if (!analysisResult) return;
    onSave({
      name: voiceName || "Custom Identity",
      instruction: editedInstruction,
      baseVoice: analysisResult.baseVoice,
    });
  };

  return (
    <div className="fixed inset-0 bg-black/90 flex items-center justify-center z-[250] p-4 backdrop-blur-md" onClick={onClose}>
      <div className="bg-gray-900 rounded-3xl shadow-2xl w-full max-w-md p-8 border border-teal-500/30 text-white" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center gap-3 mb-4">
           <SparklesIcon className="w-6 h-6 text-teal-400" />
           <h2 className="text-2xl font-bold text-teal-300 font-orbitron">Neural Induction</h2>
        </div>

        <p className="text-[10px] text-gray-400 uppercase tracking-widest mb-6 leading-relaxed">
           Induction creates a textual "blueprint" of your voice for Gemini engines. 
           For authentic clones, use ElevenLabs or Resemble library sync.
        </p>

        {view === 'initial' && (
          <div className="space-y-6">
            <div className="flex bg-gray-800 p-1 rounded-xl">
