            if (!chunkToSynthesize.startsWith('<speak>')) chunkToSynthesize = '<speak>' + chunkToSynthesize;
            if (!chunkToSynthesize.endsWith('</speak>')) chunkToSynthesize = chunkToSynthesize + '</speak>';
