                        <span className="opacity-50">PCM 24bit Equivalent</span>
                    </div>
                    <audio controls src={audioUrl} className="w-full rounded-full bg-gray-900 border border-gray-700"></audio>
                    <a href={audioUrl} download={`studio-master-${Date.now()}.wav`} className="block text-center px-4 py-4 rounded-2xl bg-teal-500 hover:bg-teal-600 font-black uppercase text-xs tracking-widest transition-all shadow-lg shadow-teal-500/20">Download Production Master</a>
                </div>
            )}
          </div>
        )}
      </div>

      <footer className="bg-gray-800 border-t border-gray-700 p-2 flex justify-between px-6 shrink-0 text-[7px] font-black text-gray-600 uppercase tracking-widest relative z-10">
        <span>System v1.5.0 • Mastering Architecture Active</span>
        <span>© 2025 AI Voice Studio Master Suite</span>
      </footer>

      {error && (
        <div className="fixed bottom-8 right-8 bg-red-950/95 border border-red-500 text-red-100 p-5 rounded-3xl shadow-2xl max-w-sm z-[300] animate-in slide-in-from-right-8 duration-500">
          <p className="text-[10px] font-black uppercase mb-2 tracking-widest text-red-400 font-orbitron">Engine Alert</p>
          <div className="max-h-40 overflow-y-auto custom-scrollbar pr-2">
            <p className="text-xs leading-relaxed">{error}</p>
          </div>
          <button onClick={() => setError(null)} className="absolute top-4 right-4 text-red-400 text-xl hover:text-white transition-all">&times;</button>
        </div>
      )}
      <CustomVoiceModal isOpen={isCustomVoiceModalOpen} onClose={() => setIsCustomVoiceModalOpen(false)} onSave={handleSaveCustomVoice} />
      <ApiKeyModal isOpen={isApiKeyModalOpen} onClose={() => setIsApiKeyModalOpen(false)} onSave={handleSaveApiKey} onShred={shredVault} initialResembleKey={resembleKey} initialElevenLabsKey={elevenLabsKey} initialAmnesiac={isAmnesiac} />
      <PronunciationModal isOpen={isPronunciationModalOpen} onClose={() => setIsPronunciationModalOpen(false)} rules={pronunciationRules} onSave={handleSavePronunciationRules} />
      <TutorialModal isOpen={isTutorialModalOpen} onClose={() => setIsTutorialModalOpen(false)} />
    </main>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { ArrowDownTrayIcon, TrashIcon } from './icons';

interface ApiKeyModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (resembleKey: string, elevenLabsKey: string, amnesiac: boolean) => void;
  onShred: () => void;
  initialResembleKey?: string;
  initialElevenLabsKey?: string;
  initialAmnesiac?: boolean;
}

export const ApiKeyModal: React.FC<ApiKeyModalProps> = ({ 
  isOpen, 
  onClose, 
  onSave, 
  onShred,
  initialResembleKey = '',
  initialElevenLabsKey = '',
  initialAmnesiac = true
}) => {
  const [resembleKey, setResembleKey] = useState(initialResembleKey);
  const [elevenLabsKey, setElevenLabsKey] = useState(initialElevenLabsKey);
  const [isAmnesiac, setIsAmnesiac] = useState(initialAmnesiac);
  const [hasGoogleKey, setHasGoogleKey] = useState(false);

  useEffect(() => {
    setResembleKey(initialResembleKey);
    setElevenLabsKey(initialElevenLabsKey);
    setIsAmnesiac(initialAmnesiac);

    if (typeof window.aistudio !== 'undefined') {
      window.aistudio.hasSelectedApiKey().then(has => {
        const revoked = sessionStorage.getItem('gemini_key_revoked') === 'true';
        setHasGoogleKey(has && !revoked);
      });
    }
  }, [initialResembleKey, initialElevenLabsKey, initialAmnesiac, isOpen]);

  if (!isOpen) return null;

  const handleSave = () => {
    onSave(resembleKey.trim(), elevenLabsKey.trim(), isAmnesiac);
    onClose();
  };

  const handleOpenGoogleSelect = async () => {
    if (typeof window.aistudio !== 'undefined') {
       await window.aistudio.openSelectKey();
       sessionStorage.removeItem('gemini_key_revoked');
       const hasKeyNow = await window.aistudio.hasSelectedApiKey();
       setHasGoogleKey(hasKeyNow);
    }
  };

  const handleRevokeGoogle = () => {
    sessionStorage.setItem('gemini_key_revoked', 'true');
    setHasGoogleKey(false);
  };

  const exportDotEnv = () => {
    const envContent = `# Generated by AI Voice Studio Production Master\nGEMINI_API_KEY=${process.env.API_KEY || 'SELECTED_IN_UI'}\nELEVENLABS_API_KEY=${elevenLabsKey}\nRESEMBLE_API_KEY=${resembleKey}`;
    const blob = new Blob([envContent], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = '.env';
    a.click();
    URL.revokeObjectURL(url);
  };

  const handleIndividualRevoke = (engine: 'eleven' | 'resemble') => {
    if (engine === 'eleven') setElevenLabsKey('');
    else setResembleKey('');
  };

  return (
    <div className="fixed inset-0 bg-black/98 flex items-center justify-center z-[200] p-4 backdrop-blur-xl" onClick={onClose}>
      <div className="bg-gray-900 rounded-3xl shadow-2xl w-full max-w-xl overflow-hidden border border-teal-500/20" onClick={(e) => e.stopPropagation()}>
        {/* Header */}
        <div className="p-6 bg-gray-800/80 border-b border-gray-700 flex justify-between items-center">
          <div>
            <h2 className="text-2xl font-black text-teal-300 font-orbitron tracking-tight uppercase">Security Vault</h2>
