      setCustomVoices(updated);
      localStorage.setItem('custom_voice_profiles', JSON.stringify(updated));
      setSelectedVoiceKey(voiceToEdit.id);
    } else {
      // Creating new voice
      const newVoice: CustomVoice = { ...voiceData, id: `custom-${Date.now()}` };
