// Improved chunking to respect sentence boundaries
const splitTextIntoChunks = (text: string, maxChars: number = 3000): string[] => {
  if (text.length <= maxChars) return [text];
  const chunks: string[] = [];
  let currentPos = 0;

  while (currentPos < text.length) {
    let endPos = currentPos + maxChars;
    if (endPos > text.length) endPos = text.length;

    if (endPos < text.length) {
      // Prioritize sentence terminators for cleaner prosody breaks
      const lastPeriod = text.lastIndexOf('. ', endPos);
      const lastQuestion = text.lastIndexOf('? ', endPos);
      const lastExclamation = text.lastIndexOf('! ', endPos);
      const lastNewline = text.lastIndexOf('\n', endPos);

      const breakPoint = Math.max(lastPeriod, lastQuestion, lastExclamation, lastNewline);

      if (breakPoint > currentPos) {
        endPos = breakPoint + 1; // Include the punctuation
      } else {
        // Fallback to space if no sentence end found
        const lastSpace = text.lastIndexOf(' ', endPos);
        if (lastSpace > currentPos) endPos = lastSpace;
      }
    }

    const chunk = text.substring(currentPos, endPos).trim();
    if (chunk.length > 0) chunks.push(chunk);
    currentPos = endPos;
  }
  return chunks;
};

