            <div className="bg-gray-800/30 p-3 rounded-xl border border-gray-700/50">
               <label className="block text-[9px] font-black text-teal-400 mb-1 uppercase tracking-widest">Voice Styling / Direction (Enforces Accent & Tone)</label>
               <input 
