      const systemInstruction = `You are a professional documentary narrator. Identity Tone: ${voiceInstruction}. Focus on technical accuracy and dramatic gravity.`;

      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      nextStartTimeRef.current = 0;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: baseVoiceName } } },
          systemInstruction,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
        },
        callbacks: {
          onopen: async () => {
            streamRef.current = await navigator.mediaDevices.getUserMedia({ audio: true });
            const source = inputAudioContextRef.current!.createMediaStreamSource(streamRef.current);
            scriptProcessorRef.current = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current.onaudioprocess = (e) => {
              const input = e.inputBuffer.getChannelData(0);
              const pcmBlob: Blob = { data: encode(new Uint8Array(new Int16Array(input.map(f => f * 32768)).buffer)), mimeType: 'audio/pcm;rate=16000' };
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessorRef.current);
            scriptProcessorRef.current.connect(inputAudioContextRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            if (message.serverContent?.inputTranscription) {
              const text = message.serverContent.inputTranscription.text;
              currentInputTranscriptionRef.current += text;
              setTranscript(prev => {
                const last = prev[prev.length - 1];
                if (last?.speaker === 'user' && !last.isFinal) {
                  const updated = [...prev];
                  updated[updated.length - 1] = { ...last, text: currentInputTranscriptionRef.current };
                  return updated;
                }
                return [...prev, { speaker: 'user', text: currentInputTranscriptionRef.current, isFinal: false }];
              });
            }
            if (message.serverContent?.outputTranscription) {
              const text = message.serverContent.outputTranscription.text;
              currentOutputTranscriptionRef.current += text;
              setTranscript(prev => {
                const last = prev[prev.length - 1];
                if (last?.speaker === 'model' && !last.isFinal) {
                  const updated = [...prev];
                  updated[updated.length - 1] = { ...last, text: currentOutputTranscriptionRef.current };
                  return updated;
                }
                return [...prev, { speaker: 'model', text: currentOutputTranscriptionRef.current, isFinal: false }];
              });
            }
            if (message.serverContent?.turnComplete) {
              setTranscript(prev => prev.map(m => ({ ...m, isFinal: true })));
              currentInputTranscriptionRef.current = '';
              currentOutputTranscriptionRef.current = '';
            }
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              const audioBuffer = await decodeAudioData(decode(base64Audio), outputAudioContextRef.current!, 24000, 1);
              const s = outputAudioContextRef.current!.createBufferSource();
              s.buffer = audioBuffer;
              s.connect(outputAudioContextRef.current!.destination);
              const startTime = Math.max(outputAudioContextRef.current!.currentTime, nextStartTimeRef.current);
              s.start(startTime);
              nextStartTimeRef.current = startTime + audioBuffer.duration;
              sourcesRef.current.add(s);
              s.onended = () => sourcesRef.current.delete(s);
            }
          },
          onerror: (err: any) => { setError(`Engine Exception: ${err.message}`); stopSession(); },
          onclose: () => stopSession(),
        },
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setError(err.message); setIsSessionActive(false); }
  };

  const generateNarration = async () => {
    if (!await ensureApiKey()) return;
    setIsGenerating(true); setGenerationStatus('Calibrating Neural Synthesis...'); setError(null); setAudioUrl(null);
    try {
      const apiKey = getEffectiveApiKey();
      const ai = new GoogleGenAI({ apiKey });
      let ruleAppliedText = narrationText;
      pronunciationRules.forEach(r => ruleAppliedText = ruleAppliedText.replace(new RegExp(`\\b${r.word}\\b`, 'gi'), r.alias));

      const isSsml = ruleAppliedText.includes('<speak>');
      const chunks = splitTextIntoChunks(ruleAppliedText);
      const audioParts: Uint8Array[] = [];

      for (let i = 0; i < chunks.length; i++) {
        setGenerationStatus(`Processing Segment ${i + 1}/${chunks.length}...`);

        let chunkToSynthesize = chunks[i];
        if (isSsml) {
            if (!chunkToSynthesize.trim().startsWith('<speak>')) chunkToSynthesize = '<speak>' + chunkToSynthesize;
            if (!chunkToSynthesize.trim().endsWith('</speak>')) chunkToSynthesize = chunkToSynthesize + '</speak>';
        }

        if (narrationLanguage !== 'English (US)') {
             setGenerationStatus(`Translating Segment ${i + 1}/${chunks.length} to ${narrationLanguage}...`);
             try {
                const transRes = await ai.models.generateContent({
                    model: 'gemini-3-flash-preview', 
                    contents: [{ parts: [{ text: `Translate the following documentary narration script into ${narrationLanguage}. \n\nDirectives:\n1. Maintain the exact SSML tags like <break> or <prosody> in their correct semantic position.\n2. Keep the tone dramatic, professional, and suitable for a documentary.\n3. Do not add any conversational preamble. Return ONLY the translated script.\n4. If the language is Sanskrit or Thai Pali, preserve the phonetic integrity for incantations and Romanized diacritics.\n\nScript:\n${chunkToSynthesize}` }] }]
                });
                if (transRes.text) {
                    chunkToSynthesize = transRes.text.trim();
                }
             } catch (tErr) {
                 console.warn("Translation failed for chunk " + i, tErr);
             }
        }

        setGenerationStatus(`Synthesizing Segment ${i + 1}/${chunks.length}...`);

        try {
          if (narrationProvider === 'elevenlabs') {
            const res = await fetch(`https://api.elevenlabs.io/v1/text-to-speech/${elevenLabsVoiceId}`, {
              method: 'POST',
              headers: { 'Content-Type': 'application/json', 'xi-api-key': elevenLabsKey },
              body: JSON.stringify({ text: chunkToSynthesize, model_id: 'eleven_multilingual_v2' })
            });
            if (!res.ok) throw new Error(`ElevenLabs API Failed.`);
            audioParts.push(new Uint8Array(await res.arrayBuffer()));
          } else if (narrationProvider === 'resemble') {
             const res = await fetch(`https://app.resemble.ai/api/v2/projects/${resembleProjectId}/clips`, {
               method: 'POST',
               headers: { 'Content-Type': 'application/json', 'Authorization': `Token token=${resembleKey}` },
               body: JSON.stringify({ body: chunkToSynthesize, voice_uuid: resembleVoiceId })
             });
             if (!res.ok) throw new Error(`Resemble AI API error.`);
             const data = await res.json();
             const audioFetch = await fetch(data.item.link);
             audioParts.push(new Uint8Array(await audioFetch.arrayBuffer()));
          } else {
            const customProfile = customVoices.find(v => v.id === selectedVoiceKey);
            const preset = narrationPrebuiltVoices[selectedVoiceKey];
            const baseVoiceName = customProfile ? customProfile.baseVoice : (preset?.voiceName || 'Charon');

            let accentInstruction = "";
            if (narrationLanguage.includes("UK")) accentInstruction = "British UK accent";
            else if (narrationLanguage !== 'English (US)') accentInstruction = `${narrationLanguage} accent`;

            const styleInstruction = voiceStyle ? `${voiceStyle} tone` : "";
            const identityInstruction = customProfile ? customProfile.instruction : (preset?.instruction || "");

            // Using a clearer structure for the TTS engine to minimize safety rejections
            let textPrompt = chunkToSynthesize;
            if (accentInstruction || styleInstruction || identityInstruction) {
                 const fullInstruction = [accentInstruction, styleInstruction, identityInstruction].filter(Boolean).join(", ");
                 textPrompt = `Voice Profile: ${fullInstruction}\n\nNarrative Text: ${chunkToSynthesize}`;
            }

            const res = await ai.models.generateContent({
                model: 'gemini-2.5-flash-preview-tts', 
                contents: [{ parts: [{ text: textPrompt }] }],
                config: { 
                  responseModalities: [Modality.AUDIO], 
                  speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: baseVoiceName } } },
                },
            });

            let base64: string | undefined;
            const candidate = res.candidates?.[0];

            if (candidate?.finishReason === 'SAFETY') {
                throw new Error(`Segment ${i+1} Blocked by Safety Filters. Try rephrasing the script.`);
            }

            if (candidate?.content?.parts) {
                for (const part of candidate.content.parts) {
                    if (part.inlineData?.data) { base64 = part.inlineData.data; break; }
                }
            }
            if (base64) {
                audioParts.push(decode(base64));
            } else {
                console.warn(`No audio data returned for segment ${i+1}. Finish Reason: ${candidate?.finishReason}`);
            }
          }
          await new Promise(r => setTimeout(r, 150));
        } catch (chunkErr: any) { throw new Error(`Segment ${i+1} Failed: ${chunkErr.message}`); }
      }

      if (audioParts.length === 0) {
         throw new Error("Pipeline returned no audio data. This may be due to a strict safety filter or transient API issues. Try a shorter script segment or check your API usage limits.");
      }

      const concatenated = concatenateBuffers(audioParts);
      const isMpeg = narrationProvider === 'elevenlabs' || narrationProvider === 'resemble';
      setAudioUrl(URL.createObjectURL(isMpeg ? new globalThis.Blob([concatenated], { type: 'audio/mpeg' }) : pcmToWavBlob(concatenated, 24000, 1)));
