type SvgProvider = 'gemini-2.5-tts' | 'gemini-3-pro' | 'gemini-3-flash' | 'gemini-2.5-flash' | 'elevenlabs' | 'resemble';

const narrationPrebuiltVoices: { [key: string]: { description: string; voiceName: string, instruction?: string } } = {
  'Charon (Deep Male)': { description: 'A very deep, resonant, and authoritative male voice.', voiceName: 'Charon' },
  'Zephyr (Warm Female)': { description: 'A warm and friendly female voice.', voiceName: 'Zephyr' },
  'Hyperion (Authoritative Male)': { description: 'Authoritative deep voice for documentary-style narration.', voiceName: 'Charon' },
  'Puck (Friendly Male)': { description: 'A friendly and engaging male voice.', voiceName: 'Puck' },
  'Fenrir (Serious Male)': { description: 'A serious, mature voice for formal narration.', voiceName: 'Fenrir' },
  'Kore (Clear Female)': { description: 'Clear neutral female voice.', voiceName: 'Kore' },
  'Aura (Calm Female)': { description: 'A calm, clear, and reassuring female voice.', voiceName: 'Kore' }
};

const LANGUAGES = [
  'Arabic (AR)', 'Aymara', 'Catalan', 'Cherokee', 'Chinese (ZH)', 'Danish', 'Dutch (NL)',
  'English (UK)', 'English (US)', 'Flemish', 'French (FR)', 'Georgian', 'German (DE)',
  'Guarani', 'Hindi (IN)', 'Indonesian (ID)', 'Italian (IT)', 'Japanese (JP)', 'Kannada',
  'Khmer', 'Korean (KR)', 'Lao', 'Latin', 'Latvian', 'Maltese', 'Maya (Yucatec)', 'Nahuatl',
  'Navajo', 'Nepali', 'Norwegian', 'Polish (PL)', 'Portuguese (BR)', 'Quechua', 'Russian (RU)',
  'Sanskrit (SA)', 'Sinhala', 'Spanish (ES)', 'Swedish (SE)', 'Tamil', 'Thai (TH)', 'Thai Pali (TH-PI)', 'Turkish (TR)', 'Vietnamese (VN)'
];

const MASTER_NARRATION_DEMO = `<speak>
  In the silence of the cosmic void, a single particle began its journey toward the dawn of time.
  <break time="1.5s"/>
  The neural landscape shifts where machine and human identity converge.
</speak>`;

const App: React.FC = () => {
  const [mode, setMode] = useState<AppMode>('narration');
  const [isSessionActive, setIsSessionActive] = useState<boolean>(false);
  const [transcript, setTranscript] = useState<TranscriptMessage[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [selectedVoiceKey, setSelectedVoiceKey] = useState<string>('Charon (Deep Male)');
  const [customVoices, setCustomVoices] = useState<CustomVoice[]>([]);
  const [isCustomVoiceModalOpen, setIsCustomVoiceModalOpen] = useState(false);
  const [voiceToEdit, setVoiceToEdit] = useState<CustomVoice | null>(null);

  const [narrationProvider, setNarrationProvider] = useState<SvgProvider>('gemini-2.5-tts');
  const [voiceStyle, setVoiceStyle] = useState<string>('');

  const [elevenLabsVoices, setElevenLabsVoices] = useState<ExternalVoice[]>([]);
  const [resembleVoices, setResembleVoices] = useState<ExternalVoice[]>([]);
  const [isSyncingVoices, setIsSyncingVoices] = useState(false);

  const [elevenLabsVoiceId, setElevenLabsVoiceId] = useState<string>('');
  const [resembleProjectId, setResembleProjectId] = useState<string>('');
  const [resembleVoiceId, setResembleVoiceId] = useState<string>('');

  const [resembleKey, setResembleKey] = useState<string>('');
  const [elevenLabsKey, setElevenLabsKey] = useState<string>('');
  const [isAmnesiac, setIsAmnesiac] = useState<boolean>(true);

  const [isApiKeyModalOpen, setIsApiKeyModalOpen] = useState<boolean>(false);
  const [isTutorialModalOpen, setIsTutorialModalOpen] = useState<boolean>(false);

  const [narrationText, setNarrationText] = useState<string>(MASTER_NARRATION_DEMO);
  const [narrationLanguage, setNarrationLanguage] = useState<string>('English (US)');
  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [generationStatus, setGenerationStatus] = useState<string>('');
  const [audioUrl, setAudioUrl] = useState<string | null>(null);
  const [pronunciationRules, setPronunciationRules] = useState<PronunciationRule[]>([]);
  const [isPronunciationModalOpen, setIsPronunciationModalOpen] = useState(false);

  const sessionRef = useRef<any | null>(null);
  const inputAudioContextRef = useRef<AudioContext | null>(null);
  const outputAudioContextRef = useRef<AudioContext | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const scriptProcessorRef = useRef<ScriptProcessorNode | null>(null);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const nextStartTimeRef = useRef<number>(0);
  const currentInputTranscriptionRef = useRef<string>('');
  const currentOutputTranscriptionRef = useRef<string>('');
  const transcriptEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const storedAmnesiac = localStorage.getItem('amnesiac_mode');
    const amnesiacStatus = storedAmnesiac === 'false' ? false : true;
    setIsAmnesiac(amnesiacStatus);
    const storedVoices = localStorage.getItem('custom_voice_profiles');
    const storedRules = localStorage.getItem('pronunciation_rules');
    if (storedVoices) try { setCustomVoices(JSON.parse(storedVoices)); } catch (e) {}
    if (storedRules) try { setPronunciationRules(JSON.parse(storedRules)); } catch (e) {}
    if (!amnesiacStatus) {
      setResembleKey(localStorage.getItem('resemble_api_key') || '');
      setElevenLabsKey(localStorage.getItem('elevenlabs_api_key') || '');
    }
  }, []);

  useEffect(() => { transcriptEndRef.current?.scrollIntoView({ behavior: 'smooth' }); }, [transcript]);

  const exportVoices = () => {
    const dataStr = JSON.stringify(customVoices, null, 2);
    const dataUri = 'data:application/json;charset=utf-8,' + encodeURIComponent(dataStr);
    const link = document.createElement('a');
    link.setAttribute('href', dataUri);
    link.setAttribute('download', 'custom_voices.json');
    link.click();
  };

  const importVoices = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'application/json';
    input.onchange = (e: any) => {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onload = (event: any) => {
        try {
          const imported = JSON.parse(event.target.result);
          if (Array.isArray(imported)) {
            const updated = [...customVoices, ...imported.filter(v => !customVoices.find(cv => cv.id === v.id))];
            setCustomVoices(updated);
            localStorage.setItem('custom_voice_profiles', JSON.stringify(updated));
          }
        } catch (err) { setError("Import failed: Invalid JSON"); }
      };
      reader.readAsText(file);
    };
    input.click();
  };

  const exportScript = () => {
    const dataUri = 'data:text/plain;charset=utf-8,' + encodeURIComponent(narrationText);
    const link = document.createElement('a');
    link.setAttribute('href', dataUri);
    link.setAttribute('download', 'narrative_script.txt');
    link.click();
  };

  const importScript = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'text/plain';
    input.onchange = (e: any) => {
      const file = e.target.files[0];
      const reader = new FileReader();
      reader.onload = (event: any) => { setNarrationText(event.target.result as string); };
      reader.readAsText(file);
    };
    input.click();
  };

  const syncExternalVoices = async () => {
    setIsSyncingVoices(true); setError(null);
    try {
      if (narrationProvider === 'elevenlabs' && elevenLabsKey) {
        const res = await fetch('https://api.elevenlabs.io/v1/voices', { headers: { 'xi-api-key': elevenLabsKey } });
        const data = await res.json();
        setElevenLabsVoices(data.voices.map((v: any) => ({ id: v.voice_id, name: v.name, provider: 'elevenlabs' })));
      } else if (narrationProvider === 'resemble' && resembleKey) {
        const res = await fetch('https://app.resemble.ai/api/v2/voices', { headers: { 'Authorization': `Token token=${resembleKey}` } });
        const data = await res.json();
        setResembleVoices(data.items.map((v: any) => ({ id: v.uuid, name: v.name, provider: 'resemble' })));
      }
    } catch (err: any) { setError(`Sync Error: ${err.message}`); } finally { setIsSyncingVoices(false); }
  };

  const handleSaveApiKey = (google: string, resemble: string, eleven: string, amnesiac: boolean) => {
    setIsAmnesiac(amnesiac); localStorage.setItem('amnesiac_mode', amnesiac ? 'true' : 'false');
    if (!amnesiac) {
      if(google) localStorage.setItem('gemini_api_key', google);
      if(resemble) localStorage.setItem('resemble_api_key', resemble);
      if(eleven) localStorage.setItem('elevenlabs_api_key', eleven);
    }
    setResembleKey(resemble); setElevenLabsKey(eleven);
  };

  const shredVault = () => {
    localStorage.clear(); sessionStorage.clear();
    setResembleKey(''); setElevenLabsKey(''); setIsAmnesiac(true); setCustomVoices([]); setPronunciationRules([]);
    window.location.reload();
  };

  const getEffectiveApiKey = () => localStorage.getItem('gemini_api_key') || process.env.API_KEY;

  const ensureApiKey = async (): Promise<boolean> => {
    if (typeof window.aistudio !== 'undefined') {
       const hasKey = await window.aistudio.hasSelectedApiKey();
       if (!hasKey) { await window.aistudio.openSelectKey(); return true; }
       return true;
    }
    if (!getEffectiveApiKey()) { setIsApiKeyModalOpen(true); return false; }
    return true;
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close(); sessionRef.current = null; }
    if (streamRef.current) { streamRef.current.getTracks().forEach((track) => track.stop()); streamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (inputAudioContextRef.current) { inputAudioContextRef.current.close(); inputAudioContextRef.current = null; }
    if (outputAudioContextRef.current) { sourcesRef.current.forEach(s => s.stop()); sourcesRef.current.clear(); outputAudioContextRef.current.close(); outputAudioContextRef.current = null; }
    setIsSessionActive(false);
  }, []);

  const startSession = async () => {
    if (!await ensureApiKey()) return;
    setError(null); setIsSessionActive(true);
    try {
      const apiKey = getEffectiveApiKey();
      const ai = new GoogleGenAI({ apiKey });
      const customProfile = customVoices.find(v => v.id === selectedVoiceKey);
      const voiceInstruction = customProfile ? customProfile.instruction : (narrationPrebuiltVoices[selectedVoiceKey]?.instruction || "");
      const baseVoiceName = customProfile ? customProfile.baseVoice : (narrationPrebuiltVoices[selectedVoiceKey]?.voiceName || 'Charon');
      const systemInstruction = `You are a professional documentary narrator. Identity Tone: ${voiceInstruction}. Focus on technical accuracy and dramatic gravity.`;

      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      nextStartTimeRef.current = 0;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: baseVoiceName } } },
          systemInstruction,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
        },
        callbacks: {
          onopen: async () => {
            streamRef.current = await navigator.mediaDevices.getUserMedia({ audio: true });
            const source = inputAudioContextRef.current!.createMediaStreamSource(streamRef.current);
            scriptProcessorRef.current = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current.onaudioprocess = (e) => {
              const input = e.inputBuffer.getChannelData(0);
              const pcmBlob: Blob = { data: encode(new Uint8Array(new Int16Array(input.map(f => f * 32768)).buffer)), mimeType: 'audio/pcm;rate=16000' };
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessorRef.current);
            scriptProcessorRef.current.connect(inputAudioContextRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              const audioBuffer = await decodeAudioData(decode(base64Audio), outputAudioContextRef.current!, 24000, 1);
              const s = outputAudioContextRef.current!.createBufferSource();
              s.buffer = audioBuffer;
              s.connect(outputAudioContextRef.current!.destination);
              const startTime = Math.max(outputAudioContextRef.current!.currentTime, nextStartTimeRef.current);
              s.start(startTime);
              nextStartTimeRef.current = startTime + audioBuffer.duration;
              sourcesRef.current.add(s);
            }
          },
          onerror: (err: any) => { setError(`Engine Exception: ${err.message}`); stopSession(); },
          onclose: () => stopSession(),
        },
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setError(err.message); setIsSessionActive(false); }
  };

  const generateNarration = async () => {
    if (!await ensureApiKey()) return;
    setIsGenerating(true); setGenerationStatus('Calibrating Neural Synthesis...'); setError(null); setAudioUrl(null);
    try {
      const apiKey = getEffectiveApiKey();
      const ai = new GoogleGenAI({ apiKey });
      let script = narrationText;
      pronunciationRules.forEach(r => script = script.replace(new RegExp(`\\b${r.word}\\b`, 'gi'), r.alias));

      const isSsmlInput = script.includes('<speak>');
      const chunks = splitTextIntoChunks(script);
      const audioParts: Uint8Array[] = [];

      for (let i = 0; i < chunks.length; i++) {
        setGenerationStatus(`Segment ${i + 1}/${chunks.length}...`);
        let chunk = chunks[i];

        if (narrationLanguage !== 'English (US)') {
             setGenerationStatus(`Optimizing Segment ${i + 1}...`);
             const isClassical = ['Sanskrit (SA)', 'Thai Pali (TH-PI)'].includes(narrationLanguage);
             const promptText = isClassical 
                ? `Orthographic Optimization: Preserve the following ${narrationLanguage} text exactly, but optimize its Romanized diacritics for phonetic clarity when read by an AI. Return ONLY optimized text.\n\nText:\n${chunk}`
                : `Translate the following documentary narration script into ${narrationLanguage}. Maintain SSML. Return ONLY translation.\n\nScript:\n${chunk}`;

             try {
                const transRes = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: [{ parts: [{ text: promptText }] }] });
                if (transRes.text) chunk = transRes.text.trim();
             } catch (tErr) { console.warn("Optimization failed", tErr); }
        }

        if (isSsmlInput) {
            if (!chunk.trim().startsWith('<speak>')) chunk = '<speak>' + chunk;
            if (!chunk.trim().endsWith('</speak>')) chunk = chunk + '</speak>';
        }

        try {
          const customProfile = customVoices.find(v => v.id === selectedVoiceKey);
          const preset = narrationPrebuiltVoices[selectedVoiceKey];
          const baseVoice = customProfile ? customProfile.baseVoice : (preset?.voiceName || 'Charon');
          const instructions = [
              narrationLanguage !== 'English (US)' ? `${narrationLanguage} accent` : '',
              voiceStyle ? `${voiceStyle} tone` : '',
              customProfile ? customProfile.instruction : (preset?.instruction || "")
          ].filter(Boolean).join(", ");

          const ttsPrompt = instructions ? `Phonetic Directive: ${instructions}\n\nNarrative Text:\n${chunk}` : chunk;

          const res = await ai.models.generateContent({
              model: 'gemini-2.5-flash-preview-tts', 
              contents: [{ parts: [{ text: ttsPrompt }] }],
              config: { responseModalities: [Modality.AUDIO], speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: baseVoice } } } },
          });

          if (res.candidates?.[0]?.finishReason === 'SAFETY') {
              const stripped = chunk.replace(/<[^>]*>/g, '');
              const resRetry = await ai.models.generateContent({
                  model: 'gemini-2.5-flash-preview-tts', 
                  contents: [{ parts: [{ text: `Directive: Narrate this text clearly.\n\nText:\n${stripped}` }] }],
                  config: { responseModalities: [Modality.AUDIO], speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: baseVoice } } } },
              });
              const base64Retry = resRetry.candidates?.[0]?.content?.parts?.find(p => p.inlineData)?.inlineData?.data;
              if (base64Retry) audioParts.push(decode(base64Retry));
              else throw new Error(`Segment ${i+1} Blocked by Safety Filters.`);
          } else {
              const base64 = res.candidates?.[0]?.content?.parts?.find(p => p.inlineData)?.inlineData?.data;
              if (base64) audioParts.push(decode(base64));
          }
          await new Promise(r => setTimeout(r, 200));
        } catch (err: any) { throw new Error(`Segment ${i+1} Failed: ${err.message}`); }
      }

      if (audioParts.length === 0) throw new Error("No audio generated. Check script safety.");
      const concatenated = concatenateBuffers(audioParts);
      setAudioUrl(URL.createObjectURL(pcmToWavBlob(concatenated, 24000, 1)));
    } catch (err: any) { setError(err.message); } finally { setIsGenerating(false); }
  };

  const renderGeminiVoiceSelector = () => (
    <div className="flex flex-col gap-2">
      <div className="flex justify-between items-center mb-1">
        <label className="text-[9px] font-black text-gray-500 uppercase tracking-widest">Neural Induction (Gemini Only)</label>
        <div className="flex gap-2">
           <button onClick={exportVoices} className="text-[8px] text-gray-500 hover:text-teal-400 font-black uppercase flex items-center gap-1 transition-colors"><ArrowDownTrayIcon className="w-3 h-3" /> Export Profiles</button>
           <button onClick={importVoices} className="text-[8px] text-gray-500 hover:text-teal-400 font-black uppercase flex items-center gap-1 transition-colors"><ArrowUpTrayIcon className="w-3 h-3" /> Import Profiles</button>
        </div>
      </div>
      <div className="flex gap-2">
        <select value={selectedVoiceKey} onChange={(e) => setSelectedVoiceKey(e.target.value)} className="flex-grow bg-gray-800 border border-gray-700 rounded-lg p-2 text-white text-xs outline-none focus:ring-1 focus:ring-teal-500/50">
          <optgroup label="Core Presets" className="bg-gray-900">
            {Object.keys(narrationPrebuiltVoices).map(v => <option key={v} value={v}>{v}</option>)}
          </optgroup>
          {customVoices.length > 0 && (
            <optgroup label="Inducted Blueprints" className="bg-gray-900">
              {customVoices.map(v => <option key={v.id} value={v.id}>{v.name}</option>)}
            </optgroup>
          )}
        </select>
        <button onClick={() => setIsCustomVoiceModalOpen(true)} className="px-4 bg-teal-600/20 border border-teal-500/40 rounded-lg text-teal-400 hover:bg-teal-600/30 flex items-center gap-2 transition-all">
          <SparklesIcon className="w-4 h-4" />
          <span className="text-[8px] font-black uppercase tracking-tighter">Clone</span>
        </button>
      </div>
    </div>
  );

  return (
    <main className="bg-gray-900 text-white h-screen flex flex-col font-sans overflow-hidden">
      <header className="bg-gray-800 border-b border-gray-700 p-4 flex flex-col items-center gap-4 shrink-0 shadow-2xl relative z-10">
        <div className="flex items-center gap-3">
          <AppLogo />
          <div className="flex flex-col">
            <h1 className="text-3xl font-bold text-cyan-300 font-orbitron tracking-tighter text-center">AI Voice Studio Plus</h1>
            <div className="mt-2 text-center">
              <span className="text-[7px] bg-teal-500/10 text-teal-400 px-2 py-1 rounded border border-teal-500/20 font-black uppercase tracking-[0.2em]">Professional Audio Production Master Suite</span>
            </div>
          </div>
        </div>
        <div className="w-full flex justify-between items-center max-w-md">
            <div className="flex items-center gap-4">
              <button onClick={() => setIsTutorialModalOpen(true)} className="text-gray-400 hover:text-teal-300 transition-colors"><InformationCircleIcon className="w-6 h-6" /></button>
              <button onClick={() => setIsPronunciationModalOpen(true)} className="text-gray-400 hover:text-teal-300 transition-colors"><BookOpenIcon className="w-6 h-6" /></button>
            </div>
            <div className="inline-flex bg-gray-900 border border-gray-700 rounded-lg p-1">
                <button onClick={() => setMode('conversation')} className={`px-4 py-1.5 text-[10px] font-bold uppercase rounded-md transition-all ${mode === 'conversation' ? 'bg-teal-600' : 'text-gray-400'}`}>Live Chat</button>
                <button onClick={() => setMode('narration')} className={`px-4 py-1.5 text-[10px] font-bold uppercase rounded-md transition-all ${mode === 'narration' ? 'bg-teal-600' : 'text-gray-400'}`}>Studio</button>
            </div>
             <button onClick={() => setIsApiKeyModalOpen(true)} className="text-gray-400 hover:text-teal-300 transition-colors"><KeyIcon className="w-6 h-6" /></button>
        </div>
      </header>

      <div className="flex-grow flex flex-col overflow-hidden relative">
        {mode === 'conversation' ? (
          <div className="flex-grow w-full max-w-4xl mx-auto flex flex-col p-4 relative min-h-0">
            <div className="bg-gray-800/50 p-4 rounded-2xl border border-gray-700/50 mb-4 shrink-0">
               {renderGeminiVoiceSelector()}
            </div>
            <div className="flex-grow overflow-y-auto space-y-4 pb-32 no-scrollbar scroll-container min-h-0 px-2">
              {transcript.map((msg, i) => (
                <div key={i} className={`flex items-start gap-4 ${msg.speaker === 'user' ? 'justify-end' : ''}`}>
                  <div className={`p-4 rounded-2xl max-w-[85%] border shadow-xl ${msg.speaker === 'model' ? 'bg-gray-800 border-gray-700 text-teal-50' : 'bg-teal-900/40 border-teal-500/30 text-teal-100'}`}>
                    <p className="text-sm leading-relaxed font-medium whitespace-pre-wrap">{msg.text || 'Syncing...'}</p>
                  </div>
                </div>
              ))}
              <div ref={transcriptEndRef} />
            </div>
            <div className="absolute bottom-6 left-1/2 -translate-x-1/2 w-full max-w-lg flex items-center gap-4 px-4 z-20">
                <button onClick={() => setTranscript([])} className="p-4 bg-gray-900 border border-gray-700 rounded-2xl hover:bg-gray-800 text-gray-500 transition-all"><TrashIcon className="w-5 h-5" /></button>
                <button onClick={isSessionActive ? stopSession : startSession} className={`flex-grow py-5 rounded-3xl font-black uppercase text-xs tracking-[0.2em] border shadow-2xl transition-all ${isSessionActive ? 'bg-red-600 border-red-400' : 'bg-teal-600 border-teal-400'}`}>
                  {isSessionActive ? 'Terminate Link' : 'Initialize Sync'}
                </button>
            </div>
          </div>
        ) : (
          <div className="flex-grow w-full max-w-5xl mx-auto p-4 flex flex-col gap-4 overflow-y-auto no-scrollbar scroll-container">
            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 bg-gray-800/40 p-5 rounded-3xl border border-gray-700/50">
                <div>
                    <label className="block text-[9px] font-black text-gray-500 mb-1 uppercase tracking-widest">Pipeline</label>
                    <select value={narrationProvider} onChange={(e) => setNarrationProvider(e.target.value as SvgProvider)} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-xs outline-none">
                      <option value="gemini-2.5-tts">Gemini 2.5 TTS</option>
                      <option value="gemini-3-flash">Gemini 3 Flash</option>
                      <option value="elevenlabs">ElevenLabs</option>
                    </select>
                </div>
                <div>
                    <label className="block text-[9px] font-black text-gray-500 mb-1 uppercase tracking-widest">Language Registry</label>
                    <select value={narrationLanguage} onChange={(e) => setNarrationLanguage(e.target.value)} className="w-full bg-gray-800 border border-gray-700 rounded-md p-2 text-white text-xs outline-none">
                        {LANGUAGES.map(lang => <option key={lang} value={lang}>{lang}</option>)}
                    </select>
                </div>
                <div className="md:col-span-2">
                  {renderGeminiVoiceSelector()}
                </div>
            </div>

            <div className="bg-gray-800/30 p-3 rounded-xl border border-gray-700/50">
               <label className="block text-[9px] font-black text-teal-400 mb-1 uppercase tracking-widest">Neural Styling / Direction (Override Engine)</label>
               <input type="text" value={voiceStyle} onChange={(e) => setVoiceStyle(e.target.value)} placeholder="e.g. Deep Baritone, Slow Meditative, Brahmanic Pronunciation, British Accent" className="w-full bg-gray-900 border border-gray-700 rounded-md p-2 text-white text-xs outline-none focus:border-teal-500/50" />
            </div>

            <div className="flex flex-col flex-grow min-h-[300px]">
                 <div className="flex justify-between items-center mb-2">
