      <CustomVoiceModal isOpen={isCustomVoiceModalOpen} onClose={() => setIsCustomVoiceModalOpen(false)} onSave={(v) => { 
        const newVoice: CustomVoice = { ...v, id: `custom-${Date.now()}` };
