  const getEffectiveApiKey = () => localStorage.getItem('gemini_api_key') || process.env.API_KEY;

  const ensureApiKey = async (): Promise<boolean> => {
    if (typeof window.aistudio !== 'undefined') {
       const hasKey = await window.aistudio.hasSelectedApiKey();
       if (!hasKey) { await window.aistudio.openSelectKey(); return true; }
       return true;
    }
    if (!getEffectiveApiKey()) { setIsApiKeyModalOpen(true); return false; }
    return true;
  };

  const stopSession = useCallback(() => {
    if (sessionRef.current) { sessionRef.current.close(); sessionRef.current = null; }
    if (streamRef.current) { streamRef.current.getTracks().forEach((track) => track.stop()); streamRef.current = null; }
    if (scriptProcessorRef.current) { scriptProcessorRef.current.disconnect(); scriptProcessorRef.current = null; }
    if (inputAudioContextRef.current) { inputAudioContextRef.current.close(); inputAudioContextRef.current = null; }
    if (outputAudioContextRef.current) { sourcesRef.current.forEach(s => s.stop()); sourcesRef.current.clear(); outputAudioContextRef.current.close(); outputAudioContextRef.current = null; }
    setIsSessionActive(false);
  }, []);

  const startSession = async () => {
    if (!await ensureApiKey()) return;
    setError(null); setIsSessionActive(true);
    try {
      const apiKey = getEffectiveApiKey();
      const ai = new GoogleGenAI({ apiKey });
      const customProfile = customVoices.find(v => v.id === selectedVoiceKey);
      const voiceInstruction = customProfile ? customProfile.instruction : (narrationPrebuiltVoices[selectedVoiceKey]?.instruction || "");
      const baseVoiceName = customProfile ? customProfile.baseVoice : (narrationPrebuiltVoices[selectedVoiceKey]?.voiceName || 'Charon');
      const systemInstruction = `You are a professional documentary narrator. Identity Tone: ${voiceInstruction}. Focus on technical accuracy and dramatic gravity.`;

      inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      nextStartTimeRef.current = 0;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: baseVoiceName } } },
          systemInstruction,
          inputAudioTranscription: {},
          outputAudioTranscription: {},
        },
        callbacks: {
          onopen: async () => {
            streamRef.current = await navigator.mediaDevices.getUserMedia({ audio: true });
            const source = inputAudioContextRef.current!.createMediaStreamSource(streamRef.current);
            scriptProcessorRef.current = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
            scriptProcessorRef.current.onaudioprocess = (e) => {
              const input = e.inputBuffer.getChannelData(0);
              const pcmBlob: Blob = { data: encode(new Uint8Array(new Int16Array(input.map(f => f * 32768)).buffer)), mimeType: 'audio/pcm;rate=16000' };
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessorRef.current);
            scriptProcessorRef.current.connect(inputAudioContextRef.current!.destination);
          },
          onmessage: async (message: LiveServerMessage) => {
            const base64Audio = message.serverContent?.modelTurn?.parts[0]?.inlineData?.data;
            if (base64Audio) {
              const audioBuffer = await decodeAudioData(decode(base64Audio), outputAudioContextRef.current!, 24000, 1);
              const s = outputAudioContextRef.current!.createBufferSource();
              s.buffer = audioBuffer;
              s.connect(outputAudioContextRef.current!.destination);
              const startTime = Math.max(outputAudioContextRef.current!.currentTime, nextStartTimeRef.current);
              s.start(startTime);
              nextStartTimeRef.current = startTime + audioBuffer.duration;
              sourcesRef.current.add(s);
            }
          },
          onerror: (err: any) => { setError(`Engine Exception: ${err.message}`); stopSession(); },
          onclose: () => stopSession(),
        },
      });
      sessionRef.current = await sessionPromise;
    } catch (err: any) { setError(err.message); setIsSessionActive(false); }
  };

  const generateNarration = async () => {
    if (!await ensureApiKey()) return;
    setIsGenerating(true); setGenerationStatus('Calibrating Neural Synthesis...'); setError(null); setAudioUrl(null);
    try {
      const apiKey = getEffectiveApiKey();
      const ai = new GoogleGenAI({ apiKey });
      let script = narrationText;
      pronunciationRules.forEach(r => script = script.replace(new RegExp(`\\b${r.word}\\b`, 'gi'), r.alias));

      const isSsmlInput = script.includes('<speak>');
      // Use smaller chunks for dense diacritic text to prevent safety blocks and timeouts
      const chunks = splitTextIntoChunks(script, 1000); 
      const audioParts: Uint8Array[] = [];

      for (let i = 0; i < chunks.length; i++) {
        setGenerationStatus(`Segment ${i + 1}/${chunks.length}...`);
        let chunk = chunks[i];

        const isDiacriticLanguage = ['Sanskrit (SA)', 'Thai Pali (TH-PI)', 'Diacritics (Sacred Text reader Only)'].includes(narrationLanguage);

        // Bypassing optimization for 'Diacritics (Sacred Text reader Only)' as users paste exact Romanized Pali
        // which often triggers safety blocks if the optimization model attempts to process large blocks of it.
        if (narrationLanguage !== 'English (US)' && narrationLanguage !== 'Diacritics (Sacred Text reader Only)') {
             setGenerationStatus(`Optimizing Segment ${i + 1}...`);
             const promptText = isDiacriticLanguage
                ? `Orthographic Optimization: Preserve the following ${narrationLanguage} text exactly, but optimize its Romanized diacritics for phonetic clarity when read by a Brahmanic/Vedic AI narrator. Return ONLY the script.\n\nScript:\n${chunk}`
                : `Translate the following documentary narration script into ${narrationLanguage}. Maintain SSML tags. Return ONLY translation.\n\nScript:\n${chunk}`;

             try {
                const transRes = await ai.models.generateContent({ model: 'gemini-3-flash-preview', contents: [{ parts: [{ text: promptText }] }] });
                if (transRes.text) chunk = transRes.text.trim();
             } catch (tErr) { console.warn("Optimization failed", tErr); }
        }

        if (isSsmlInput) {
            if (!chunk.trim().startsWith('<speak>')) chunk = '<speak>' + chunk;
            if (!chunk.trim().endsWith('</speak>')) chunk = chunk + '</speak>';
        }

        try {
          const customProfile = customVoices.find(v => v.id === selectedVoiceKey);
          const preset = narrationPrebuiltVoices[selectedVoiceKey];
          const baseVoice = customProfile ? customProfile.baseVoice : (preset?.voiceName || 'Charon');

          const instructions = [
              narrationLanguage !== 'English (US)' && narrationLanguage !== 'Diacritics (Sacred Text reader Only)' ? `${narrationLanguage} accent` : '',
              voiceStyle ? `${voiceStyle} tone` : '',
              customProfile ? customProfile.instruction : (preset?.instruction || "")
          ].filter(Boolean).join(", ");

          // Safety-Hardened Phonetic Directive
          const ttsPrompt = instructions ? `Phonetic Directive: ${instructions}\n\nNarrative Text:\n${chunk}` : chunk;

          const res = await ai.models.generateContent({
              model: 'gemini-2.5-flash-preview-tts', 
              contents: [{ parts: [{ text: ttsPrompt }] }],
              config: { responseModalities: [Modality.AUDIO], speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: baseVoice } } } },
          });

          if (res.candidates?.[0]?.finishReason === 'SAFETY') {
              // Automatic Safety Fallback Pass: Stripping SSML often bypasses false-positives in safety filters
              const stripped = chunk.replace(/<[^>]*>/g, '');
              const resRetry = await ai.models.generateContent({
                  model: 'gemini-2.5-flash-preview-tts', 
                  contents: [{ parts: [{ text: `Directive: Narrate this text clearly.\n\nText:\n${stripped}` }] }],
                  config: { responseModalities: [Modality.AUDIO], speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: baseVoice } } } },
              });
              const base64Retry = resRetry.candidates?.[0]?.content?.parts?.find(p => p.inlineData)?.inlineData?.data;
              if (base64Retry) audioParts.push(decode(base64Retry));
              else throw new Error(`Segment ${i+1} Blocked by Safety Filters.`);
          } else {
              const base64 = res.candidates?.[0]?.content?.parts?.find(p => p.inlineData)?.inlineData?.data;
              if (base64) audioParts.push(decode(base64));
          }
          await new Promise(r => setTimeout(r, 200));
        } catch (err: any) { throw new Error(`Segment ${i+1} Failed: ${err.message}`); }
      }

      if (audioParts.length === 0) throw new Error("No audio generated. Check script safety.");
      const concatenated = concatenateBuffers(audioParts);
      setAudioUrl(URL.createObjectURL(pcmToWavBlob(concatenated, 24000, 1)));
    } catch (err: any) { setError(err.message); } finally { setIsGenerating(false); }
  };

